#[tokio::main]
async fn main() {
    if let Err(error) = run().await {
        eprintln!("meshmine-node: {error}");
        process::exit(1);
    }
}

async fn run() -> Result<(), Box<dyn Error>> {
    let mut arguments = env::args().skip(1);
    let command = arguments.next().ok_or_else(usage)?;
    let arguments: Vec<_> = arguments.collect();
    validate_command_arguments(&command, &arguments)?;
    match command.as_str() {
        "cpu-mine" => cpu_mine(arguments),
        "research-mine-once" => research_mine_once(arguments),
        "verify-parent" => verify_parent(arguments),
        "overlay-init" => overlay_init(arguments),
        "overlay-serve" => overlay_serve(arguments).await,
        "overlay-audit" => overlay_audit(arguments),
        "overlay-observe" => overlay_observe(arguments),
        "active-receipt-migration-status" => active_receipt_migration_status(arguments),
        "active-receipt-migration-advance" => active_receipt_migration_advance(arguments),
        "journal-inventory" => journal_inventory(arguments),
        "overlay-put-response" => overlay_put_response(arguments),
        "overlay-fetch" => overlay_fetch(arguments).await,
        "overlay-gossip-operator" => overlay_gossip_operator(arguments).await,
        "overlay-gossip-parent" => overlay_gossip_parent(arguments).await,
        "overlay-gossip-object" => overlay_gossip_object(arguments).await,
        "committee-key-init" => committee_key_init(arguments),
        "receipt-propose" => receipt_propose(arguments),
        "receipt-sign" => receipt_sign(arguments),
        "receipt-assemble" => receipt_assemble(arguments),
        "payout-snapshot-propose" => payout_snapshot_propose(arguments),
        "payout-plan-propose" => payout_plan_propose(arguments),
        "settlement-sign" => settlement_sign(arguments),
        "settlement-assemble" => settlement_assemble(arguments),
        "share-context-import" => share_context_import(arguments),
        "overlay-sync-hns" => overlay_sync_hns(arguments),
        _ => Err(usage().into()),
    }
}

#[derive(Clone, Copy)]
struct CommandArgumentSchema {
    value_arguments: &'static [&'static str],
    boolean_flags: &'static [&'static str],
    repeatable_value_arguments: &'static [&'static str],
}

