#[derive(Clone)]
struct GossipForwardRouter {
    fast_path: mpsc::Sender<ForwardedGossip>,
    accounting: mpsc::Sender<ForwardedGossip>,
    availability: mpsc::Sender<ForwardedGossip>,
    settlement: mpsc::Sender<ForwardedGossip>,
}

struct GossipForwardReceivers {
    fast_path: mpsc::Receiver<ForwardedGossip>,
    accounting: mpsc::Receiver<ForwardedGossip>,
    availability: mpsc::Receiver<ForwardedGossip>,
    settlement: mpsc::Receiver<ForwardedGossip>,
}

impl GossipForwardRouter {
    fn bounded(per_lane_capacity: usize) -> (Self, GossipForwardReceivers) {
        let (fast_path_tx, fast_path_rx) = mpsc::channel(per_lane_capacity);
        let (accounting_tx, accounting_rx) = mpsc::channel(per_lane_capacity);
        let (availability_tx, availability_rx) = mpsc::channel(per_lane_capacity);
        let (settlement_tx, settlement_rx) = mpsc::channel(per_lane_capacity);
        (
            Self {
                fast_path: fast_path_tx,
                accounting: accounting_tx,
                availability: availability_tx,
                settlement: settlement_tx,
            },
            GossipForwardReceivers {
                fast_path: fast_path_rx,
                accounting: accounting_rx,
                availability: availability_rx,
                settlement: settlement_rx,
            },
        )
    }

    fn try_send(
        &self,
        forwarded: ForwardedGossip,
    ) -> Result<(), mpsc::error::TrySendError<ForwardedGossip>> {
        match forwarded.topic.protocol_lane() {
            ProtocolLane::FastPath => self.fast_path.try_send(forwarded),
            ProtocolLane::Accounting => self.accounting.try_send(forwarded),
            ProtocolLane::Availability => self.availability.try_send(forwarded),
            ProtocolLane::Settlement => self.settlement.try_send(forwarded),
        }
    }
}

