const GOSSIP_MIGRATION_OPERATOR: u8 = 1 << 0;
const GOSSIP_MIGRATION_PARENT: u8 = 1 << 1;
const GOSSIP_MIGRATION_SHARE: u8 = 1 << 2;
const GOSSIP_MIGRATION_RECEIPT: u8 = 1 << 3;
const GOSSIP_MIGRATION_PAYOUT: u8 = 1 << 4;
const GOSSIP_MIGRATION_ALL: u8 = GOSSIP_MIGRATION_OPERATOR
    | GOSSIP_MIGRATION_PARENT
    | GOSSIP_MIGRATION_SHARE
    | GOSSIP_MIGRATION_RECEIPT
    | GOSSIP_MIGRATION_PAYOUT;

impl Default for StaticPeerAcknowledgements {
    fn default() -> Self {
        Self {
            next_scan_sequence: 1,
            acknowledged: vec![],
        }
    }
}

impl GossipOutboxRecoveryProfile {
    const fn migration_mask(self) -> u8 {
        GOSSIP_MIGRATION_OPERATOR
            | if self.parent {
                GOSSIP_MIGRATION_PARENT
            } else {
                0
            }
            | if self.share {
                GOSSIP_MIGRATION_SHARE
            } else {
                0
            }
            | if self.receipt {
                GOSSIP_MIGRATION_RECEIPT
            } else {
                0
            }
            | if self.payout {
                GOSSIP_MIGRATION_PAYOUT
            } else {
                0
            }
    }

    const fn supports(self, topic: GossipTopic) -> bool {
        match topic {
            GossipTopic::Operator => true,
            GossipTopic::Parent => self.parent,
            GossipTopic::Share => self.share,
            GossipTopic::ReceiptBatch | GossipTopic::SessionClose => self.receipt,
            GossipTopic::PayoutSnapshot | GossipTopic::PayoutPlan => self.payout,
            _ => false,
        }
    }
}

