fn research_mine_once(arguments: Vec<String>) -> Result<(), Box<dyn Error>> {
    let config = parse_research_mine_config(&arguments)?;
    prepare_research_state_directory(&config.directory)?;
    let endpoint = validate_research_hsd_cli(&config.hsd_cli)?;
    let store = RedbStore::create(config.directory.join(RESEARCH_MINE_DATABASE))?;
    let oracle = HsdCliResearchMining {
        executable: config.hsd_cli.clone(),
        endpoint: endpoint.clone(),
    };
    match load_research_record::<ResearchEndpointRecord>(&store, "endpoint")? {
        Some(durable) => {
            validate_research_record_version(durable.record_version, "endpoint")?;
            if durable != endpoint {
                return Err(
                    "the configured hsd CLI no longer matches the durable research endpoint".into(),
                );
            }
        }
        None => {
            if !store
                .scan_namespace(
                    RESEARCH_MINE_NAMESPACE,
                    ScanLimits {
                        maximum_records: 32,
                        maximum_value_bytes: RESEARCH_MINE_MAX_RECORD_BYTES,
                        maximum_total_bytes: RESEARCH_MINE_MAX_RECORD_BYTES * 32,
                    },
                )?
                .is_empty()
            {
                return Err(
                    "legacy research state has no endpoint binding; use a fresh empty directory"
                        .into(),
                );
            }
            // Attest before binding the endpoint so an accidental mainnet
            // selection cannot poison an otherwise fresh research directory.
            attest_research_regtest_endpoint(&oracle)?;
            persist_research_record(&store, "endpoint", &endpoint)?;
        }
    }
    let outcome = run_research_mine_once(&config, &store, &oracle, None)?;
    println!("status=research-block-accepted");
    println!("network=regtest");
    println!("height={}", outcome.height);
    println!("block_hash={}", hex::encode(outcome.block_hash));
    println!("captures={}", outcome.capture_count);
    println!("acceptance_reason={}", outcome.acceptance_reason);
    println!("acceptance_scope=historical-durable-record");
    println!("production_eligible=false");
    println!("research_only=true");
    Ok(())
}

fn parse_research_mine_config(arguments: &[String]) -> Result<ResearchMineConfig, Box<dyn Error>> {
    let mut directory = None;
    let mut hsd_cli = None;
    let mut research_seed = None;
    let mut blind_band_bits = None;
    let mut nonce_limit = None;
    let mut maximum_captures = None;
    let mut acknowledged = false;
    let mut stock_regtest_compat = false;
    let mut index = 0;
    while index < arguments.len() {
        let name = arguments[index].as_str();
        match name {
            "--acknowledge-research-only-regtest" => {
                if acknowledged {
                    return Err("duplicate --acknowledge-research-only-regtest".into());
                }
                acknowledged = true;
                index += 1;
                continue;
            }
            "--stock-regtest-compat" => {
                if stock_regtest_compat {
                    return Err("duplicate --stock-regtest-compat".into());
                }
                stock_regtest_compat = true;
                index += 1;
                continue;
            }
            _ => {}
        }
        let value = arguments
            .get(index + 1)
            .ok_or_else(|| format!("missing value for {name}"))?;
        match name {
            "--dir" if directory.is_none() => directory = Some(PathBuf::from(value)),
            "--hsd-cli" if hsd_cli.is_none() => hsd_cli = Some(PathBuf::from(value)),
            "--research-seed" if research_seed.is_none() => {
                research_seed = Some(fixed_hex(value, "research seed")?)
            }
            "--blind-band-bits" if blind_band_bits.is_none() => {
                blind_band_bits = Some(value.parse::<u16>()?)
            }
            "--nonce-limit" if nonce_limit.is_none() => nonce_limit = Some(value.parse::<u32>()?),
            "--maximum-captures" if maximum_captures.is_none() => {
                maximum_captures = Some(value.parse::<usize>()?)
            }
            _ => return Err(format!("unknown or duplicate research mine argument: {name}").into()),
        }
        index += 2;
    }
    if !acknowledged {
        return Err(
            "research-mine-once requires --acknowledge-research-only-regtest before contacting hsd"
                .into(),
        );
    }
    let blind_band_bits = blind_band_bits.unwrap_or(if stock_regtest_compat { 0 } else { 1 });
    let nonce_limit = nonce_limit.unwrap_or(RESEARCH_MINE_DEFAULT_NONCE_LIMIT);
    let maximum_captures = maximum_captures.unwrap_or(RESEARCH_MINE_DEFAULT_MAXIMUM_CAPTURES);
    if blind_band_bits > 255
        || stock_regtest_compat != (blind_band_bits == 0)
        || nonce_limit == 0
        || nonce_limit > RESEARCH_MINE_MAXIMUM_NONCE_LIMIT
        || !(1..=RESEARCH_MINE_MAXIMUM_CAPTURES).contains(&maximum_captures)
    {
        return Err("research mining bounds are invalid".into());
    }
    Ok(ResearchMineConfig {
        directory: directory.ok_or("missing --dir")?,
        hsd_cli: hsd_cli.ok_or("missing --hsd-cli")?,
        research_seed: research_seed.ok_or("missing --research-seed")?,
        stock_regtest_compat,
        blind_band_bits,
        nonce_limit,
        maximum_captures,
    })
}

fn run_research_mine_once(
    config: &ResearchMineConfig,
    store: &dyn DurableStore,
    oracle: &dyn ResearchMiningHsd,
    stop_after: Option<ResearchMineStage>,
) -> Result<ResearchMineOutcome, Box<dyn Error>> {
    let terminal_accepted = load_research_record::<ResearchAcceptedRecord>(store, "accepted")?;
    let initial_attested_work = if terminal_accepted.is_none() {
        Some(attest_research_regtest_endpoint(oracle)?)
    } else {
        None
    };

    let work = match load_research_record::<ResearchWorkRecord>(store, "work")? {
        Some(work) => work,
        None => {
            if terminal_accepted.is_some() {
                return Err("accepted research session is missing durable work".into());
            }
            let response = decode_and_validate_research_work(
                initial_attested_work
                    .as_deref()
                    .ok_or("initial research endpoint attestation did not return work")?,
                config,
            )?;
            persist_research_record(store, "work", &response)?;
            research_stop_after(stop_after, ResearchMineStage::Work)?;
            response
        }
    };
    let (base_miner, capture_parameters) = validate_durable_research_work(&work, config)?;

    let member_keys = research_member_keys(&config.research_seed);
    let backend = ResearchVssBackend::new(store);
    let setup_request = SetupRequest {
        protocol_version: CORE_V2,
        network_id: 2,
        lane_id: 0,
        session_sequence: u64::from(work.height),
        parent_hash: base_miner.prev_block,
        leading_zero_prefix_q: capture_parameters.leading_zero_prefix_q,
        blind_band_bits_d: capture_parameters.blind_band_bits_d,
        threshold: 2,
        timed_open_after_ms: 0,
        deterministic_seed: domain_hash(
            "meshmine/research-mine-mask-seed/v2",
            &config.research_seed,
        ),
    };
    let validation_store = MemoryStore::default();
    let validation_backend = ResearchVssBackend::new(&validation_store);
    let expected_setup = validation_backend.setup(&setup_request, &member_keys)?;
    let setup = match load_research_record::<ResearchSetupRecord>(store, "setup")? {
        Some(record) => research_setup_from_record(&record)?,
        None => {
            if terminal_accepted.is_some() {
                return Err("accepted research session is missing durable setup".into());
            }
            let setup = backend.setup(&setup_request, &member_keys)?;
            let record = research_setup_record(&setup);
            persist_research_record(store, "setup", &record)?;
            research_stop_after(stop_after, ResearchMineStage::Setup)?;
            setup
        }
    };
    validate_research_setup(&setup, &base_miner, &capture_parameters, &member_keys)?;
    if setup != expected_setup {
        return Err("durable research MPC setup is not the deterministic seeded setup".into());
    }

    let mut committed_miner = base_miner.clone();
    committed_miner.mask_hash = setup.mask_hash;
    let captures = match load_research_record::<ResearchCapturesRecord>(store, "captures")? {
        Some(record) => record,
        None => {
            if terminal_accepted.is_some() {
                return Err("accepted research session is missing durable captures".into());
            }
            let record = collect_research_captures(
                &committed_miner,
                &capture_parameters.capture_target,
                config.nonce_limit,
                config.maximum_captures,
            )?;
            persist_research_record(store, "captures", &record)?;
            research_stop_after(stop_after, ResearchMineStage::Captures)?;
            record
        }
    };
    validate_research_captures(
        &captures,
        &committed_miner,
        &capture_parameters.capture_target,
        config.nonce_limit,
        config.maximum_captures,
    )?;

    let captures_bytes = encode_research_record(&captures)?;
    let expected_boundary = ResearchBoundaryRecord {
        record_version: RESEARCH_MINE_RECORD_VERSION,
        captures_hash: hex::encode(domain_hash(
            "meshmine/research-accepted-boundary/v2",
            &captures_bytes,
        )),
        capture_count: captures
            .captures
            .len()
            .try_into()
            .map_err(|_| "research capture count exceeds durable boundary encoding")?,
    };
    let boundary = match load_research_record::<ResearchBoundaryRecord>(store, "boundary")? {
        Some(record) => record,
        None => {
            if terminal_accepted.is_some() {
                return Err("accepted research session is missing durable boundary".into());
            }
            persist_research_record(store, "boundary", &expected_boundary)?;
            research_stop_after(stop_after, ResearchMineStage::Boundary)?;
            expected_boundary.clone()
        }
    };
    if boundary != expected_boundary {
        return Err("durable research accepted-share boundary does not match captures".into());
    }

    let opened = match load_research_record::<ResearchOpenedRecord>(store, "opened")? {
        Some(record) => research_opened_from_record(&record)?,
        None => {
            if terminal_accepted.is_some() {
                return Err("accepted research session is missing durable opened mask".into());
            }
            let opening_shares = setup
                .members
                .iter()
                .take(usize::from(setup.threshold))
                .map(|member| backend.load_opening(&setup.session_binding, member))
                .collect::<Result<Vec<_>, _>>()?;
            let opened = backend.timed_open(
                &setup,
                &opening_shares,
                &TimedOpeningGate {
                    phase: SessionPhase::Opening,
                    timed_open_after_ms: 0,
                    accepted_boundary_fixed: true,
                },
                0,
            )?;
            let record = research_opened_record(&opened);
            persist_research_record(store, "opened", &record)?;
            research_stop_after(stop_after, ResearchMineStage::Opened)?;
            opened
        }
    };
    validate_research_opened(&opened, &setup)?;
    let expected_opening_shares = expected_setup
        .members
        .iter()
        .take(usize::from(expected_setup.threshold))
        .map(|member| validation_backend.load_opening(&expected_setup.session_binding, member))
        .collect::<Result<Vec<_>, _>>()?;
    let expected_opened = validation_backend.timed_open(
        &expected_setup,
        &expected_opening_shares,
        &TimedOpeningGate {
            phase: SessionPhase::Opening,
            timed_open_after_ms: 0,
            accepted_boundary_fixed: true,
        },
        0,
    )?;
    if opened != expected_opened {
        return Err("durable research opening is not the deterministic seeded opening".into());
    }
    if terminal_accepted.is_none() {
        backend.retire_after_audit(&setup, &opened)?;
    }

    let accepted_shares = captures
        .captures
        .iter()
        .map(|capture| {
            Ok(AcceptedShareHash {
                share_id: fixed_hex(&capture.capture_id, "research capture ID")?,
                raw_share_hash: fixed_hex(&capture.raw_share_hash, "research raw share hash")?,
            })
        })
        .collect::<Result<Vec<_>, Box<dyn Error>>>()?;
    let winner_ids = evaluate_accepted_winners(
        &opened,
        &accepted_shares,
        &capture_parameters.network_target,
    );
    let winner_id = winner_ids
        .first()
        .ok_or("the fixed research capture boundary contains no winning share")?;
    let winning_capture = captures
        .captures
        .iter()
        .find(|capture| {
            fixed_hex::<32>(&capture.capture_id, "research capture ID")
                .is_ok_and(|capture_id| &capture_id == winner_id)
        })
        .ok_or("research winner is missing from the durable capture boundary")?;

    let mut winning_miner = committed_miner;
    winning_miner.nonce = winning_capture.nonce;
    let solved_header = hns_header_from_miner(&winning_miner, opened.mask);
    let block_hash = solved_header.pow_hash();
    if block_hash > capture_parameters.network_target {
        return Err("opened research winner does not satisfy the HNS network target".into());
    }
    let intent = ResearchSubmissionIntentRecord {
        record_version: RESEARCH_MINE_RECORD_VERSION,
        height: work.height,
        miner_data: hex::encode(winning_miner.to_bytes()),
        mask: hex::encode(opened.mask),
        expected_block_hash: hex::encode(block_hash),
    };
    let durable_intent =
        match load_research_record::<ResearchSubmissionIntentRecord>(store, "submission-intent")? {
            Some(record) => record,
            None => {
                if terminal_accepted.is_some() {
                    return Err(
                        "accepted research session is missing durable submission intent".into(),
                    );
                }
                persist_research_record(store, "submission-intent", &intent)?;
                research_stop_after(stop_after, ResearchMineStage::SubmissionIntent)?;
                intent.clone()
            }
        };
    if durable_intent != intent {
        return Err("durable research submission intent does not match the opened winner".into());
    }

    if let Some(accepted) = terminal_accepted {
        validate_research_record_version(accepted.record_version, "accepted")?;
        let accepted_hash = fixed_hex(&accepted.block_hash, "accepted research block hash")?;
        if accepted_hash != block_hash
            || accepted.block_hash != durable_intent.expected_block_hash
            || !matches!(accepted.reason.as_str(), "valid" | "confirmed-after-stale")
        {
            return Err(
                "accepted research record is inconsistent with the fully reconstructed submission"
                    .into(),
            );
        }
        return Ok(ResearchMineOutcome {
            height: work.height,
            block_hash,
            capture_count: captures.captures.len(),
            acceptance_reason: accepted.reason,
        });
    }

    // Re-attest the endpoint immediately before every write attempt. A caller
    // cannot resume a stored regtest session with --hsd-cli pointed at mainnet.
    attest_research_regtest_endpoint(oracle)?;
    let miner_data: [u8; meshmine_hns::MINER_HEADER_SIZE] =
        fixed_hex(&durable_intent.miner_data, "research miner submission data")?;
    let mask = fixed_hex(&durable_intent.mask, "research opened mask")?;
    let (accepted, reason) = oracle.submit_work(&miner_data, &mask)?;
    research_stop_after(stop_after, ResearchMineStage::Submitted)?;
    let acceptance_reason = if accepted && reason == "valid" {
        "valid".to_owned()
    } else if !accepted && reason == "stale" {
        let canonical = oracle.block_hash_at(work.height)?;
        if canonical != block_hash {
            return Err(
                "hsd reported stale research work but the expected block is not canonical".into(),
            );
        }
        "confirmed-after-stale".to_owned()
    } else {
        return Err(
            format!("hsd rejected research work: accepted={accepted}, reason={reason}").into(),
        );
    };
    let accepted_record = ResearchAcceptedRecord {
        record_version: RESEARCH_MINE_RECORD_VERSION,
        block_hash: hex::encode(block_hash),
        reason: acceptance_reason.clone(),
    };
    persist_research_record(store, "accepted", &accepted_record)?;
    research_stop_after(stop_after, ResearchMineStage::Accepted)?;
    Ok(ResearchMineOutcome {
        height: work.height,
        block_hash,
        capture_count: captures.captures.len(),
        acceptance_reason,
    })
}

fn decode_hsd_submitwork_result(output: &[u8]) -> Result<(bool, String), Box<dyn Error>> {
    let result: (bool, String) = serde_json::from_slice(output)?;
    Ok(result)
}

fn encode_hsd_rpc_bytes_argument(bytes: &[u8]) -> Result<String, serde_json::Error> {
    serde_json::to_string(&hex::encode(bytes))
}

fn decode_hsd_hash_output(output: &[u8]) -> Result<Hash256, Box<dyn Error>> {
    let text = std::str::from_utf8(output)?.trim();
    let value = serde_json::from_str::<String>(text).unwrap_or_else(|_| text.to_owned());
    fixed_hex(&value, "canonical HNS block hash")
}

fn decode_and_validate_research_work(
    output: &[u8],
    config: &ResearchMineConfig,
) -> Result<ResearchWorkRecord, Box<dyn Error>> {
    let work: HsdResearchWorkJson = serde_json::from_slice(output)?;
    let record = ResearchWorkRecord {
        record_version: RESEARCH_MINE_RECORD_VERSION,
        network: work.network,
        data: work.data,
        target: work.target,
        height: work.height,
        time: work.time,
    };
    validate_durable_research_work(&record, config)?;
    Ok(record)
}

fn validate_durable_research_work(
    work: &ResearchWorkRecord,
    config: &ResearchMineConfig,
) -> Result<(MinerHeader, meshmine_hns::CaptureParameters), Box<dyn Error>> {
    validate_research_record_version(work.record_version, "work")?;
    if work.network != "regtest" {
        return Err(format!(
            "research-mine-once refuses non-regtest hsd network {:?}; mainnet/live production is forbidden",
            work.network
        )
        .into());
    }
    let data: [u8; meshmine_hns::MINER_HEADER_SIZE] =
        fixed_hex(&work.data, "hsd getwork miner data")?;
    let miner = MinerHeader::from_bytes(&data)?;
    let parameters = if config.stock_regtest_compat {
        if config.blind_band_bits != 0 || miner.bits != RESEARCH_MINE_STOCK_REGTEST_BITS {
            return Err(format!(
                "stock regtest compatibility requires bits=0x{RESEARCH_MINE_STOCK_REGTEST_BITS:08x} and d=0"
            )
            .into());
        }
        let mut network_target = [0; 32];
        network_target[..3].copy_from_slice(&[0x7f, 0xff, 0xff]);
        let mut capture_target = [0xff; 32];
        capture_target[0] = 0x7f;
        CaptureParameters {
            network_target,
            leading_zero_bits_p: 1,
            leading_zero_prefix_q: 1,
            blind_band_bits_d: 0,
            capture_target,
        }
    } else {
        if config.blind_band_bits == 0 {
            return Err("d=0 requires the explicit stock regtest compatibility profile".into());
        }
        derive_capture_parameters(miner.bits, config.blind_band_bits).map_err(|error| {
            format!(
                "isolated regtest target cannot support blind-band d={}: {error}",
                config.blind_band_bits
            )
        })?
    };
    let reported_target: Hash256 = fixed_hex(&work.target, "hsd getwork target")?;
    if reported_target != parameters.network_target {
        return Err("hsd getwork target does not match the serialized compact target".into());
    }
    let zero_mask = [0; 32];
    if miner.mask_hash != blake2b_256(&[&miner.prev_block, &zero_mask]) {
        return Err(
            "research getwork must use hsd's zero-mask template before MPC commitment".into(),
        );
    }
    Ok((miner, parameters))
}

fn attest_research_regtest_endpoint(
    oracle: &dyn ResearchMiningHsd,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let response = oracle.get_work()?;
    let work: HsdResearchWorkJson = serde_json::from_slice(&response)?;
    if work.network != "regtest" {
        return Err(format!(
            "research submission refused: current hsd endpoint is {:?}, not regtest",
            work.network
        )
        .into());
    }
    let genesis = oracle.block_hash_at(0)?;
    if genesis != RESEARCH_MINE_REGTEST_GENESIS {
        return Err(format!(
            "research submission refused: endpoint genesis {} is not the hsd regtest genesis",
            hex::encode(genesis)
        )
        .into());
    }
    Ok(response)
}

fn research_member_keys(seed: &Hash256) -> Vec<SigningKey> {
    (0..3u8)
        .map(|index| {
            let mut body = [0; 33];
            body[..32].copy_from_slice(seed);
            body[32] = index;
            SigningKey::from_bytes(&domain_hash("meshmine/research-mine-member-key/v2", &body))
        })
        .collect()
}

fn research_setup_record(setup: &ResearchSetup) -> ResearchSetupRecord {
    ResearchSetupRecord {
        record_version: RESEARCH_MINE_RECORD_VERSION,
        session_binding: hex::encode(setup.session_binding),
        parent_hash: hex::encode(setup.parent_hash),
        mask_hash: hex::encode(setup.mask_hash),
        mask_commitment_root: hex::encode(setup.mask_commitment_root),
        transcript_root: hex::encode(setup.transcript_root),
        leading_zero_prefix_q: setup.leading_zero_prefix_q,
        blind_band_bits_d: setup.blind_band_bits_d,
        threshold: setup.threshold,
        timed_open_after_ms: setup.timed_open_after_ms,
        members: setup.members.iter().map(hex::encode).collect(),
        share_commitments: setup.share_commitments.iter().map(hex::encode).collect(),
    }
}

fn research_setup_from_record(
    record: &ResearchSetupRecord,
) -> Result<ResearchSetup, Box<dyn Error>> {
    validate_research_record_version(record.record_version, "setup")?;
    Ok(ResearchSetup {
        session_binding: fixed_hex(&record.session_binding, "research session binding")?,
        parent_hash: fixed_hex(&record.parent_hash, "research setup parent hash")?,
        mask_hash: fixed_hex(&record.mask_hash, "research mask hash")?,
        mask_commitment_root: fixed_hex(
            &record.mask_commitment_root,
            "research mask commitment root",
        )?,
        transcript_root: fixed_hex(&record.transcript_root, "research setup transcript root")?,
        leading_zero_prefix_q: record.leading_zero_prefix_q,
        blind_band_bits_d: record.blind_band_bits_d,
        threshold: record.threshold,
        timed_open_after_ms: record.timed_open_after_ms,
        members: record
            .members
            .iter()
            .map(|member| fixed_hex(member, "research setup member"))
            .collect::<Result<Vec<_>, _>>()?,
        share_commitments: record
            .share_commitments
            .iter()
            .map(|commitment| fixed_hex(commitment, "research opening share commitment"))
            .collect::<Result<Vec<_>, _>>()?,
    })
}

fn validate_research_setup(
    setup: &ResearchSetup,
    miner: &MinerHeader,
    parameters: &meshmine_hns::CaptureParameters,
    member_keys: &[SigningKey],
) -> Result<(), Box<dyn Error>> {
    let mut expected_members: Vec<_> = member_keys
        .iter()
        .map(|key| key.verifying_key().to_bytes())
        .collect();
    expected_members.sort();
    if setup.parent_hash != miner.prev_block
        || setup.leading_zero_prefix_q != parameters.leading_zero_prefix_q
        || setup.blind_band_bits_d != parameters.blind_band_bits_d
        || setup.threshold != 2
        || setup.timed_open_after_ms != 0
        || setup.members != expected_members
        || setup.share_commitments.len() != setup.members.len()
        || meshmine_hns::merkle_root(&setup.share_commitments) != setup.mask_commitment_root
    {
        return Err("durable research MPC setup does not match the regtest mining session".into());
    }
    Ok(())
}

fn collect_research_captures(
    miner: &MinerHeader,
    capture_target: &Hash256,
    nonce_limit: u32,
    maximum_captures: usize,
) -> Result<ResearchCapturesRecord, Box<dyn Error>> {
    validate_research_capture_bounds(nonce_limit, maximum_captures)?;
    let mut candidate = miner.clone();
    let mut captures = Vec::new();
    for nonce in 0..nonce_limit {
        candidate.nonce = nonce;
        let raw_share_hash = candidate.share_hash();
        if raw_share_hash <= *capture_target {
            let capture_id = domain_hash("meshmine/research-capture/v2", &candidate.to_bytes());
            captures.push(ResearchCaptureEntry {
                capture_id: hex::encode(capture_id),
                nonce,
                raw_share_hash: hex::encode(raw_share_hash),
            });
            if captures.len() == maximum_captures {
                break;
            }
        }
    }
    if captures.is_empty() {
        return Err(format!(
            "no research capture found in {nonce_limit} deterministic nonce candidates"
        )
        .into());
    }
    Ok(ResearchCapturesRecord {
        record_version: RESEARCH_MINE_RECORD_VERSION,
        nonce_limit,
        maximum_captures: maximum_captures
            .try_into()
            .map_err(|_| "research maximum capture count exceeds its durable encoding")?,
        captures,
    })
}

fn validate_research_capture_bounds(
    nonce_limit: u32,
    maximum_captures: usize,
) -> Result<(), Box<dyn Error>> {
    if !(1..=RESEARCH_MINE_MAXIMUM_NONCE_LIMIT).contains(&nonce_limit)
        || !(1..=RESEARCH_MINE_MAXIMUM_CAPTURES).contains(&maximum_captures)
    {
        return Err("research capture bounds are outside their hard limits".into());
    }
    Ok(())
}

fn validate_research_captures(
    record: &ResearchCapturesRecord,
    miner: &MinerHeader,
    capture_target: &Hash256,
    nonce_limit: u32,
    maximum_captures: usize,
) -> Result<(), Box<dyn Error>> {
    validate_research_record_version(record.record_version, "captures")?;
    validate_research_capture_bounds(nonce_limit, maximum_captures)?;
    validate_research_capture_bounds(record.nonce_limit, usize::from(record.maximum_captures))?;
    if record.nonce_limit != nonce_limit || usize::from(record.maximum_captures) != maximum_captures
    {
        return Err("durable research capture bounds do not match this restart".into());
    }
    let expected = collect_research_captures(miner, capture_target, nonce_limit, maximum_captures)?;
    if record != &expected {
        return Err(
            "durable research captures are not the exact deterministic bounded nonce scan".into(),
        );
    }
    Ok(())
}

fn research_opened_record(opened: &OpenedMask) -> ResearchOpenedRecord {
    ResearchOpenedRecord {
        record_version: RESEARCH_MINE_RECORD_VERSION,
        mask: hex::encode(opened.mask),
        opening_transcript_root: hex::encode(opened.opening_transcript_root),
        valid_opening_members: opened
            .valid_opening_members
            .iter()
            .map(hex::encode)
            .collect(),
    }
}

fn research_opened_from_record(
    record: &ResearchOpenedRecord,
) -> Result<OpenedMask, Box<dyn Error>> {
    validate_research_record_version(record.record_version, "opened")?;
    Ok(OpenedMask {
        mask: fixed_hex(&record.mask, "research opened mask")?,
        opening_transcript_root: fixed_hex(
            &record.opening_transcript_root,
            "research opening transcript root",
        )?,
        valid_opening_members: record
            .valid_opening_members
            .iter()
            .map(|member| fixed_hex(member, "research valid opening member"))
            .collect::<Result<Vec<_>, _>>()?,
    })
}

fn validate_research_opened(
    opened: &OpenedMask,
    setup: &ResearchSetup,
) -> Result<(), Box<dyn Error>> {
    let blind_end = setup
        .leading_zero_prefix_q
        .checked_add(setup.blind_band_bits_d)
        .filter(|end| *end <= 256)
        .ok_or("research mask constraints overflow")?;
    let bit = |index: u16| {
        let byte = usize::from(index / 8);
        let shift = 7 - (index % 8);
        opened.mask[byte] & (1 << shift) != 0
    };
    let unique_members: BTreeSet<_> = opened.valid_opening_members.iter().collect();
    let required_nonzero = if setup.blind_band_bits_d == 0 {
        setup.leading_zero_prefix_q == 1 && (setup.leading_zero_prefix_q..256).any(bit)
    } else {
        (setup.leading_zero_prefix_q..blind_end).any(bit)
    };
    if blake2b_256(&[&setup.parent_hash, &opened.mask]) != setup.mask_hash
        || (0..setup.leading_zero_prefix_q).any(bit)
        || !required_nonzero
        || opened.valid_opening_members.len() < usize::from(setup.threshold)
        || unique_members.len() != opened.valid_opening_members.len()
        || opened
            .valid_opening_members
            .iter()
            .any(|member| !setup.members.contains(member))
    {
        return Err("durable research mask opening does not match the committed setup".into());
    }
    Ok(())
}

fn hns_header_from_miner(miner: &MinerHeader, mask: Hash256) -> HnsHeader {
    HnsHeader {
        nonce: miner.nonce,
        time: miner.time,
        prev_block: miner.prev_block,
        tree_root: miner.tree_root,
        extra_nonce: miner.extra_nonce,
        reserved_root: miner.reserved_root,
        witness_root: miner.witness_root,
        merkle_root: miner.merkle_root,
        version: miner.version,
        bits: miner.bits,
        mask,
    }
}

fn validate_research_record_version(version: u16, label: &str) -> Result<(), Box<dyn Error>> {
    if version != RESEARCH_MINE_RECORD_VERSION {
        return Err(format!(
            "unsupported {label} research record version {version}; expected {RESEARCH_MINE_RECORD_VERSION}"
        )
        .into());
    }
    Ok(())
}

fn encode_research_record<T: Serialize>(record: &T) -> Result<Vec<u8>, Box<dyn Error>> {
    let bytes = serde_json::to_vec(record)?;
    if bytes.len() as u64 > RESEARCH_MINE_MAX_RECORD_BYTES {
        return Err("research mining record exceeds the durable size limit".into());
    }
    Ok(bytes)
}

fn persist_research_record<T: Serialize>(
    store: &dyn DurableStore,
    key: &str,
    record: &T,
) -> Result<(), Box<dyn Error>> {
    let bytes = encode_research_record(record)?;
    if !store.put_if_absent(RESEARCH_MINE_NAMESPACE, key, &bytes)?
        && store.get(RESEARCH_MINE_NAMESPACE, key)?.as_deref() != Some(bytes.as_slice())
    {
        return Err(format!("durable research record {key:?} already has different bytes").into());
    }
    Ok(())
}

fn load_research_record<T: for<'de> Deserialize<'de>>(
    store: &dyn DurableStore,
    key: &str,
) -> Result<Option<T>, Box<dyn Error>> {
    let Some(bytes) = store.get(RESEARCH_MINE_NAMESPACE, key)? else {
        return Ok(None);
    };
    if bytes.len() as u64 > RESEARCH_MINE_MAX_RECORD_BYTES {
        return Err(format!("durable research record {key:?} exceeds the size limit").into());
    }
    Ok(Some(serde_json::from_slice(&bytes)?))
}

fn research_stop_after(
    requested: Option<ResearchMineStage>,
    reached: ResearchMineStage,
) -> Result<(), Box<dyn Error>> {
    if requested == Some(reached) {
        return Err(format!("research test stop after {}", reached.label()).into());
    }
    Ok(())
}

