struct HardenedHsdCliInspection {
    identity: HardenedHsdCliIdentity,
    file: fs::File,
}

struct HardenedHsdSourceInspection {
    identity: HardenedHsdSourceIdentity,
    directory: fs::File,
}

struct HardenedHsdSourceInvocation {
    adapter_path: PathBuf,
    retained_descriptor: Option<fs::File>,
}

impl HardenedHsdCli {
    fn validate(path: &Path) -> Result<Self, Box<dyn Error>> {
        Ok(Self {
            identity: inspect_hardened_hsd_cli(path)?.identity,
        })
    }

    fn reattest(&self) -> Result<fs::File, Box<dyn Error>> {
        let current = inspect_hardened_hsd_cli(&self.identity.canonical_path)?;
        if current.identity != self.identity {
            return Err("hsd CLI identity changed after startup validation".into());
        }
        Ok(current.file)
    }

    fn spawn_query(&self, arguments: &[String]) -> Result<std::process::Child, Box<dyn Error>> {
        use std::process::Stdio;

        let executable = self.reattest()?;
        #[cfg(unix)]
        let inherited = duplicate_inheritable_descriptor(&executable)?;
        #[cfg(unix)]
        let spawn_path = {
            use std::os::fd::AsRawFd;

            let descriptor = inherited.as_raw_fd();
            #[cfg(target_os = "linux")]
            let path = PathBuf::from(format!("/proc/self/fd/{descriptor}"));
            #[cfg(not(target_os = "linux"))]
            let path = PathBuf::from(format!("/dev/fd/{descriptor}"));
            path
        };
        #[cfg(not(unix))]
        let spawn_path = self.identity.canonical_path.clone();

        let mut command = Command::new(spawn_path);
        command
            .args(arguments)
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::null());
        #[cfg(unix)]
        {
            use std::os::unix::process::CommandExt;

            command.process_group(0);
        }
        let child = command.spawn()?;
        // The child inherited a non-CLOEXEC duplicate. Keeping it open through
        // `spawn` lets a shebang interpreter reopen the exact validated inode.
        #[cfg(unix)]
        drop(inherited);
        drop(executable);
        Ok(child)
    }
}

impl HardenedHsdSource {
    fn validate(path: &Path) -> Result<Self, Box<dyn Error>> {
        Ok(Self {
            identity: inspect_hardened_hsd_source(path)?.identity,
        })
    }

    fn reattest(&self) -> Result<fs::File, Box<dyn Error>> {
        let current = inspect_hardened_hsd_source(&self.identity.canonical_path)?;
        if current.identity != self.identity {
            return Err("hsd source directory identity changed after startup validation".into());
        }
        Ok(current.directory)
    }

    fn prepare_adapter_invocation(&self) -> Result<HardenedHsdSourceInvocation, Box<dyn Error>> {
        let directory = self.reattest()?;
        #[cfg(unix)]
        {
            use std::os::fd::AsRawFd;

            let inherited = duplicate_inheritable_descriptor(&directory)?;
            let descriptor = inherited.as_raw_fd();
            #[cfg(target_os = "linux")]
            let adapter_path = PathBuf::from(format!("/proc/self/fd/{descriptor}"));
            #[cfg(not(target_os = "linux"))]
            let adapter_path = PathBuf::from(format!("/dev/fd/{descriptor}"));
            Ok(HardenedHsdSourceInvocation {
                adapter_path,
                retained_descriptor: Some(fs::File::from(inherited)),
            })
        }
        #[cfg(not(unix))]
        {
            Ok(HardenedHsdSourceInvocation {
                adapter_path: self.identity.canonical_path.clone(),
                retained_descriptor: Some(directory),
            })
        }
    }
}

fn inspect_hardened_hsd_cli(path: &Path) -> Result<HardenedHsdCliInspection, Box<dyn Error>> {
    if !path.is_absolute() {
        return Err("hsd CLI path must be absolute".into());
    }
    let canonical_path = fs::canonicalize(path)?;
    if canonical_path != path {
        return Err("hsd CLI path and every ancestor must be canonical and non-symlink".into());
    }

    #[cfg(unix)]
    let mut file = open_hardened_hsd_cli_unix(path)?;
    #[cfg(not(unix))]
    let mut file = {
        let metadata = fs::symlink_metadata(path)?;
        if metadata.file_type().is_symlink() || !metadata.is_file() {
            return Err("hsd CLI must be a regular file, not a symlink".into());
        }
        fs::File::open(path)?
    };

    let opened = file.metadata()?;
    if !opened.is_file() {
        return Err("hsd CLI must be a regular file".into());
    }
    #[cfg(unix)]
    validate_hardened_hsd_cli_leaf(&opened)?;

    let mut bytes = Vec::new();
    (&mut file)
        .take(HSD_CLI_MAX_EXECUTABLE_BYTES.saturating_add(1))
        .read_to_end(&mut bytes)?;
    if bytes.len() as u64 > HSD_CLI_MAX_EXECUTABLE_BYTES {
        return Err("hsd CLI exceeds the executable size bound".into());
    }
    let hashed = file.metadata()?;
    #[cfg(unix)]
    if !same_hardened_hsd_metadata(&opened, &hashed) {
        return Err("hsd CLI changed while it was being hashed".into());
    }

    let final_path = fs::symlink_metadata(path)?;
    if final_path.file_type().is_symlink() || !final_path.is_file() {
        return Err("hsd CLI path changed during validation".into());
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;

        if final_path.dev() != opened.dev() || final_path.ino() != opened.ino() {
            return Err("hsd CLI path changed during descriptor validation".into());
        }
    }
    if fs::canonicalize(path)? != canonical_path {
        return Err("hsd CLI canonical path changed during validation".into());
    }

    Ok(HardenedHsdCliInspection {
        identity: HardenedHsdCliIdentity {
            canonical_path,
            executable_hash: blake2b_256(&[&bytes]),
            executable_bytes: bytes.len() as u64,
            #[cfg(unix)]
            device: {
                use std::os::unix::fs::MetadataExt;
                opened.dev()
            },
            #[cfg(unix)]
            inode: {
                use std::os::unix::fs::MetadataExt;
                opened.ino()
            },
            #[cfg(unix)]
            owner: {
                use std::os::unix::fs::MetadataExt;
                opened.uid()
            },
            #[cfg(unix)]
            mode: {
                use std::os::unix::fs::PermissionsExt;
                opened.permissions().mode() & 0o7777
            },
            #[cfg(unix)]
            modified_seconds: {
                use std::os::unix::fs::MetadataExt;
                opened.mtime()
            },
            #[cfg(unix)]
            modified_nanoseconds: {
                use std::os::unix::fs::MetadataExt;
                opened.mtime_nsec()
            },
            #[cfg(unix)]
            changed_seconds: {
                use std::os::unix::fs::MetadataExt;
                opened.ctime()
            },
            #[cfg(unix)]
            changed_nanoseconds: {
                use std::os::unix::fs::MetadataExt;
                opened.ctime_nsec()
            },
        },
        file,
    })
}

fn inspect_hardened_hsd_source(path: &Path) -> Result<HardenedHsdSourceInspection, Box<dyn Error>> {
    if !path.is_absolute() || path.parent().is_none() {
        return Err("hsd source path must be an absolute, non-root directory".into());
    }
    let canonical_path = fs::canonicalize(path)?;
    if canonical_path != path {
        return Err("hsd source path and every ancestor must be canonical and non-symlink".into());
    }

    #[cfg(unix)]
    let directory = open_hardened_hsd_source_unix(path)?;
    #[cfg(not(unix))]
    let directory = {
        let metadata = fs::symlink_metadata(path)?;
        if metadata.file_type().is_symlink() || !metadata.is_dir() {
            return Err("hsd source must be a real directory, not a symlink".into());
        }
        fs::File::open(path)?
    };
    let opened = directory.metadata()?;
    if !opened.is_dir() {
        return Err("hsd source must be a directory".into());
    }
    #[cfg(unix)]
    validate_hardened_hsd_source_leaf(&opened)?;

    let final_path = fs::symlink_metadata(path)?;
    if final_path.file_type().is_symlink() || !final_path.is_dir() {
        return Err("hsd source path changed during validation".into());
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;

        if final_path.dev() != opened.dev() || final_path.ino() != opened.ino() {
            return Err("hsd source path changed during descriptor validation".into());
        }
    }
    if fs::canonicalize(path)? != canonical_path {
        return Err("hsd source canonical path changed during validation".into());
    }

    Ok(HardenedHsdSourceInspection {
        identity: HardenedHsdSourceIdentity {
            canonical_path,
            #[cfg(unix)]
            device: {
                use std::os::unix::fs::MetadataExt;
                opened.dev()
            },
            #[cfg(unix)]
            inode: {
                use std::os::unix::fs::MetadataExt;
                opened.ino()
            },
            #[cfg(unix)]
            owner: {
                use std::os::unix::fs::MetadataExt;
                opened.uid()
            },
            #[cfg(unix)]
            mode: {
                use std::os::unix::fs::PermissionsExt;
                opened.permissions().mode() & 0o7777
            },
            #[cfg(unix)]
            modified_seconds: {
                use std::os::unix::fs::MetadataExt;
                opened.mtime()
            },
            #[cfg(unix)]
            modified_nanoseconds: {
                use std::os::unix::fs::MetadataExt;
                opened.mtime_nsec()
            },
            #[cfg(unix)]
            changed_seconds: {
                use std::os::unix::fs::MetadataExt;
                opened.ctime()
            },
            #[cfg(unix)]
            changed_nanoseconds: {
                use std::os::unix::fs::MetadataExt;
                opened.ctime_nsec()
            },
        },
        directory,
    })
}

#[cfg(unix)]
fn open_hardened_hsd_cli_unix(path: &Path) -> Result<fs::File, Box<dyn Error>> {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;
    use std::os::unix::fs::OpenOptionsExt;
    use std::path::Component;

    let mut names = Vec::new();
    for component in path.components() {
        match component {
            Component::RootDir => {}
            Component::Normal(name) => names.push(CString::new(name.as_bytes())?),
            Component::CurDir | Component::ParentDir => {
                return Err("hsd CLI path contains a noncanonical directory component".into());
            }
            Component::Prefix(_) => return Err("hsd CLI path prefix is unsupported".into()),
        }
    }
    let (leaf, ancestor_names) = names
        .split_last()
        .ok_or("hsd CLI path must name an executable file")?;
    let root = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_DIRECTORY | libc::O_NOFOLLOW | libc::O_CLOEXEC)
        .open("/")?;
    validate_hardened_hsd_ancestor(&root, Path::new("/"))?;
    let mut ancestors = vec![root];
    let mut display = PathBuf::from("/");
    for name in ancestor_names {
        let parent = ancestors
            .last()
            .ok_or("hsd CLI descriptor traversal lost its parent")?;
        let directory = openat_hardened_hsd(
            parent,
            name,
            libc::O_RDONLY | libc::O_DIRECTORY | libc::O_NOFOLLOW | libc::O_CLOEXEC,
        )?;
        display.push(std::ffi::OsStr::from_bytes(name.to_bytes()));
        validate_hardened_hsd_ancestor(&directory, &display)?;
        ancestors.push(directory);
    }
    let parent = ancestors
        .last()
        .ok_or("hsd CLI descriptor traversal lost its leaf parent")?;
    openat_hardened_hsd(
        parent,
        leaf,
        libc::O_RDONLY | libc::O_NOFOLLOW | libc::O_CLOEXEC | libc::O_NONBLOCK | libc::O_NOCTTY,
    )
}

#[cfg(unix)]
fn open_hardened_hsd_source_unix(path: &Path) -> Result<fs::File, Box<dyn Error>> {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;
    use std::os::unix::fs::OpenOptionsExt;
    use std::path::Component;

    let mut names = Vec::new();
    for component in path.components() {
        match component {
            Component::RootDir => {}
            Component::Normal(name) => names.push(CString::new(name.as_bytes())?),
            Component::CurDir | Component::ParentDir => {
                return Err("hsd source path contains a noncanonical directory component".into());
            }
            Component::Prefix(_) => return Err("hsd source path prefix is unsupported".into()),
        }
    }
    if names.is_empty() {
        return Err("hsd source path must name a non-root directory".into());
    }

    let root = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_DIRECTORY | libc::O_NOFOLLOW | libc::O_CLOEXEC)
        .open("/")?;
    validate_hardened_hsd_ancestor(&root, Path::new("/"))?;
    let mut current = root;
    let mut display = PathBuf::from("/");
    for (index, name) in names.iter().enumerate() {
        let directory = openat_hardened_hsd(
            &current,
            name,
            libc::O_RDONLY | libc::O_DIRECTORY | libc::O_NOFOLLOW | libc::O_CLOEXEC,
        )?;
        display.push(std::ffi::OsStr::from_bytes(name.to_bytes()));
        if index + 1 == names.len() {
            validate_hardened_hsd_source_leaf(&directory.metadata()?)?;
        } else {
            validate_hardened_hsd_ancestor(&directory, &display)?;
        }
        current = directory;
    }
    Ok(current)
}

#[cfg(unix)]
fn openat_hardened_hsd(
    parent: &fs::File,
    name: &std::ffi::CStr,
    flags: libc::c_int,
) -> Result<fs::File, Box<dyn Error>> {
    use std::os::fd::{AsRawFd, FromRawFd, OwnedFd};

    // SAFETY: `parent` and the NUL-terminated `name` remain live for the call;
    // a successful descriptor is transferred immediately to `OwnedFd`.
    let descriptor = unsafe { libc::openat(parent.as_raw_fd(), name.as_ptr(), flags) };
    if descriptor < 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    // SAFETY: `openat` returned a new descriptor that has no other owner.
    let descriptor = unsafe { OwnedFd::from_raw_fd(descriptor) };
    Ok(fs::File::from(descriptor))
}

#[cfg(unix)]
fn validate_hardened_hsd_ancestor(directory: &fs::File, path: &Path) -> Result<(), Box<dyn Error>> {
    use std::os::unix::fs::PermissionsExt;

    let metadata = directory.metadata()?;
    if !metadata.is_dir() {
        return Err(format!("hsd CLI ancestor {} is not a directory", path.display()).into());
    }
    let mode = metadata.permissions().mode();
    if mode & 0o022 != 0 && mode & libc::S_ISVTX == 0 {
        return Err(format!(
            "hsd CLI ancestor {} is group/world writable without the sticky bit",
            path.display()
        )
        .into());
    }
    Ok(())
}

#[cfg(unix)]
fn validate_hardened_hsd_source_leaf(metadata: &fs::Metadata) -> Result<(), Box<dyn Error>> {
    use std::os::unix::fs::{MetadataExt, PermissionsExt};

    if !metadata.is_dir() {
        return Err("hsd source must be a directory".into());
    }
    if metadata.permissions().mode() & 0o022 != 0 {
        return Err("hsd source must not be writable by group or other".into());
    }
    // SAFETY: `geteuid` has no arguments and only reads process credentials.
    let effective_user = unsafe { libc::geteuid() };
    if metadata.uid() != effective_user && metadata.uid() != 0 {
        return Err("hsd source must be owned by the effective user or root".into());
    }
    Ok(())
}

#[cfg(unix)]
fn validate_hardened_hsd_cli_leaf(metadata: &fs::Metadata) -> Result<(), Box<dyn Error>> {
    use std::os::unix::fs::{MetadataExt, PermissionsExt};

    let mode = metadata.permissions().mode();
    if mode & 0o111 == 0 {
        return Err("hsd CLI is not executable".into());
    }
    if mode & 0o022 != 0 {
        return Err("hsd CLI must not be writable by group or other".into());
    }
    // SAFETY: `geteuid` has no arguments and only reads process credentials.
    let effective_user = unsafe { libc::geteuid() };
    if metadata.uid() != effective_user && metadata.uid() != 0 {
        return Err("hsd CLI must be owned by the effective user or root".into());
    }
    Ok(())
}

#[cfg(unix)]
fn same_hardened_hsd_metadata(left: &fs::Metadata, right: &fs::Metadata) -> bool {
    use std::os::unix::fs::{MetadataExt, PermissionsExt};

    left.dev() == right.dev()
        && left.ino() == right.ino()
        && left.uid() == right.uid()
        && left.len() == right.len()
        && left.permissions().mode() == right.permissions().mode()
        && left.mtime() == right.mtime()
        && left.mtime_nsec() == right.mtime_nsec()
        && left.ctime() == right.ctime()
        && left.ctime_nsec() == right.ctime_nsec()
}

#[cfg(unix)]
fn duplicate_inheritable_descriptor(
    file: &fs::File,
) -> Result<std::os::fd::OwnedFd, Box<dyn Error>> {
    use std::os::fd::{AsRawFd, FromRawFd, OwnedFd};

    // SAFETY: `file` owns a valid descriptor. `F_DUPFD` returns a distinct
    // descriptor without `FD_CLOEXEC`, which the spawned shebang interpreter
    // must inherit until it has reopened `/proc/self/fd/N` or `/dev/fd/N`.
    let descriptor = unsafe { libc::fcntl(file.as_raw_fd(), libc::F_DUPFD, 3) };
    if descriptor < 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    // SAFETY: `fcntl(F_DUPFD)` returned a new descriptor with no other owner.
    Ok(unsafe { OwnedFd::from_raw_fd(descriptor) })
}

struct HsdCliParentOracle {
    executable: HardenedHsdCli,
    cache: Mutex<HashMap<(Hash256, Hash256), bool>>,
}

impl ParentChainOracle for HsdCliParentOracle {
    fn verify_header_and_chainwork(&self, certificate: &SessionParentCertificateV2) -> bool {
        let certificate_id = certificate.object_id();
        let Some(tip_hash) = bounded_hsd_best_hash_query(&self.executable) else {
            return false;
        };
        let cache_key = (certificate_id, tip_hash);
        if let Ok(cache) = self.cache.lock()
            && let Some(result) = cache.get(&cache_key)
        {
            return *result;
        }
        let Some(bytes) = bounded_hsd_header_query(&self.executable, certificate.parent_hash)
        else {
            return false;
        };
        let header: HsdHeaderJson = match serde_json::from_slice(&bytes) {
            Ok(header) => header,
            Err(_) => return false,
        };
        let result = header_matches(certificate, &header);
        if let Ok(mut cache) = self.cache.lock()
            && cache.len() < MAX_RECOVERY_RECORDS
        {
            cache.insert(cache_key, result);
        }
        result
    }
}

impl CanonicalBlockOracle for HsdCliCanonicalBlockOracle {
    fn is_canonical(&self, height: u32, block_hash: Hash256) -> Result<bool, Box<dyn Error>> {
        let arguments = vec![
            "rpc".to_owned(),
            "getblockhash".to_owned(),
            height.to_string(),
        ];
        let bytes = bounded_hardened_hsd_query(&self.executable, &arguments)
            .ok_or("bounded hsd canonical-block query failed or timed out")?;
        let reported: Hash256 = fixed_hex(
            std::str::from_utf8(&bytes)?.trim(),
            "canonical HNS block hash",
        )?;
        Ok(reported == block_hash)
    }
}

fn bounded_hsd_best_hash_query(executable: &HardenedHsdCli) -> Option<Hash256> {
    let bytes = bounded_hardened_hsd_query(
        executable,
        &["rpc".to_owned(), "getbestblockhash".to_owned()],
    )?;
    fixed_hex(
        std::str::from_utf8(&bytes).ok()?.trim(),
        "best HNS block hash",
    )
    .ok()
}

fn bounded_hsd_header_query(executable: &HardenedHsdCli, parent_hash: Hash256) -> Option<Vec<u8>> {
    bounded_hardened_hsd_query(
        executable,
        &[
            "rpc".to_owned(),
            "getblockheader".to_owned(),
            hex::encode(parent_hash),
            "true".to_owned(),
        ],
    )
}

fn bounded_hsd_query(executable: &Path, arguments: &[String]) -> Option<Vec<u8>> {
    use std::process::Stdio;

    let mut command = Command::new(executable);
    command
        .args(arguments)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::null());
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;

        command.process_group(0);
    }
    collect_bounded_hsd_query(command.spawn().ok()?)
}

fn bounded_hardened_hsd_query(
    executable: &HardenedHsdCli,
    arguments: &[String],
) -> Option<Vec<u8>> {
    collect_bounded_hsd_query(executable.spawn_query(arguments).ok()?)
}

fn collect_bounded_hsd_query(mut child: std::process::Child) -> Option<Vec<u8>> {
    let Some(stdout) = child.stdout.take() else {
        terminate_bounded_process_group(&mut child);
        return None;
    };
    let reader = thread::spawn(move || {
        let mut bytes = Vec::new();
        stdout
            .take(HSD_RPC_MAX_BYTES.saturating_add(1))
            .read_to_end(&mut bytes)
            .map(|_| bytes)
    });
    let deadline = Instant::now() + HSD_RPC_TIMEOUT;
    let mut status = None;
    let mut failed = false;
    loop {
        if status.is_none() {
            match child.try_wait() {
                Ok(Some(observed)) => {
                    failed = !observed.success();
                    status = Some(observed);
                }
                Ok(None) => {}
                Err(_) => failed = true,
            }
        }
        if failed || status.is_some() {
            break;
        }
        if Instant::now() >= deadline {
            break;
        }
        thread::sleep(Duration::from_millis(10));
    }
    // The direct CLI must not leave helper descendants behind, even if it
    // exited successfully or those descendants closed their stdout handles.
    terminate_bounded_process_group(&mut child);
    let teardown_deadline = Instant::now() + Duration::from_millis(500);
    while !reader.is_finished() && Instant::now() < teardown_deadline {
        thread::sleep(Duration::from_millis(10));
    }
    if !reader.is_finished() {
        return None;
    }
    let bytes = reader.join().ok()?.ok()?;
    status
        .is_some_and(|status| status.success())
        .then_some(bytes)
        .filter(|bytes| bytes.len() as u64 <= HSD_RPC_MAX_BYTES)
}

fn terminate_bounded_process_group(child: &mut std::process::Child) {
    #[cfg(unix)]
    if let Ok(process_group) = i32::try_from(child.id()) {
        // SAFETY: a negative, validated child PID asks the kernel to signal
        // only the process group created for this command.
        unsafe {
            libc::kill(-process_group, libc::SIGKILL);
        }
    }
    let _ = child.kill();
    let _ = child.wait();
}

fn verify_body_with_hsd(
    hsd_source: &HardenedHsdSource,
    body: &BlockBodyPackageV2,
) -> Result<(), Box<dyn Error>> {
    let block = encode_hsd_block(body)?;
    let invocation = hsd_source.prepare_adapter_invocation()?;
    let arguments = vec![
        HSD_BODY_ADAPTER.to_owned(),
        invocation.adapter_path.display().to_string(),
    ];
    let output = bounded_child_with_stdin_retaining(
        Path::new("node"),
        &arguments,
        block,
        4 * 1024,
        Duration::from_secs(10),
        invocation.retained_descriptor,
    )
    .ok_or("bounded hsd body oracle failed or timed out")?;
    let result: HsdBodyResult = serde_json::from_slice(&output)?;
    if !result.valid || result.reason.is_some() {
        return Err(format!(
            "hsd rejected the body: {}",
            result.reason.as_deref().unwrap_or("unknown reason")
        )
        .into());
    }
    Ok(())
}

#[cfg(test)]
fn bounded_child_with_stdin(
    executable: &Path,
    arguments: &[String],
    input: Vec<u8>,
    maximum_output: u64,
    timeout: Duration,
) -> Option<Vec<u8>> {
    bounded_child_with_stdin_retaining(executable, arguments, input, maximum_output, timeout, None)
}

fn bounded_child_with_stdin_retaining(
    executable: &Path,
    arguments: &[String],
    input: Vec<u8>,
    maximum_output: u64,
    timeout: Duration,
    retained_descriptor: Option<fs::File>,
) -> Option<Vec<u8>> {
    use std::process::Stdio;

    let mut command = Command::new(executable);
    command
        .args(arguments)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null());
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;

        command.process_group(0);
    }
    let mut child = command.spawn().ok()?;
    // The adapter inherited the non-CLOEXEC source-directory descriptor. It
    // resolves the source argument through that exact validated directory,
    // even if the configured pathname is replaced immediately after spawn.
    drop(retained_descriptor);
    let Some(mut stdin) = child.stdin.take() else {
        terminate_bounded_process_group(&mut child);
        return None;
    };
    let writer = thread::spawn(move || stdin.write_all(&input));
    let Some(stdout) = child.stdout.take() else {
        terminate_bounded_process_group(&mut child);
        return None;
    };
    let reader = thread::spawn(move || {
        let mut bytes = Vec::new();
        stdout
            .take(maximum_output.saturating_add(1))
            .read_to_end(&mut bytes)
            .map(|_| bytes)
    });
    let deadline = Instant::now() + timeout;
    let mut status = None;
    loop {
        match child.try_wait() {
            Ok(Some(observed)) => {
                status = Some(observed);
                break;
            }
            Ok(None) => {}
            Err(_) => break,
        }
        if Instant::now() >= deadline {
            break;
        }
        thread::sleep(Duration::from_millis(10));
    }
    terminate_bounded_process_group(&mut child);
    let teardown_deadline = Instant::now() + Duration::from_millis(500);
    while (!writer.is_finished() || !reader.is_finished()) && Instant::now() < teardown_deadline {
        thread::sleep(Duration::from_millis(10));
    }
    if !writer.is_finished() || !reader.is_finished() {
        return None;
    }
    writer.join().ok()?.ok()?;
    let bytes = reader.join().ok()?.ok()?;
    status
        .is_some_and(|status| status.success())
        .then_some(bytes)
        .filter(|bytes| bytes.len() as u64 <= maximum_output)
}

fn encode_hsd_block(body: &BlockBodyPackageV2) -> Result<Vec<u8>, Box<dyn Error>> {
    let header = HnsHeader {
        nonce: 0,
        time: body.template_core.minimum_ntime,
        prev_block: body.template_core.hns_parent_hash,
        tree_root: body.tree_root,
        extra_nonce: [0; 24],
        reserved_root: body.reserved_root,
        witness_root: body.witness_root,
        merkle_root: body.merkle_root,
        version: body.template_core.block_version,
        bits: body.template_core.bits,
        mask: [0; 32],
    };
    let transaction_count = body
        .transactions_raw
        .len()
        .checked_add(1)
        .ok_or("body transaction count overflow")?;
    let mut block = Vec::with_capacity(
        236usize
            .checked_add(body.coinbase_raw.len())
            .and_then(|size| {
                body.transactions_raw
                    .iter()
                    .try_fold(size, |size, transaction| {
                        size.checked_add(transaction.len())
                    })
            })
            .ok_or("body block size overflow")?,
    );
    block.extend_from_slice(&header.to_bytes());
    encode_hsd_varint(transaction_count as u64, &mut block);
    block.extend_from_slice(&body.coinbase_raw);
    for transaction in &body.transactions_raw {
        block.extend_from_slice(transaction);
    }
    if block.len() > MAX_FILE_BYTES as usize + 4_096 {
        return Err("encoded HNS block exceeds body-oracle bound".into());
    }
    Ok(block)
}

fn encode_hsd_varint(value: u64, output: &mut Vec<u8>) {
    if value < 0xfd {
        output.push(value as u8);
    } else if u16::try_from(value).is_ok() {
        output.push(0xfd);
        output.extend_from_slice(&(value as u16).to_le_bytes());
    } else if u32::try_from(value).is_ok() {
        output.push(0xfe);
        output.extend_from_slice(&(value as u32).to_le_bytes());
    } else {
        output.push(0xff);
        output.extend_from_slice(&value.to_le_bytes());
    }
}

fn header_matches(certificate: &SessionParentCertificateV2, header: &HsdHeaderJson) -> bool {
    header.confirmations > 0
        && header.height == certificate.parent_height
        && header.time == certificate.observed_ntime
        && header
            .hash
            .eq_ignore_ascii_case(&hex::encode(certificate.parent_hash))
        && header
            .chainwork
            .eq_ignore_ascii_case(&hex::encode(certificate.parent_chainwork.0))
}

fn verify_parent(arguments: Vec<String>) -> Result<(), Box<dyn Error>> {
    let hsd_cli = HardenedHsdCli::validate(Path::new(argument(&arguments, "--hsd-cli")?))?;
    let parent_hash: Hash256 = fixed_hex(argument(&arguments, "--hash")?, "parent hash")?;
    let parent_chainwork: Hash256 =
        fixed_hex(argument(&arguments, "--chainwork")?, "parent chainwork")?;
    let certificate = SessionParentCertificateV2 {
        protocol_version: 2,
        network_id: 0,
        parent_hash,
        parent_height: argument(&arguments, "--height")?.parse()?,
        parent_chainwork: U256(parent_chainwork),
        observed_ntime: argument(&arguments, "--ntime")?.parse()?,
        certificate_sequence: 0,
        previous_parent_certificate_id: [0; 32],
        signer_set: SignatureSet::empty_ed25519(),
    };
    if !(HsdCliParentOracle {
        executable: hsd_cli,
        cache: Mutex::new(HashMap::new()),
    })
    .verify_header_and_chainwork(&certificate)
    {
        return Err(
            "local hsd rejected the parent hash, canonicality, height, ntime, or chainwork".into(),
        );
    }
    println!("status=local-hsd-parent-verified");
    println!("parent_hash={}", hex::encode(parent_hash));
    println!("height={}", certificate.parent_height);
    println!("chainwork={}", hex::encode(parent_chainwork));
    Ok(())
}

fn cpu_mine(arguments: Vec<String>) -> Result<(), Box<dyn Error>> {
    let header_hex = argument(&arguments, "--header")?;
    let target_hex = argument(&arguments, "--capture-target")?;
    let start: u32 = optional_argument(&arguments, "--start")
        .map(str::parse)
        .transpose()?
        .unwrap_or(0);
    let limit: u32 = optional_argument(&arguments, "--limit")
        .map(str::parse)
        .transpose()?
        .unwrap_or(u32::MAX);

    let raw_header = hex::decode(header_hex)?;
    let mut header = MinerHeader::from_bytes(&raw_header)?;
    let target: Hash256 = hex::decode(target_hex)?
        .try_into()
        .map_err(|bytes: Vec<u8>| {
            format!("capture target must be 32 bytes, got {}", bytes.len())
        })?;

    let end = u64::from(start) + u64::from(limit);
    for candidate in u64::from(start)..end.min(u64::from(u32::MAX) + 1) {
        header.nonce = candidate as u32;
        let share_hash = header.share_hash();
        if share_hash <= target {
            println!("nonce={}", header.nonce);
            println!("share_hash={}", hex::encode(share_hash));
            return Ok(());
        }
    }
    Err(format!("no capture share found in {limit} nonce candidates from {start}").into())
}

fn argument<'a>(arguments: &'a [String], name: &str) -> Result<&'a str, Box<dyn Error>> {
    optional_argument(arguments, name).ok_or_else(|| format!("missing {name}").into())
}

fn optional_argument<'a>(arguments: &'a [String], name: &str) -> Option<&'a str> {
    arguments
        .windows(2)
        .find(|pair| pair[0] == name)
        .map(|pair| pair[1].as_str())
}

fn repeated_arguments<'a>(arguments: &'a [String], name: &str) -> Vec<&'a str> {
    arguments
        .windows(2)
        .filter(|pair| pair[0] == name)
        .map(|pair| pair[1].as_str())
        .collect()
}

fn fixed_hex<const N: usize>(value: &str, label: &str) -> Result<[u8; N], Box<dyn Error>> {
    let bytes = hex::decode(value)?;
    bytes
        .try_into()
        .map_err(|bytes: Vec<u8>| format!("{label} must be {N} bytes, got {}", bytes.len()).into())
}

