    fn secure_tempdir() -> std::io::Result<tempfile::TempDir> {
        let directory = tempfile::tempdir()?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(directory.path(), fs::Permissions::from_mode(0o700))?;
        }
        Ok(directory)
    }

    fn initialize_parent_reorg_repair(store: &dyn DurableStore, network_id: u8) {
        super::ensure_parent_reorg_repair_ready(store, network_id).unwrap();
    }

    #[derive(Clone, Debug, PartialEq, Eq)]
    struct SubmittedResearchWork {
        miner_data: [u8; meshmine_hns::MINER_HEADER_SIZE],
        mask: Hash256,
        block_hash: Hash256,
    }

    struct MockResearchHsd {
        network: Mutex<String>,
        genesis: Mutex<Hash256>,
        work_data: [u8; meshmine_hns::MINER_HEADER_SIZE],
        target: Hash256,
        height: u32,
        response_time: u64,
        get_work_calls: AtomicUsize,
        submit_calls: AtomicUsize,
        submitted: Mutex<Option<SubmittedResearchWork>>,
    }

    fn cli_arguments(arguments: &[&str]) -> Vec<String> {
        arguments
            .iter()
            .map(|argument| (*argument).to_owned())
            .collect()
    }

    #[test]
    fn cli_schema_rejects_duplicate_nonrepeatable_arguments() {
        for (command, arguments, duplicate) in [
            (
                "overlay-serve",
                cli_arguments(&[
                    "--dir",
                    "state",
                    "--network-id",
                    "2",
                    "--listen",
                    "127.0.0.1:8443",
                    "--network-id",
                    "3",
                ]),
                "--network-id",
            ),
            (
                "receipt-sign",
                cli_arguments(&["--key", "first", "--key", "second"]),
                "--key",
            ),
        ] {
            let error = validate_command_arguments(command, &arguments).unwrap_err();
            assert_eq!(error.to_string(), format!("duplicate argument {duplicate}"));
        }
    }

    #[test]
    fn cli_schema_rejects_unknown_dangling_and_flag_as_value_arguments() {
        let typo = cli_arguments(&["--trusted-crt", "peer.der"]);
        assert!(
            validate_command_arguments("overlay-fetch", &typo)
                .unwrap_err()
                .to_string()
                .contains("unknown argument")
        );

        let dangling = cli_arguments(&["--out"]);
        assert_eq!(
            validate_command_arguments("committee-key-init", &dangling)
                .unwrap_err()
                .to_string(),
            "missing value for --out"
        );

        let flag_as_value = cli_arguments(&["--key", "--out", "signature.bin"]);
        assert_eq!(
            validate_command_arguments("receipt-sign", &flag_as_value)
                .unwrap_err()
                .to_string(),
            "missing value for --key; found option --out"
        );
    }

