    impl MockResearchHsd {
        fn new(network: &str) -> Self {
            let header = HnsHeader {
                nonce: 0,
                time: 1_700_000_000,
                prev_block: [3; 32],
                tree_root: [5; 32],
                extra_nonce: [7; meshmine_hns::NONCE_SIZE],
                reserved_root: [11; 32],
                witness_root: [13; 32],
                merkle_root: [17; 32],
                version: 0,
                bits: 0x207f_ffff,
                mask: [0; 32],
            };
            let mut target = [0; 32];
            target[..3].copy_from_slice(&[0x7f, 0xff, 0xff]);
            Self {
                network: Mutex::new(network.to_owned()),
                genesis: Mutex::new(RESEARCH_MINE_REGTEST_GENESIS),
                work_data: header.to_miner(),
                target,
                height: 42,
                // hsd's response clock is not required to equal attempt.time.
                response_time: header.time + 1,
                get_work_calls: AtomicUsize::new(0),
                submit_calls: AtomicUsize::new(0),
                submitted: Mutex::new(None),
            }
        }

        fn set_network(&self, network: &str) {
            *self.network.lock().unwrap() = network.to_owned();
        }

        fn set_genesis(&self, genesis: Hash256) {
            *self.genesis.lock().unwrap() = genesis;
        }

        fn submitted(&self) -> Option<SubmittedResearchWork> {
            self.submitted.lock().unwrap().clone()
        }
    }

    impl ResearchMiningHsd for MockResearchHsd {
        fn get_work(&self) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
            self.get_work_calls.fetch_add(1, Ordering::SeqCst);
            Ok(serde_json::to_vec(&serde_json::json!({
                "network": self.network.lock().unwrap().clone(),
                "data": hex::encode(self.work_data),
                "target": hex::encode(self.target),
                "height": self.height,
                "time": self.response_time,
                "fee": 0
            }))?)
        }

        fn submit_work(
            &self,
            miner_data: &[u8; meshmine_hns::MINER_HEADER_SIZE],
            mask: &Hash256,
        ) -> Result<(bool, String), Box<dyn std::error::Error>> {
            self.submit_calls.fetch_add(1, Ordering::SeqCst);
            if self.network.lock().unwrap().as_str() != "regtest" {
                return Err("mock refused a non-regtest submission".into());
            }
            let miner = MinerHeader::from_bytes(miner_data)?;
            if miner.mask_hash != blake2b_256(&[&miner.prev_block, mask]) {
                return Err("mock received a bad mask hash".into());
            }
            let block_hash = hns_header_from_miner(&miner, *mask).pow_hash();
            if block_hash > self.target {
                return Err("mock received work above the network target".into());
            }
            let submitted = SubmittedResearchWork {
                miner_data: *miner_data,
                mask: *mask,
                block_hash,
            };
            let mut prior = self.submitted.lock().unwrap();
            match prior.as_ref() {
                None => {
                    *prior = Some(submitted);
                    Ok((true, "valid".to_owned()))
                }
                Some(existing) if existing == &submitted => Ok((false, "stale".to_owned())),
                Some(_) => Err("mock received conflicting work after acceptance".into()),
            }
        }

        fn block_hash_at(&self, height: u32) -> Result<Hash256, Box<dyn std::error::Error>> {
            if height == 0 {
                return Ok(*self.genesis.lock().unwrap());
            }
            if height != self.height {
                return Err("mock canonical height mismatch".into());
            }
            self.submitted
                .lock()
                .unwrap()
                .as_ref()
                .map(|submitted| submitted.block_hash)
                .ok_or_else(|| "mock has no canonical research block".into())
        }
    }

    fn mock_research_config(directory: &Path) -> ResearchMineConfig {
        ResearchMineConfig {
            directory: directory.to_path_buf(),
            hsd_cli: directory.join("never-executed-hsd-cli"),
            research_seed: [29; 32],
            stock_regtest_compat: true,
            blind_band_bits: 0,
            nonce_limit: 4_096,
            maximum_captures: 64,
        }
    }

    fn research_cli_arguments(extra: &[&str]) -> Vec<String> {
        let mut arguments = vec![
            "--acknowledge-research-only-regtest".to_owned(),
            "--dir".to_owned(),
            "/tmp/research-never-created".to_owned(),
            "--hsd-cli".to_owned(),
            "/tmp/research-never-executed".to_owned(),
            "--research-seed".to_owned(),
            hex::encode([1; 32]),
        ];
        arguments.extend(extra.iter().map(|value| (*value).to_owned()));
        arguments
    }

    #[test]
    fn research_mine_once_is_end_to_end_durable_and_terminal_replay_is_read_only() {
        let directory = secure_tempdir().unwrap();
        let config = mock_research_config(directory.path());
        let oracle = MockResearchHsd::new("regtest");
        let database = directory.path().join(RESEARCH_MINE_DATABASE);
        let outcome = {
            let store = RedbStore::create(&database).unwrap();
            let outcome = run_research_mine_once(&config, &store, &oracle, None).unwrap();
            for key in [
                "work",
                "setup",
                "captures",
                "boundary",
                "opened",
                "submission-intent",
                "accepted",
            ] {
                assert!(store.get(RESEARCH_MINE_NAMESPACE, key).unwrap().is_some());
            }
            outcome
        };
        assert_eq!(outcome.height, 42);
        assert_eq!(outcome.acceptance_reason, "valid");
        assert!(outcome.capture_count > 0);
        assert_eq!(oracle.submit_calls.load(Ordering::SeqCst), 1);

        let submitted = oracle.submitted().unwrap();
        let original = MinerHeader::from_bytes(&oracle.work_data).unwrap();
        let solved = MinerHeader::from_bytes(&submitted.miner_data).unwrap();
        assert_eq!(
            original.mask_hash,
            blake2b_256(&[&original.prev_block, &[0; 32]])
        );
        assert_ne!(submitted.mask, [0; 32]);
        assert_eq!(submitted.mask[0] & 0x80, 0);
        assert!(submitted.mask.iter().any(|byte| *byte != 0));
        assert_eq!(
            solved.mask_hash,
            blake2b_256(&[&solved.prev_block, &submitted.mask])
        );
        assert_eq!(submitted.block_hash, outcome.block_hash);
        assert!(submitted.block_hash <= oracle.target);
        assert_eq!(oracle.get_work_calls.load(Ordering::SeqCst), 2);

        let get_work_calls = oracle.get_work_calls.load(Ordering::SeqCst);
        let replayed = {
            let store = RedbStore::create(&database).unwrap();
            run_research_mine_once(&config, &store, &oracle, None).unwrap()
        };
        assert_eq!(replayed, outcome);
        assert_eq!(oracle.submit_calls.load(Ordering::SeqCst), 1);
        assert_eq!(oracle.get_work_calls.load(Ordering::SeqCst), get_work_calls);
    }

    #[test]
    fn research_mine_once_recovers_every_persisted_boundary_and_stale_acceptance_gap() {
        for stage in [
            ResearchMineStage::Work,
            ResearchMineStage::Setup,
            ResearchMineStage::Captures,
            ResearchMineStage::Boundary,
            ResearchMineStage::Opened,
            ResearchMineStage::SubmissionIntent,
            ResearchMineStage::Submitted,
            ResearchMineStage::Accepted,
        ] {
            let directory = secure_tempdir().unwrap();
            let config = mock_research_config(directory.path());
            let oracle = MockResearchHsd::new("regtest");
            let database = directory.path().join(RESEARCH_MINE_DATABASE);
            {
                let store = RedbStore::create(&database).unwrap();
                let error =
                    run_research_mine_once(&config, &store, &oracle, Some(stage)).unwrap_err();
                assert!(
                    error
                        .to_string()
                        .contains(&format!("stop after {}", stage.label()))
                );
            }
            let outcome = {
                let store = RedbStore::create(&database).unwrap();
                run_research_mine_once(&config, &store, &oracle, None).unwrap()
            };
            assert_eq!(outcome.height, 42, "failed recovery after {stage:?}");
            assert_eq!(
                oracle.submit_calls.load(Ordering::SeqCst),
                if stage == ResearchMineStage::Submitted {
                    2
                } else {
                    1
                },
                "unexpected submit count after {stage:?}"
            );
            if stage == ResearchMineStage::Submitted {
                assert_eq!(outcome.acceptance_reason, "confirmed-after-stale");
            }
        }
    }

