    #[test]
    fn research_mine_once_rejects_changed_or_truncated_capture_boundary() {
        let directory = secure_tempdir().unwrap();
        let config = mock_research_config(directory.path());
        let oracle = MockResearchHsd::new("regtest");
        let store = MemoryStore::default();
        run_research_mine_once(&config, &store, &oracle, Some(ResearchMineStage::Captures))
            .unwrap_err();

        let mut changed = config.clone();
        changed.nonce_limit -= 1;
        let error = run_research_mine_once(&changed, &store, &oracle, None).unwrap_err();
        assert!(error.to_string().contains("bounds do not match"));
        assert_eq!(oracle.submit_calls.load(Ordering::SeqCst), 0);

        let mut captures = load_research_record::<ResearchCapturesRecord>(&store, "captures")
            .unwrap()
            .unwrap();
        assert!(captures.captures.len() > 1);
        captures.captures.pop();
        store
            .put(
                RESEARCH_MINE_NAMESPACE,
                "captures",
                &encode_research_record(&captures).unwrap(),
            )
            .unwrap();
        let error = run_research_mine_once(&config, &store, &oracle, None).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("exact deterministic bounded nonce scan")
        );
        assert_eq!(oracle.submit_calls.load(Ordering::SeqCst), 0);
    }

    #[test]
    fn terminal_replay_rejects_missing_stages_without_rpc_or_repair() {
        for key in [
            "work",
            "setup",
            "captures",
            "boundary",
            "opened",
            "submission-intent",
        ] {
            let directory = secure_tempdir().unwrap();
            let config = mock_research_config(directory.path());
            let oracle = MockResearchHsd::new("regtest");
            let store = MemoryStore::default();
            run_research_mine_once(&config, &store, &oracle, None).unwrap();
            store.delete(RESEARCH_MINE_NAMESPACE, key).unwrap();
            let work_calls = oracle.get_work_calls.load(Ordering::SeqCst);
            let submit_calls = oracle.submit_calls.load(Ordering::SeqCst);

            let error = run_research_mine_once(&config, &store, &oracle, None).unwrap_err();
            assert!(
                error.to_string().contains("missing durable"),
                "unexpected error for missing {key}: {error}"
            );
            assert_eq!(oracle.get_work_calls.load(Ordering::SeqCst), work_calls);
            assert_eq!(oracle.submit_calls.load(Ordering::SeqCst), submit_calls);
            assert!(store.get(RESEARCH_MINE_NAMESPACE, key).unwrap().is_none());
        }
    }

    #[test]
    fn terminal_replay_recomputes_setup_opening_and_seed_without_rpc() {
        for corrupted_stage in ["setup", "opened", "seed"] {
            let directory = secure_tempdir().unwrap();
            let config = mock_research_config(directory.path());
            let oracle = MockResearchHsd::new("regtest");
            let store = MemoryStore::default();
            run_research_mine_once(&config, &store, &oracle, None).unwrap();
            let mut replay_config = config.clone();
            match corrupted_stage {
                "setup" => {
                    let mut record = load_research_record::<ResearchSetupRecord>(&store, "setup")
                        .unwrap()
                        .unwrap();
                    record.transcript_root = hex::encode([41; 32]);
                    store
                        .put(
                            RESEARCH_MINE_NAMESPACE,
                            "setup",
                            &encode_research_record(&record).unwrap(),
                        )
                        .unwrap();
                }
                "opened" => {
                    let mut record = load_research_record::<ResearchOpenedRecord>(&store, "opened")
                        .unwrap()
                        .unwrap();
                    record.opening_transcript_root = hex::encode([42; 32]);
                    store
                        .put(
                            RESEARCH_MINE_NAMESPACE,
                            "opened",
                            &encode_research_record(&record).unwrap(),
                        )
                        .unwrap();
                }
                "seed" => replay_config.research_seed[0] ^= 1,
                _ => unreachable!(),
            }
            let work_calls = oracle.get_work_calls.load(Ordering::SeqCst);
            let submit_calls = oracle.submit_calls.load(Ordering::SeqCst);
            assert!(
                run_research_mine_once(&replay_config, &store, &oracle, None).is_err(),
                "terminal replay accepted corrupted {corrupted_stage}"
            );
            assert_eq!(oracle.get_work_calls.load(Ordering::SeqCst), work_calls);
            assert_eq!(oracle.submit_calls.load(Ordering::SeqCst), submit_calls);
        }
    }

