    #[test]
    fn research_mine_parser_separates_stock_and_blinded_profiles_and_caps_work() {
        let stock =
            parse_research_mine_config(&research_cli_arguments(&["--stock-regtest-compat"]))
                .unwrap();
        assert!(stock.stock_regtest_compat);
        assert_eq!(stock.blind_band_bits, 0);

        let synthetic = parse_research_mine_config(&research_cli_arguments(&[])).unwrap();
        assert!(!synthetic.stock_regtest_compat);
        assert_eq!(synthetic.blind_band_bits, 1);
        assert!(
            parse_research_mine_config(&research_cli_arguments(&[
                "--stock-regtest-compat",
                "--blind-band-bits",
                "1",
            ]))
            .is_err()
        );
        assert!(
            parse_research_mine_config(&research_cli_arguments(&["--blind-band-bits", "0",]))
                .is_err()
        );
        assert!(
            parse_research_mine_config(&research_cli_arguments(&[
                "--nonce-limit",
                &RESEARCH_MINE_MAXIMUM_NONCE_LIMIT.to_string(),
            ]))
            .is_ok()
        );
        assert!(
            parse_research_mine_config(&research_cli_arguments(&[
                "--nonce-limit",
                &(RESEARCH_MINE_MAXIMUM_NONCE_LIMIT + 1).to_string(),
            ]))
            .is_err()
        );
    }

