    #[cfg(unix)]
    #[test]
    fn research_paths_reject_symlinks_and_mutable_or_noncanonical_cli_identity() {
        use std::os::unix::fs::{PermissionsExt, symlink};

        let root = secure_tempdir().unwrap();
        fs::set_permissions(root.path(), fs::Permissions::from_mode(0o700)).unwrap();
        let state = root.path().join("state");
        prepare_research_state_directory(&state).unwrap();
        assert_eq!(
            fs::metadata(&state).unwrap().permissions().mode() & 0o777,
            0o700
        );
        assert!(prepare_research_state_directory(Path::new("relative-state")).is_err());
        let state_target = root.path().join("state-target");
        fs::create_dir(&state_target).unwrap();
        let state_link = root.path().join("state-link");
        symlink(&state_target, &state_link).unwrap();
        assert!(prepare_research_state_directory(&state_link).is_err());

        let cli = root.path().join("hsw-cli");
        fs::write(&cli, b"#!/bin/sh\nprintf '\"regtest\"'\n").unwrap();
        fs::set_permissions(&cli, fs::Permissions::from_mode(0o700)).unwrap();
        let first = validate_research_hsd_cli(&cli).unwrap();
        fs::write(&cli, b"#!/bin/sh\nprintf '\"changed\"'\n").unwrap();
        let changed = validate_research_hsd_cli(&cli).unwrap();
        assert_ne!(first, changed);

        fs::set_permissions(&cli, fs::Permissions::from_mode(0o722)).unwrap();
        assert!(validate_research_hsd_cli(&cli).is_err());
        fs::set_permissions(&cli, fs::Permissions::from_mode(0o700)).unwrap();
        let cli_link = root.path().join("hsw-cli-link");
        symlink(&cli, &cli_link).unwrap();
        assert!(validate_research_hsd_cli(&cli_link).is_err());
    }

