    #[cfg(unix)]
    #[test]
    fn production_hsd_cli_reattests_identity_before_every_pinned_spawn() {
        use std::os::unix::fs::PermissionsExt;

        let root = secure_tempdir().unwrap();
        let cli = root.path().join("hsd-cli");
        fs::write(&cli, b"#!/bin/sh\nprintf 'first'\n").unwrap();
        fs::set_permissions(&cli, fs::Permissions::from_mode(0o700)).unwrap();
        let first = HardenedHsdCli::validate(&cli).unwrap();
        assert_eq!(bounded_hardened_hsd_query(&first, &[]).unwrap(), b"first");

        // An in-place owner write retains the inode, so the digest/timestamp
        // portion of the identity must still stop the next invocation.
        fs::write(&cli, b"#!/bin/sh\nprintf 'changed-in-place'\n").unwrap();
        assert!(bounded_hardened_hsd_query(&first, &[]).is_none());

        let second = HardenedHsdCli::validate(&cli).unwrap();
        let replacement = root.path().join("replacement");
        fs::write(&replacement, b"#!/bin/sh\nprintf 'replacement'\n").unwrap();
        fs::set_permissions(&replacement, fs::Permissions::from_mode(0o700)).unwrap();
        fs::rename(&replacement, &cli).unwrap();
        assert!(bounded_hardened_hsd_query(&second, &[]).is_none());

        let replacement_identity = HardenedHsdCli::validate(&cli).unwrap();
        assert_eq!(
            bounded_hardened_hsd_query(&replacement_identity, &[]).unwrap(),
            b"replacement"
        );
    }

