    #[cfg(unix)]
    #[test]
    fn production_hsd_source_reattests_and_pins_the_directory_before_adapter_spawn() {
        use std::os::unix::fs::PermissionsExt;

        let root = secure_tempdir().unwrap();
        let source = root.path().join("hsd");
        fs::create_dir(&source).unwrap();
        fs::set_permissions(&source, fs::Permissions::from_mode(0o700)).unwrap();
        fs::write(source.join("identity"), b"first").unwrap();
        let first = HardenedHsdSource::validate(&source).unwrap();
        let invocation = first.prepare_adapter_invocation().unwrap();
        assert_eq!(
            fs::read(invocation.adapter_path.join("identity")).unwrap(),
            b"first"
        );

        let original = root.path().join("original");
        fs::rename(&source, &original).unwrap();
        fs::create_dir(&source).unwrap();
        fs::set_permissions(&source, fs::Permissions::from_mode(0o700)).unwrap();
        fs::write(source.join("identity"), b"replacement").unwrap();
        assert!(first.prepare_adapter_invocation().is_err());

        // A freshly attested source pins the replacement directory descriptor
        // for the adapter rather than relying on a second pathname lookup.
        let replacement = HardenedHsdSource::validate(&source).unwrap();
        let invocation = replacement.prepare_adapter_invocation().unwrap();
        assert_eq!(
            fs::read(invocation.adapter_path.join("identity")).unwrap(),
            b"replacement"
        );
    }

