    fn certified_receipt_and_close(
        benchmark: &ShareValidationBenchmark,
        fixture: &ShareValidationArtifacts,
    ) -> (ReceiptBatchV2, SessionCloseV2) {
        let validated = ValidatedShare {
            share: fixture.share.clone(),
            share_id: fixture.share.object_id(),
            work_key: fixture.share.work_key(),
            credited_work: work_for_target(&fixture.share.declared_target),
        };
        let mut builder = ReceiptBuilder::new(
            CORE_V2,
            2,
            fixture.session.object_id(),
            0,
            [0; 32],
            0,
            meshmine_types::U512::ZERO,
        );
        builder.accept(validated).unwrap();
        let mut batch = builder.finalize(SignatureSet::empty_ed25519()).unwrap();
        batch.signer_set = benchmark.certify_receipt(&batch);
        let mut close = build_session_close(
            fixture.session.object_id(),
            std::slice::from_ref(&batch),
            &fixture.receipt_roster,
            1,
            [77; 32],
            vec![],
            SignatureSet::empty_ed25519(),
        )
        .unwrap();
        close.signer_set = benchmark.certify_settlement(&close);
        (batch, close)
    }

    fn persist_legacy_empty_receipt_sessions(
        store: &dyn DurableStore,
        benchmark: &ShareValidationBenchmark,
        fixture: &ShareValidationArtifacts,
        count: u64,
    ) -> Vec<(Hash256, ReceiptBatchV2)> {
        let journal = ProtocolJournal::new(store);
        (0..count)
            .map(|offset| {
                let mut session = fixture.session.clone();
                session.session_sequence = session
                    .session_sequence
                    .checked_add(offset)
                    .expect("test session sequence");
                let session_id = session.object_id();
                journal
                    .persist(
                        ProtocolRecordKind::MaskSession,
                        &session_id,
                        &canonical_bytes(&session),
                    )
                    .unwrap();
                let builder =
                    ReceiptBuilder::new(CORE_V2, 2, session_id, 0, [0; 32], 0, U512::ZERO);
                let mut batch = builder.finalize(SignatureSet::empty_ed25519()).unwrap();
                batch.signer_set = benchmark.certify_receipt(&batch);
                journal
                    .persist(
                        ProtocolRecordKind::ReceiptBatch,
                        &batch.object_id(),
                        &canonical_bytes(&batch),
                    )
                    .unwrap();
                (session_id, batch)
            })
            .collect()
    }

    fn persist_session_close_evidence(
        store: &dyn DurableStore,
        session: &meshmine_types::MaskSessionV2,
        close: &SessionCloseV2,
    ) {
        let session_id = session.object_id();
        let close_id = close.object_id();
        assert_eq!(close.session_id, session_id);
        let journal = ProtocolJournal::new(store);
        journal
            .persist(
                ProtocolRecordKind::MaskSession,
                &session_id,
                &canonical_bytes(session),
            )
            .unwrap();
        journal
            .persist(
                ProtocolRecordKind::SessionClose,
                &close_id,
                &canonical_bytes(close),
            )
            .unwrap();
    }

    fn persist_legacy_normal_closed_session(
        store: &dyn DurableStore,
        session: &meshmine_types::MaskSessionV2,
        close: &SessionCloseV2,
    ) -> super::NormalClosedSessionIndexEntry {
        let session_id = session.object_id();
        let close_id = close.object_id();
        persist_session_close_evidence(store, session, close);
        store
            .put(
                &super::session_normal_close_namespace(2),
                &hex::encode(session_id),
                &super::session_normal_close_value(2, session_id, close_id),
            )
            .unwrap();
        store
            .put(
                &super::session_normal_close_proof_namespace(2),
                &hex::encode(session_id),
                &super::session_normal_close_proof_value(2, session_id, close_id),
            )
            .unwrap();
        store
            .put(
                &super::session_closure_namespace(2),
                &hex::encode(session_id),
                &super::session_closure_value(2, session_id),
            )
            .unwrap();
        super::normal_closed_session_index_entry(2, session, close).unwrap()
    }

    struct ReorgWinningCloseStore {
        inner: MemoryStore,
        session_id: Hash256,
        migration_race: bool,
        injected: std::sync::atomic::AtomicBool,
        migration_injected: std::sync::atomic::AtomicBool,
    }

    impl ReorgWinningCloseStore {
        fn new(session_id: Hash256) -> Self {
            Self {
                inner: MemoryStore::default(),
                session_id,
                migration_race: false,
                injected: std::sync::atomic::AtomicBool::new(false),
                migration_injected: std::sync::atomic::AtomicBool::new(false),
            }
        }

        fn during_migration(session_id: Hash256) -> Self {
            Self {
                inner: MemoryStore::default(),
                session_id,
                migration_race: true,
                injected: std::sync::atomic::AtomicBool::new(false),
                migration_injected: std::sync::atomic::AtomicBool::new(false),
            }
        }
    }

    impl DurableStore for ReorgWinningCloseStore {
        fn put(
            &self,
            namespace: &str,
            key: &str,
            value: &[u8],
        ) -> Result<(), meshmine_storage::StorageError> {
            self.inner.put(namespace, key, value)
        }

        fn get(
            &self,
            namespace: &str,
            key: &str,
        ) -> Result<Option<Vec<u8>>, meshmine_storage::StorageError> {
            self.inner.get(namespace, key)
        }

        fn delete(&self, namespace: &str, key: &str) -> Result<(), meshmine_storage::StorageError> {
            self.inner.delete(namespace, key)
        }

        fn compare_and_swap(
            &self,
            namespace: &str,
            key: &str,
            expected: Option<&[u8]>,
            value: &[u8],
        ) -> Result<bool, meshmine_storage::StorageError> {
            self.inner.compare_and_swap(namespace, key, expected, value)
        }

        fn apply_batch(
            &self,
            operations: &[meshmine_storage::BatchOperation],
        ) -> Result<(), meshmine_storage::StorageError> {
            self.inner.apply_batch(operations)
        }

        fn apply_batch_if(
            &self,
            namespace: &str,
            key: &str,
            expected: Option<&[u8]>,
            operations: &[meshmine_storage::BatchOperation],
        ) -> Result<bool, meshmine_storage::StorageError> {
            self.inner
                .apply_batch_if(namespace, key, expected, operations)
        }

        fn apply_batch_if_all(
            &self,
            conditions: &[meshmine_storage::BatchCondition],
            operations: &[meshmine_storage::BatchOperation],
        ) -> Result<bool, meshmine_storage::StorageError> {
            let normal_namespace = super::session_normal_close_namespace(2);
            let attempts_normal_promotion = operations.iter().any(|operation| {
                matches!(
                    operation,
                    meshmine_storage::BatchOperation::Put { namespace, .. }
                        if namespace == &normal_namespace
                )
            });
            if self.migration_race
                && attempts_normal_promotion
                && self
                    .migration_injected
                    .compare_exchange(false, true, Ordering::SeqCst, Ordering::SeqCst)
                    .is_ok()
            {
                let session_key = hex::encode(self.session_id);
                self.inner.apply_batch(&[
                    meshmine_storage::BatchOperation::put(
                        REORG_CLOSED_SESSION_NAMESPACE,
                        &session_key,
                        2u64.to_le_bytes().to_vec(),
                    ),
                    meshmine_storage::BatchOperation::put(
                        super::session_closure_namespace(2),
                        &session_key,
                        super::session_closure_value(2, self.session_id),
                    ),
                ])?;
                // Delegate the stale transaction rather than forcing a
                // synthetic failure: the migration's exact/absent conditions
                // must observe this interleaving and reject the promotion.
                return self.inner.apply_batch_if_all(conditions, operations);
            }
            let close_write = operations.iter().find_map(|operation| match operation {
                meshmine_storage::BatchOperation::Put {
                    namespace,
                    key,
                    value,
                } if namespace == "journal/session-close/v2" => Some((key.clone(), value.clone())),
                _ => None,
            });
            if !self.migration_race
                && let Some((close_key, close_value)) = close_write
                && self
                    .injected
                    .compare_exchange(false, true, Ordering::SeqCst, Ordering::SeqCst)
                    .is_ok()
            {
                let session_key = hex::encode(self.session_id);
                self.inner.apply_batch(&[
                    meshmine_storage::BatchOperation::put(
                        "journal/session-close/v2",
                        close_key,
                        close_value,
                    ),
                    meshmine_storage::BatchOperation::put(
                        REORG_CLOSED_SESSION_NAMESPACE,
                        &session_key,
                        1u64.to_le_bytes().to_vec(),
                    ),
                    meshmine_storage::BatchOperation::put(
                        super::session_closure_namespace(2),
                        &session_key,
                        super::session_closure_value(2, self.session_id),
                    ),
                    meshmine_storage::BatchOperation::delete(
                        super::active_receipt_head_namespace(2),
                        super::active_receipt_head_key(self.session_id),
                    ),
                ])?;
                return Ok(false);
            }
            self.inner.apply_batch_if_all(conditions, operations)
        }

        fn scan_namespace(
            &self,
            namespace: &str,
            limits: meshmine_storage::ScanLimits,
        ) -> Result<Vec<meshmine_storage::NamespaceRecord>, meshmine_storage::StorageError>
        {
            self.inner.scan_namespace(namespace, limits)
        }

        fn scan_namespace_after(
            &self,
            namespace: &str,
            exclusive_cursor: Option<&str>,
            limits: meshmine_storage::ScanLimits,
        ) -> Result<meshmine_storage::NamespacePage, meshmine_storage::StorageError> {
            self.inner
                .scan_namespace_after(namespace, exclusive_cursor, limits)
        }
    }

