    struct ReorgRepairProbeStore {
        inner: MemoryStore,
        canonical_scans: AtomicUsize,
        parent_scans: AtomicUsize,
        session_scans: AtomicUsize,
        parent_gets: AtomicUsize,
        paged_scans: AtomicUsize,
        injected_marker: Option<(String, String, u64)>,
        injected: std::sync::atomic::AtomicBool,
    }

    impl ReorgRepairProbeStore {
        fn counting() -> Self {
            Self {
                inner: MemoryStore::default(),
                canonical_scans: AtomicUsize::new(0),
                parent_scans: AtomicUsize::new(0),
                session_scans: AtomicUsize::new(0),
                parent_gets: AtomicUsize::new(0),
                paged_scans: AtomicUsize::new(0),
                injected_marker: None,
                injected: std::sync::atomic::AtomicBool::new(false),
            }
        }

        fn with_injected_marker(namespace: &str, object_id: Hash256, sequence: u64) -> Self {
            Self {
                injected_marker: Some((namespace.to_owned(), hex::encode(object_id), sequence)),
                ..Self::counting()
            }
        }
    }

    impl DurableStore for ReorgRepairProbeStore {
        fn put(
            &self,
            namespace: &str,
            key: &str,
            value: &[u8],
        ) -> Result<(), meshmine_storage::StorageError> {
            self.inner.put(namespace, key, value)
        }

        fn get(
            &self,
            namespace: &str,
            key: &str,
        ) -> Result<Option<Vec<u8>>, meshmine_storage::StorageError> {
            if namespace == "journal/parent-certificate/v2" {
                self.parent_gets.fetch_add(1, Ordering::SeqCst);
            }
            self.inner.get(namespace, key)
        }

        fn delete(&self, namespace: &str, key: &str) -> Result<(), meshmine_storage::StorageError> {
            self.inner.delete(namespace, key)
        }

        fn compare_and_swap(
            &self,
            namespace: &str,
            key: &str,
            expected: Option<&[u8]>,
            value: &[u8],
        ) -> Result<bool, meshmine_storage::StorageError> {
            self.inner.compare_and_swap(namespace, key, expected, value)
        }

        fn apply_batch(
            &self,
            operations: &[meshmine_storage::BatchOperation],
        ) -> Result<(), meshmine_storage::StorageError> {
            self.inner.apply_batch(operations)
        }

        fn apply_batch_if(
            &self,
            namespace: &str,
            key: &str,
            expected: Option<&[u8]>,
            operations: &[meshmine_storage::BatchOperation],
        ) -> Result<bool, meshmine_storage::StorageError> {
            self.inner
                .apply_batch_if(namespace, key, expected, operations)
        }

        fn apply_batch_if_all(
            &self,
            conditions: &[meshmine_storage::BatchCondition],
            operations: &[meshmine_storage::BatchOperation],
        ) -> Result<bool, meshmine_storage::StorageError> {
            if let Some((namespace, key, sequence)) = self.injected_marker.as_ref()
                && operations.iter().any(|operation| {
                    matches!(
                        operation,
                        meshmine_storage::BatchOperation::Put {
                            namespace: operation_namespace,
                            key: operation_key,
                            ..
                        } if operation_namespace == namespace && operation_key == key
                    )
                })
                && self
                    .injected
                    .compare_exchange(false, true, Ordering::SeqCst, Ordering::SeqCst)
                    .is_ok()
            {
                self.inner.put(namespace, key, &sequence.to_le_bytes())?;
            }
            self.inner.apply_batch_if_all(conditions, operations)
        }

        fn scan_namespace(
            &self,
            namespace: &str,
            limits: ScanLimits,
        ) -> Result<Vec<meshmine_storage::NamespaceRecord>, meshmine_storage::StorageError>
        {
            match namespace {
                "journal/canonical-plan-payment/v2" => {
                    self.canonical_scans.fetch_add(1, Ordering::SeqCst);
                }
                "journal/parent-certificate/v2" => {
                    self.parent_scans.fetch_add(1, Ordering::SeqCst);
                }
                "journal/mask-session/v2" => {
                    self.session_scans.fetch_add(1, Ordering::SeqCst);
                }
                _ => {}
            }
            self.inner.scan_namespace(namespace, limits)
        }

        fn scan_namespace_after(
            &self,
            namespace: &str,
            exclusive_cursor: Option<&str>,
            limits: ScanLimits,
        ) -> Result<meshmine_storage::NamespacePage, meshmine_storage::StorageError> {
            self.paged_scans.fetch_add(1, Ordering::SeqCst);
            self.inner
                .scan_namespace_after(namespace, exclusive_cursor, limits)
        }
    }

