    #[derive(Clone, Copy)]
    enum EventCloseRaceWinner {
        Event,
        Close,
    }

    struct EventCloseRaceStore {
        inner: MemoryStore,
        winner: EventCloseRaceWinner,
        contenders: Barrier,
        winner_committed: std::sync::atomic::AtomicBool,
    }

    impl EventCloseRaceStore {
        fn new(winner: EventCloseRaceWinner) -> Self {
            Self {
                inner: MemoryStore::default(),
                winner,
                contenders: Barrier::new(2),
                winner_committed: std::sync::atomic::AtomicBool::new(false),
            }
        }
    }

    impl DurableStore for EventCloseRaceStore {
        fn put(
            &self,
            namespace: &str,
            key: &str,
            value: &[u8],
        ) -> Result<(), meshmine_storage::StorageError> {
            self.inner.put(namespace, key, value)
        }

        fn get(
            &self,
            namespace: &str,
            key: &str,
        ) -> Result<Option<Vec<u8>>, meshmine_storage::StorageError> {
            self.inner.get(namespace, key)
        }

        fn delete(&self, namespace: &str, key: &str) -> Result<(), meshmine_storage::StorageError> {
            self.inner.delete(namespace, key)
        }

        fn compare_and_swap(
            &self,
            namespace: &str,
            key: &str,
            expected: Option<&[u8]>,
            value: &[u8],
        ) -> Result<bool, meshmine_storage::StorageError> {
            self.inner.compare_and_swap(namespace, key, expected, value)
        }

        fn apply_batch(
            &self,
            operations: &[meshmine_storage::BatchOperation],
        ) -> Result<(), meshmine_storage::StorageError> {
            self.inner.apply_batch(operations)
        }

        fn apply_batch_if(
            &self,
            namespace: &str,
            key: &str,
            expected: Option<&[u8]>,
            operations: &[meshmine_storage::BatchOperation],
        ) -> Result<bool, meshmine_storage::StorageError> {
            self.inner
                .apply_batch_if(namespace, key, expected, operations)
        }

        fn apply_batch_if_all(
            &self,
            conditions: &[meshmine_storage::BatchCondition],
            operations: &[meshmine_storage::BatchOperation],
        ) -> Result<bool, meshmine_storage::StorageError> {
            let event = operations.iter().any(|operation| {
                matches!(
                    operation,
                    meshmine_storage::BatchOperation::Put { namespace, .. }
                        if namespace == "journal/canonical-plan-payment/v2"
                )
            }) && operations.iter().any(|operation| {
                matches!(
                    operation,
                    meshmine_storage::BatchOperation::Put { namespace, .. }
                        if namespace == REORG_CLOSED_SESSION_NAMESPACE
                )
            });
            let close = operations.iter().any(|operation| {
                matches!(
                    operation,
                    meshmine_storage::BatchOperation::Put { namespace, .. }
                        if namespace == "journal/session-close/v2"
                )
            }) && operations.iter().any(|operation| {
                matches!(
                    operation,
                    meshmine_storage::BatchOperation::Put { namespace, .. }
                        if namespace == &super::session_normal_close_proof_namespace(2)
                )
            });
            if !event && !close {
                return self.inner.apply_batch_if_all(conditions, operations);
            }
            self.contenders.wait();
            let is_winner = matches!(
                (self.winner, event, close),
                (EventCloseRaceWinner::Event, true, false)
                    | (EventCloseRaceWinner::Close, false, true)
            );
            if !is_winner {
                while !self.winner_committed.load(Ordering::Acquire) {
                    std::thread::yield_now();
                }
            }
            let committed = self.inner.apply_batch_if_all(conditions, operations)?;
            if is_winner {
                self.winner_committed.store(true, Ordering::Release);
            }
            Ok(committed)
        }

        fn scan_namespace(
            &self,
            namespace: &str,
            limits: ScanLimits,
        ) -> Result<Vec<meshmine_storage::NamespaceRecord>, meshmine_storage::StorageError>
        {
            self.inner.scan_namespace(namespace, limits)
        }

        fn scan_namespace_after(
            &self,
            namespace: &str,
            exclusive_cursor: Option<&str>,
            limits: ScanLimits,
        ) -> Result<meshmine_storage::NamespacePage, meshmine_storage::StorageError> {
            self.inner
                .scan_namespace_after(namespace, exclusive_cursor, limits)
        }
    }

