    fn certified_snapshot_and_plan(
        benchmark: &ShareValidationBenchmark,
        fixture: &ShareValidationArtifacts,
        close: &SessionCloseV2,
        entropy_hash: [u8; 32],
        prior_beacon: [u8; 32],
    ) -> (PayoutSnapshotV2, PayoutPlanV2) {
        let credited_work = work_for_target(&fixture.share.declared_target);
        let close_id = close.object_id();
        let mut snapshot = PayoutSnapshotV2 {
            protocol_version: CORE_V2,
            network_id: 2,
            snapshot_sequence: 0,
            previous_snapshot_id: [0; 32],
            first_session_close_id: close_id,
            last_session_close_id: close_id,
            close_anchor_height: fixture.parent.parent_height,
            work_window_target: credited_work,
            actual_work_in_window: credited_work,
            work_buckets: vec![WorkBucketLeaf {
                bucket_id: fixture.payout_bucket.object_id(),
                operator_pubkey: fixture.payout_bucket.operator_pubkey,
                hns_address_version: fixture.payout_bucket.hns_address_version,
                hns_address_hash: fixture.payout_bucket.hns_address_hash.clone(),
                credited_work,
            }],
            service_buckets: vec![],
            share_set_root: merkle_root(&[close_id]),
            service_set_root: merkle_root(&[]),
            settlement_committee_id: fixture.settlement_roster.id(),
            signer_set: SignatureSet::empty_ed25519(),
        };
        snapshot.signer_set = benchmark.certify_settlement(&snapshot);
        let mut plan = build_payout_plan(
            &snapshot,
            snapshot.close_anchor_height + 1,
            vec![entropy_hash],
            prior_beacon,
            payout_profile(),
            SignatureSet::empty_ed25519(),
        )
        .unwrap();
        plan.signer_set = benchmark.certify_settlement(&plan);
        (snapshot, plan)
    }

    fn payout_admission(
        store: &dyn DurableStore,
        fixture: &ShareValidationArtifacts,
        oracle: Arc<dyn CanonicalBlockOracle + Send + Sync>,
        prior_beacon: Hash256,
    ) -> PayoutAdmission {
        let policy = payout_policy(fixture, prior_beacon);
        let state = recover_payout_state(
            store,
            2,
            &fixture.receipt_roster,
            &fixture.settlement_roster,
            policy,
            oracle.as_ref(),
        )
        .unwrap();
        PayoutAdmission {
            settlement_roster: fixture.settlement_roster.clone(),
            receipt_roster: fixture.receipt_roster.clone(),
            policy,
            hns_oracle: oracle,
            share_dags: None,
            state: Mutex::new(state),
        }
    }

    fn payout_policy(
        fixture: &ShareValidationArtifacts,
        prior_beacon: Hash256,
    ) -> super::StaticPayoutPolicy {
        let credited_work = work_for_target(&fixture.share.declared_target);
        super::StaticPayoutPolicy {
            profile: payout_profile(),
            maximum_entropy_blocks: 8,
            snapshot_step_work: credited_work,
            pplns_window_work: credited_work,
            entropy_delay_blocks: 1,
            entropy_block_count: 1,
            prior_beacon,
        }
    }

