    #[test]
    fn static_payout_profile_rejects_unreplayable_or_ambiguous_policy() {
        let example =
            Path::new(env!("CARGO_MANIFEST_DIR")).join("../../specs/payout-profile.example.json");
        let source: serde_json::Value =
            serde_json::from_slice(&fs::read(example).unwrap()).unwrap();
        let directory = secure_tempdir().unwrap();

        let cases = [
            (
                "service-tickets",
                "service_ticket_count",
                serde_json::json!(1),
            ),
            (
                "service-allocation",
                "service_basis_points",
                serde_json::json!(1),
            ),
            (
                "zero-snapshot-step",
                "snapshot_step_work",
                serde_json::json!("00".repeat(64)),
            ),
            (
                "zero-window",
                "pplns_window_work",
                serde_json::json!("00".repeat(64)),
            ),
            ("zero-delay", "entropy_delay_blocks", serde_json::json!(0)),
            ("zero-entropy", "entropy_block_count", serde_json::json!(0)),
            (
                "excess-entropy",
                "entropy_block_count",
                serde_json::json!(33),
            ),
        ];
        for (name, field, value) in cases {
            let mut configured = source.clone();
            configured[field] = value;
            let path = directory.path().join(format!("{name}.json"));
            fs::write(&path, serde_json::to_vec(&configured).unwrap()).unwrap();
            assert!(
                load_static_payout_profile(&path, 2).is_err(),
                "invalid static payout policy accepted: {name}"
            );
        }

        let mut unknown = source;
        unknown["unfrozen_policy"] = serde_json::json!(true);
        let path = directory.path().join("unknown-field.json");
        fs::write(&path, serde_json::to_vec(&unknown).unwrap()).unwrap();
        assert!(load_static_payout_profile(&path, 2).is_err());
    }

    #[test]
    fn independent_javascript_payout_verifier_matches_rust_and_rejects_resigned_fraud() {
        let directory = secure_tempdir().unwrap();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        let (_, close) = certified_receipt_and_close(&benchmark, &fixture);
        let entropy = [41; 32];
        let beacon = [42; 32];
        let (snapshot, plan) =
            certified_snapshot_and_plan(&benchmark, &fixture, &close, entropy, beacon);
        let snapshot_path = directory.path().join("snapshot.bin");
        let plan_path = directory.path().join("plan.bin");
        let fraudulent_path = directory.path().join("fraudulent-plan.bin");
        let roster_path = directory.path().join("settlement.json");
        let profile_path = directory.path().join("payout-profile.json");
        fs::write(&snapshot_path, canonical_bytes(&snapshot)).unwrap();
        fs::write(&plan_path, canonical_bytes(&plan)).unwrap();

        let roster = serde_json::json!({
            "protocol_version": CORE_V2,
            "network_id": 2,
            "role": "settlement",
            "epoch": fixture.settlement_roster.epoch,
            "threshold": fixture.settlement_roster.threshold,
            "members": fixture
                .settlement_roster
                .members
                .iter()
                .map(hex::encode)
                .collect::<Vec<_>>()
        });
        fs::write(&roster_path, serde_json::to_vec(&roster).unwrap()).unwrap();
        let credited_work = work_for_target(&fixture.share.declared_target);
        let profile = serde_json::json!({
            "protocol_version": CORE_V2,
            "network_id": 2,
            "work_ticket_count": 1,
            "service_ticket_count": 0,
            "service_basis_points": 0,
            "maximum_service_basis_points": 600,
            "minimum_ticket_value": 1,
            "maximum_coinbase_outputs": 16,
            "maximum_entropy_blocks": 8,
            "snapshot_step_work": hex::encode(credited_work.0),
            "pplns_window_work": hex::encode(credited_work.0),
            "entropy_delay_blocks": 1,
            "entropy_block_count": 1,
            "prior_beacon": hex::encode(beacon)
        });
        fs::write(&profile_path, serde_json::to_vec(&profile).unwrap()).unwrap();

        let repository = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let verifier = repository.join("hsd-oracle/verify-payout-artifacts.js");
        let run = |candidate: &Path| {
            std::process::Command::new("node")
                .env("NODE_BACKEND", "js")
                .arg(&verifier)
                .arg("--snapshot")
                .arg(&snapshot_path)
                .arg("--plan")
                .arg(candidate)
                .arg("--settlement-roster")
                .arg(&roster_path)
                .arg("--payout-profile")
                .arg(&profile_path)
                .arg("--skip-canonical-entropy")
                .output()
                .unwrap()
        };
        let verified = run(&plan_path);
        assert!(
            verified.status.success(),
            "independent verifier failed: {}",
            String::from_utf8_lossy(&verified.stderr)
        );
        let report: serde_json::Value = serde_json::from_slice(&verified.stdout).unwrap();
        assert_eq!(report["valid"], true);
        assert_eq!(report["snapshot_id"], hex::encode(snapshot.object_id()));
        assert_eq!(report["plan_id"], hex::encode(plan.object_id()));
        assert_eq!(report["canonical_entropy_checked"], false);

        let mut fraudulent = plan;
        fraudulent.entropy_hashes[0][0] ^= 1;
        fraudulent.signer_set = SignatureSet::empty_ed25519();
        fraudulent.signer_set = benchmark.certify_settlement(&fraudulent);
        fs::write(&fraudulent_path, canonical_bytes(&fraudulent)).unwrap();
        let rejected = run(&fraudulent_path);
        assert!(!rejected.status.success());
        assert!(
            String::from_utf8_lossy(&rejected.stderr)
                .contains("plan seed does not match the snapshot, entropy, and beacon")
        );
    }

    #[test]
    fn independent_javascript_body_verifier_matches_rust_and_rejects_resigned_fraud() {
        let directory = secure_tempdir().unwrap();
        let fixture = ShareValidationBenchmark::new().artifacts();
        let body_path = directory.path().join("body.bin");
        let fraudulent_path = directory.path().join("fraudulent-body.bin");
        fs::write(&body_path, canonical_bytes(&fixture.body)).unwrap();
        let repository = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let verifier = repository.join("hsd-oracle/verify-body-artifacts.js");
        let run = |candidate: &Path| {
            std::process::Command::new("node")
                .env("NODE_BACKEND", "js")
                .arg(&verifier)
                .arg("--body")
                .arg(candidate)
                .arg("--body-only")
                .output()
                .unwrap()
        };

        let verified = run(&body_path);
        assert!(
            verified.status.success(),
            "independent body verifier failed: {}",
            String::from_utf8_lossy(&verified.stderr)
        );
        let report: serde_json::Value = serde_json::from_slice(&verified.stdout).unwrap();
        assert_eq!(report["valid"], true);
        assert_eq!(
            report["template_core_id"],
            hex::encode(fixture.body.template_core_id)
        );
        assert_eq!(
            report["body_package_id"],
            hex::encode(fixture.body.object_id())
        );
        assert_eq!(report["contextual_hsd_checked"], false);

        let mut fraudulent = fixture.body;
        fraudulent.hsd_validation_result_hash[0] ^= 1;
        fraudulent.operator_signature = SignatureBytes::empty();
        fraudulent.operator_signature = sign_object(
            &SigningKey::from_bytes(&[42; 32]),
            fraudulent.network_id,
            &fraudulent,
        );
        fs::write(&fraudulent_path, canonical_bytes(&fraudulent)).unwrap();
        let rejected = run(&fraudulent_path);
        assert!(!rejected.status.success());
        assert!(
            String::from_utf8_lossy(&rejected.stderr)
                .contains("body hsd validation-result commitment is inconsistent")
        );
    }

    #[test]
    fn continuous_hns_sync_configuration_is_explicit_and_bounded() {
        let source = secure_tempdir().unwrap();
        let hsd_cli = source.path().join("hsd-cli");
        fs::write(&hsd_cli, b"#!/bin/sh\nexit 0\n").unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(&hsd_cli, fs::Permissions::from_mode(0o700)).unwrap();
        }
        let arguments = vec![
            "--hsd-cli".to_owned(),
            hsd_cli.display().to_string(),
            "--hns-sync-source".to_owned(),
            source.path().display().to_string(),
            "--hns-sync-from-height".to_owned(),
            "17".to_owned(),
            "--hns-sync-interval-ms".to_owned(),
            "250".to_owned(),
            "--hns-sync-maximum-events".to_owned(),
            "32".to_owned(),
        ];
        assert!(load_hns_sync_config(&arguments, false).is_err());
        let configured = load_hns_sync_config(&arguments, true).unwrap().unwrap();
        assert_eq!(configured.from_height, Some(17));
        assert_eq!(configured.maximum_events, 32);
        assert_eq!(configured.interval, std::time::Duration::from_millis(250));

        let orphan_option = vec!["--hns-sync-from-height".to_owned(), "17".to_owned()];
        assert!(load_hns_sync_config(&orphan_option, true).is_err());
        let mut too_fast = arguments;
        let index = too_fast
            .iter()
            .position(|argument| argument == "--hns-sync-interval-ms")
            .unwrap();
        too_fast[index + 1] = "99".to_owned();
        assert!(load_hns_sync_config(&too_fast, true).is_err());
    }

