    #[test]
    fn static_peer_configuration_is_bounded_rotation_ready_and_identity_pinned() {
        let directory = secure_tempdir().unwrap();
        fs::write(
            directory.path().join("retiring.der"),
            b"retiring-certificate",
        )
        .unwrap();
        fs::write(directory.path().join("current.der"), b"current-certificate").unwrap();
        let path = directory.path().join("peers.json");
        let write_config = |forward_queue: usize,
                            network_id: u8,
                            expected_transport_pubkey: [u8; 32],
                            certificates: Vec<&str>| {
            fs::write(
                &path,
                serde_json::to_vec_pretty(&serde_json::json!({
                    "protocol_version": CORE_V2,
                    "network_id": network_id,
                    "reconnect_initial_ms": 250,
                    "reconnect_maximum_ms": 30_000,
                    "forward_queue": forward_queue,
                    "peers": [{
                        "remote": "127.0.0.1:9444",
                        "server_name": "localhost",
                        "expected_transport_pubkey": hex::encode(expected_transport_pubkey),
                        "trusted_server_certificates": certificates,
                    }],
                }))
                .unwrap(),
            )
            .unwrap();
        };
        let arguments = vec!["--peer-config".to_owned(), path.display().to_string()];
        write_config(64, 2, [1; 32], vec!["retiring.der", "current.der"]);
        let configured = load_static_peer_network_config(&arguments, 2, [2; 32])
            .unwrap()
            .unwrap();
        assert_eq!(configured.peers.len(), 1);
        assert_eq!(configured.forward_queue, 64);
        assert_eq!(configured.reconnect_initial, Duration::from_millis(250));
        assert_eq!(configured.reconnect_maximum, Duration::from_secs(30));
        assert_eq!(configured.replay_interval, Duration::from_secs(5));
        assert_eq!(configured.maximum_replay_objects_per_pass, 256);
        assert_eq!(configured.maximum_replay_bytes_per_pass, 16 * 1024 * 1024);
        assert_eq!(
            configured.peers[0].trusted_server_certificates,
            vec![
                b"retiring-certificate".to_vec(),
                b"current-certificate".to_vec()
            ]
        );

        write_config(0, 2, [1; 32], vec!["current.der"]);
        assert!(load_static_peer_network_config(&arguments, 2, [2; 32]).is_err());
        write_config(64, 3, [1; 32], vec!["current.der"]);
        assert!(load_static_peer_network_config(&arguments, 2, [2; 32]).is_err());
        write_config(64, 2, [2; 32], vec!["current.der"]);
        assert!(load_static_peer_network_config(&arguments, 2, [2; 32]).is_err());
        write_config(
            64,
            2,
            [1; 32],
            vec![
                "current.der",
                "current.der",
                "current.der",
                "current.der",
                "current.der",
                "current.der",
                "current.der",
                "current.der",
                "current.der",
            ],
        );
        assert!(load_static_peer_network_config(&arguments, 2, [2; 32]).is_err());

        write_config(64, 2, [1; 32], vec!["current.der"]);
        let mut unbounded_replay: serde_json::Value =
            serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();
        unbounded_replay["replay_interval_ms"] = 999.into();
        fs::write(&path, serde_json::to_vec(&unbounded_replay).unwrap()).unwrap();
        assert!(load_static_peer_network_config(&arguments, 2, [2; 32]).is_err());
    }

    #[tokio::test]
    async fn outbound_lane_capacity_and_in_flight_permits_are_independent() {
        let (router, mut receivers) = GossipForwardRouter::bounded(1);
        let forwarded = |topic, byte| ForwardedGossip {
            sequence: u64::from(byte),
            source_peer: [0; 32],
            topic,
            object_id: [byte; 32],
            payload: vec![byte],
        };
        router
            .try_send(forwarded(GossipTopic::PayoutSnapshot, 1))
            .unwrap();
        assert!(matches!(
            router.try_send(forwarded(GossipTopic::PayoutPlan, 2)),
            Err(tokio::sync::mpsc::error::TrySendError::Full(_))
        ));
        router.try_send(forwarded(GossipTopic::Parent, 3)).unwrap();
        assert_eq!(
            receivers
                .fast_path
                .recv()
                .await
                .unwrap()
                .topic
                .protocol_lane(),
            ProtocolLane::FastPath
        );

        let delivery = StaticPeerDeliveryControl::new();
        let _settlement = delivery
            .lane_gate(ProtocolLane::Settlement)
            .acquire_owned()
            .await
            .unwrap();
        let fast = tokio::time::timeout(
            Duration::from_millis(25),
            delivery.lane_gate(ProtocolLane::FastPath).acquire_owned(),
        )
        .await;
        assert!(fast.is_ok(), "settlement occupied the fast-path permit");
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn static_peer_supervisor_forwards_authenticated_gossip_after_server_restart() {
        fn signed_operator(sequence: u64) -> (OperatorRecordV2, Vec<u8>) {
            let signing_key = SigningKey::from_bytes(&[71; 32]);
            let mut operator = OperatorRecordV2 {
                protocol_version: CORE_V2,
                network_id: 2,
                operator_pubkey: signing_key.verifying_key().to_bytes(),
                sequence,
                supported_features: 0,
                payout_bucket_ids: vec![],
                contact_metadata_hash: None,
                signature_suite: ED25519_SUITE,
                signature: SignatureBytes::empty(),
            };
            operator.signature = sign_object(&signing_key, 2, &operator);
            let bytes = canonical_bytes(&operator);
            (operator, bytes)
        }

        async fn forward_until_stored(
            source: &DurableOverlayApplication,
            destination: &DurableOverlayApplication,
            operator: &OperatorRecordV2,
            bytes: &[u8],
        ) {
            let object_id = operator.object_id();
            for _ in 0..150 {
                assert!(source.validate_and_store_gossip(
                    [250; 32],
                    GossipTopic::Operator,
                    object_id,
                    bytes,
                ));
                if destination
                    .store
                    .get(OPERATOR_NAMESPACE, &format!("2/{}", hex::encode(object_id)))
                    .unwrap()
                    .as_deref()
                    == Some(bytes)
                {
                    return;
                }
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
            panic!("static peer did not durably receive operator gossip");
        }

        let CertifiedKey { cert, key_pair } =
            generate_simple_self_signed(vec!["localhost".to_owned()]).unwrap();
        let certificate = cert.der().to_vec();
        let private_key = key_pair.serialize_der();
        let server_identity = TransportIdentity::new(SigningKey::from_bytes(&[72; 32]), None);
        let client_identity = TransportIdentity::new(SigningKey::from_bytes(&[73; 32]), None);
        let server_directory = secure_tempdir().unwrap();
        let source_directory = secure_tempdir().unwrap();
        let destination = Arc::new(DurableOverlayApplication {
            store: RedbStore::create(server_directory.path().join(STATE_DATABASE)).unwrap(),
            network_id: 2,
            parent_admission: None,
            share_admission: None,
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: None,
            gossip_outbox: None,
        });
        let (limits, topic_limits) = default_overlay_limits();
        let server = QuicOverlayServer::bind(
            "127.0.0.1:0".parse().unwrap(),
            certificate.clone(),
            private_key.clone(),
            server_identity.clone(),
            2,
            OverlayNode::new(2, limits, topic_limits),
            destination.clone(),
            QuicTransportLimits::default(),
        )
        .unwrap();
        let address = server.local_addr().unwrap();
        let (first_server_shutdown_tx, first_server_shutdown_rx) = watch::channel(false);
        let first_server_task = tokio::spawn(server.run_until(first_server_shutdown_rx));

        let (forward_tx, forward_rx) = GossipForwardRouter::bounded(8);
        let source = Arc::new(DurableOverlayApplication {
            store: RedbStore::create(source_directory.path().join(STATE_DATABASE)).unwrap(),
            network_id: 2,
            parent_admission: None,
            share_admission: None,
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: Some(forward_tx),
            gossip_outbox: Some(Arc::new(DurableGossipOutbox::new(2))),
        });
        let config = StaticPeerNetworkConfig {
            peers: vec![StaticPeerConfig {
                remote: address,
                server_name: "localhost".to_owned(),
                expected_transport_pubkey: server_identity.transport_pubkey(),
                trusted_server_certificates: vec![certificate.clone()],
            }],
            reconnect_initial: Duration::from_millis(20),
            reconnect_maximum: Duration::from_millis(80),
            forward_queue: 8,
            replay_interval: Duration::from_millis(20),
            maximum_replay_objects_per_pass: 8,
            maximum_replay_bytes_per_pass: 1024 * 1024,
        };
        super::recover_durable_gossip_outbox(
            &source.store,
            2,
            source.gossip_outbox.as_ref().unwrap().as_ref(),
            &BTreeSet::from([server_identity.transport_pubkey()]),
            super::GossipOutboxRecoveryProfile::default(),
        )
        .unwrap();
        let (peer_shutdown_tx, peer_shutdown_rx) = watch::channel(false);
        let peer_task = tokio::spawn(run_static_peer_network(
            config,
            client_identity,
            2,
            forward_rx,
            source.clone(),
            peer_shutdown_rx,
        ));

        let (first, first_bytes) = signed_operator(1);
        forward_until_stored(&source, &destination, &first, &first_bytes).await;
        first_server_shutdown_tx.send(true).unwrap();
        tokio::time::timeout(Duration::from_secs(1), first_server_task)
            .await
            .unwrap()
            .unwrap()
            .unwrap();

        let mut restarted_server = None;
        for _ in 0..50 {
            let (limits, topic_limits) = default_overlay_limits();
            match QuicOverlayServer::bind(
                address,
                certificate.clone(),
                private_key.clone(),
                server_identity.clone(),
                2,
                OverlayNode::new(2, limits, topic_limits),
                destination.clone(),
                QuicTransportLimits::default(),
            ) {
                Ok(server) => {
                    restarted_server = Some(server);
                    break;
                }
                Err(meshmine_network::TransportError::Configuration(error))
                    if error.contains("Address already in use") =>
                {
                    tokio::time::sleep(Duration::from_millis(20)).await;
                }
                Err(error) => panic!("static peer restart bind failed: {error}"),
            }
        }
        let restarted_server =
            restarted_server.expect("static peer restart address was not released within 1s");
        let (second_server_shutdown_tx, second_server_shutdown_rx) = watch::channel(false);
        let second_server_task =
            tokio::spawn(restarted_server.run_until(second_server_shutdown_rx));
        let (second, second_bytes) = signed_operator(2);
        forward_until_stored(&source, &destination, &second, &second_bytes).await;

        peer_shutdown_tx.send(true).unwrap();
        tokio::time::timeout(Duration::from_secs(1), peer_task)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        second_server_shutdown_tx.send(true).unwrap();
        tokio::time::timeout(Duration::from_secs(1), second_server_task)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn static_peer_replays_offline_queue_pressure_after_source_process_restart() {
        fn operator(sequence: u64) -> (OperatorRecordV2, Vec<u8>) {
            let signing_key = SigningKey::from_bytes(&[91; 32]);
            let mut operator = OperatorRecordV2 {
                protocol_version: CORE_V2,
                network_id: 2,
                operator_pubkey: signing_key.verifying_key().to_bytes(),
                sequence,
                supported_features: 0,
                payout_bucket_ids: vec![],
                contact_metadata_hash: None,
                signature_suite: ED25519_SUITE,
                signature: SignatureBytes::empty(),
            };
            operator.signature = sign_object(&signing_key, 2, &operator);
            let bytes = canonical_bytes(&operator);
            (operator, bytes)
        }

        let source_directory = secure_tempdir().unwrap();
        let destination_directory = secure_tempdir().unwrap();
        let source_path = source_directory.path().join(STATE_DATABASE);
        let (forward_tx, forward_rx) = GossipForwardRouter::bounded(1);
        let first_source = Arc::new(DurableOverlayApplication {
            store: RedbStore::create(&source_path).unwrap(),
            network_id: 2,
            parent_admission: None,
            share_admission: None,
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: Some(forward_tx),
            gossip_outbox: Some(Arc::new(DurableGossipOutbox::new(2))),
        });
        let mut operators = Vec::new();
        for sequence in 1..=3 {
            let (operator, bytes) = operator(sequence);
            assert!(first_source.validate_and_store_gossip(
                [250; 32],
                GossipTopic::Operator,
                operator.object_id(),
                &bytes,
            ));
            operators.push((operator, bytes));
        }
        let legacy = operator(4);
        immutable_put(
            &first_source.store,
            OPERATOR_NAMESPACE,
            &format!("2/{}", hex::encode(legacy.0.object_id())),
            &legacy.1,
        )
        .unwrap();
        operators.push(legacy);
        drop(first_source);
        drop(forward_rx);

        let CertifiedKey { cert, key_pair } =
            generate_simple_self_signed(vec!["localhost".to_owned()]).unwrap();
        let certificate = cert.der().to_vec();
        let server_identity = TransportIdentity::new(SigningKey::from_bytes(&[92; 32]), None);
        let peer_key = server_identity.transport_pubkey();
        let source_store = RedbStore::create(&source_path).unwrap();
        let outbox = Arc::new(DurableGossipOutbox::new(2));
        assert_eq!(
            super::recover_durable_gossip_outbox(
                &source_store,
                2,
                outbox.as_ref(),
                &BTreeSet::from([peer_key]),
                super::GossipOutboxRecoveryProfile::default(),
            )
            .unwrap(),
            4
        );
        let (forward_tx, forward_rx) = GossipForwardRouter::bounded(1);
        let source = Arc::new(DurableOverlayApplication {
            store: source_store,
            network_id: 2,
            parent_admission: None,
            share_admission: None,
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: Some(forward_tx),
            gossip_outbox: Some(outbox),
        });
        let destination = Arc::new(DurableOverlayApplication {
            store: RedbStore::create(destination_directory.path().join(STATE_DATABASE)).unwrap(),
            network_id: 2,
            parent_admission: None,
            share_admission: None,
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: None,
            gossip_outbox: None,
        });
        let (limits, topic_limits) = default_overlay_limits();
        let server = QuicOverlayServer::bind(
            "127.0.0.1:0".parse().unwrap(),
            certificate.clone(),
            key_pair.serialize_der(),
            server_identity,
            2,
            OverlayNode::new(2, limits, topic_limits),
            destination.clone(),
            QuicTransportLimits::default(),
        )
        .unwrap();
        let address = server.local_addr().unwrap();
        let (server_shutdown_tx, server_shutdown_rx) = watch::channel(false);
        let server_task = tokio::spawn(server.run_until(server_shutdown_rx));
        let config = StaticPeerNetworkConfig {
            peers: vec![StaticPeerConfig {
                remote: address,
                server_name: "localhost".to_owned(),
                expected_transport_pubkey: peer_key,
                trusted_server_certificates: vec![certificate],
            }],
            reconnect_initial: Duration::from_millis(20),
            reconnect_maximum: Duration::from_millis(80),
            forward_queue: 1,
            replay_interval: Duration::from_millis(20),
            maximum_replay_objects_per_pass: 2,
            maximum_replay_bytes_per_pass: 1024 * 1024,
        };
        let (peer_shutdown_tx, peer_shutdown_rx) = watch::channel(false);
        let peer_task = tokio::spawn(run_static_peer_network(
            config,
            TransportIdentity::new(SigningKey::from_bytes(&[93; 32]), None),
            2,
            forward_rx,
            source.clone(),
            peer_shutdown_rx,
        ));

        for _ in 0..150 {
            let destination_complete = operators.iter().all(|(operator, bytes)| {
                destination
                    .store
                    .get(
                        OPERATOR_NAMESPACE,
                        &format!("2/{}", hex::encode(operator.object_id())),
                    )
                    .unwrap()
                    .as_deref()
                    == Some(bytes)
            });
            // The remote durable write is visible before its QUIC response is
            // received and the corresponding sender-side ACK is committed.
            // Wait for both sides of that at-least-once handoff instead of
            // racing the final ACK write.
            let acknowledgements =
                super::load_static_peer_acknowledgements(&source.store, 2, peer_key).unwrap();
            let acknowledgements_complete =
                (1..=4).all(|sequence| acknowledgements.contains(sequence));
            if destination_complete && acknowledgements_complete {
                break;
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
        assert!(operators.iter().all(|(operator, bytes)| {
            destination
                .store
                .get(
                    OPERATOR_NAMESPACE,
                    &format!("2/{}", hex::encode(operator.object_id())),
                )
                .unwrap()
                .as_deref()
                == Some(bytes)
        }));
        let acknowledgements =
            super::load_static_peer_acknowledgements(&source.store, 2, peer_key).unwrap();
        for sequence in 1..=4 {
            assert!(acknowledgements.contains(sequence));
        }

        peer_shutdown_tx.send(true).unwrap();
        tokio::time::timeout(Duration::from_secs(1), peer_task)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        server_shutdown_tx.send(true).unwrap();
        tokio::time::timeout(Duration::from_secs(1), server_task)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
    }

    #[test]
    fn publication_intents_recover_each_crash_phase_without_replaying_migrated_history() {
        fn intent(preparation: super::GossipPublicationPreparation) -> String {
            match preparation {
                super::GossipPublicationPreparation::Intent(key) => key,
                other => panic!("expected publication intent, got {other:?}"),
            }
        }

        fn operator(sequence: u64) -> (OperatorRecordV2, Vec<u8>) {
            let signing_key = SigningKey::from_bytes(&[104; 32]);
            let mut operator = OperatorRecordV2 {
                protocol_version: CORE_V2,
                network_id: 2,
                operator_pubkey: signing_key.verifying_key().to_bytes(),
                sequence,
                supported_features: 0,
                payout_bucket_ids: vec![],
                contact_metadata_hash: None,
                signature_suite: ED25519_SUITE,
                signature: SignatureBytes::empty(),
            };
            operator.signature = sign_object(&signing_key, 2, &operator);
            let bytes = canonical_bytes(&operator);
            (operator, bytes)
        }

        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let outbox = DurableGossipOutbox::new(2);
        let intent_namespace =
            super::network_namespace(super::GOSSIP_PUBLICATION_INTENT_NAMESPACE, 2);
        let peer = [105; 32];

        // A crash before authoritative admission leaves a harmless intent that
        // startup discards. The same pass records the one-time operator
        // migration even though there is no historical operator yet.
        let (pre_store, pre_store_bytes) = operator(1);
        let pre_store_intent = intent(
            outbox
                .prepare_publication(
                    &store,
                    GossipTopic::Operator,
                    pre_store.object_id(),
                    peer,
                    &pre_store_bytes,
                )
                .unwrap(),
        );
        assert!(
            store
                .get(&intent_namespace, &pre_store_intent)
                .unwrap()
                .is_some()
        );
        assert_eq!(
            super::recover_durable_gossip_outbox(
                &store,
                2,
                &outbox,
                &BTreeSet::new(),
                super::GossipOutboxRecoveryProfile::default(),
            )
            .unwrap(),
            0
        );
        assert!(
            store
                .get(&intent_namespace, &pre_store_intent)
                .unwrap()
                .is_none()
        );
        assert_eq!(
            super::load_gossip_migration(&store, 2).unwrap(),
            super::GOSSIP_MIGRATION_OPERATOR
        );

        // A crash after the authoritative write but before locator
        // publication is recovered from the exact wrapper intent, including
        // its direct source identity.
        let (post_store, post_store_bytes) = operator(2);
        let post_store_intent = intent(
            outbox
                .prepare_publication(
                    &store,
                    GossipTopic::Operator,
                    post_store.object_id(),
                    peer,
                    &post_store_bytes,
                )
                .unwrap(),
        );
        immutable_put(
            &store,
            OPERATOR_NAMESPACE,
            &format!("2/{}", hex::encode(post_store.object_id())),
            &post_store_bytes,
        )
        .unwrap();
        assert_eq!(
            super::recover_durable_gossip_outbox(
                &store,
                2,
                &outbox,
                &BTreeSet::new(),
                super::GossipOutboxRecoveryProfile::default(),
            )
            .unwrap(),
            1
        );
        assert!(
            store
                .get(&intent_namespace, &post_store_intent)
                .unwrap()
                .is_none()
        );
        assert_eq!(
            super::load_gossip_outbox_source(
                &store,
                2,
                GossipTopic::Operator,
                post_store.object_id(),
            )
            .unwrap(),
            Some(peer)
        );

        // Once a topic group is migrated, an authoritative record without an
        // intent is not blindly replayed. This is the distinction compaction
        // needs between retired history and a real admission crash gap.
        let (untracked, untracked_bytes) = operator(3);
        immutable_put(
            &store,
            OPERATOR_NAMESPACE,
            &format!("2/{}", hex::encode(untracked.object_id())),
            &untracked_bytes,
        )
        .unwrap();
        assert_eq!(
            super::recover_durable_gossip_outbox(
                &store,
                2,
                &outbox,
                &BTreeSet::new(),
                super::GossipOutboxRecoveryProfile::default(),
            )
            .unwrap(),
            1
        );
        assert!(
            store
                .get(
                    &super::network_namespace(super::GOSSIP_OUTBOX_INDEX_NAMESPACE, 2),
                    &super::gossip_outbox_index_key(GossipTopic::Operator, &untracked.object_id(),),
                )
                .unwrap()
                .is_none()
        );
        assert_eq!(
            outbox
                .prepare_publication(
                    &store,
                    GossipTopic::Operator,
                    untracked.object_id(),
                    peer,
                    &untracked_bytes,
                )
                .unwrap(),
            super::GossipPublicationPreparation::RetiredDuplicate
        );
        assert_eq!(
            super::recover_durable_gossip_outbox(
                &store,
                2,
                &outbox,
                &BTreeSet::new(),
                super::GossipOutboxRecoveryProfile::default(),
            )
            .unwrap(),
            1
        );

        // A crash after locator publication but before intent cleanup is
        // idempotent and does not allocate a second sequence.
        let (post_locator, post_locator_bytes) = operator(4);
        let post_locator_intent = intent(
            outbox
                .prepare_publication(
                    &store,
                    GossipTopic::Operator,
                    post_locator.object_id(),
                    peer,
                    &post_locator_bytes,
                )
                .unwrap(),
        );
        immutable_put(
            &store,
            OPERATOR_NAMESPACE,
            &format!("2/{}", hex::encode(post_locator.object_id())),
            &post_locator_bytes,
        )
        .unwrap();
        assert_eq!(
            outbox
                .publish(
                    &store,
                    GossipTopic::Operator,
                    post_locator.object_id(),
                    Some(peer),
                )
                .unwrap(),
            Some(2)
        );
        assert_eq!(
            super::recover_durable_gossip_outbox(
                &store,
                2,
                &outbox,
                &BTreeSet::new(),
                super::GossipOutboxRecoveryProfile::default(),
            )
            .unwrap(),
            2
        );
        assert!(
            store
                .get(&intent_namespace, &post_locator_intent)
                .unwrap()
                .is_none()
        );

        // Signature wrappers share an object ID but not a payload hash. Their
        // intents cannot erase one another.
        let (wrapped, wrapped_bytes) = operator(5);
        let mut alternate_wrapper = wrapped_bytes.clone();
        *alternate_wrapper.last_mut().unwrap() ^= 1;
        let first_wrapper_intent = intent(
            outbox
                .prepare_publication(
                    &store,
                    GossipTopic::Operator,
                    wrapped.object_id(),
                    peer,
                    &wrapped_bytes,
                )
                .unwrap(),
        );
        let second_wrapper_intent = intent(
            outbox
                .prepare_publication(
                    &store,
                    GossipTopic::Operator,
                    wrapped.object_id(),
                    peer,
                    &alternate_wrapper,
                )
                .unwrap(),
        );
        assert_ne!(first_wrapper_intent, second_wrapper_intent);
        outbox
            .clear_publication(&store, &first_wrapper_intent)
            .unwrap();
        assert!(
            store
                .get(&intent_namespace, &second_wrapper_intent)
                .unwrap()
                .is_some()
        );
        outbox
            .clear_publication(&store, &second_wrapper_intent)
            .unwrap();

        store
            .put(&intent_namespace, "malformed", b"malformed")
            .unwrap();
        assert!(
            super::recover_durable_gossip_outbox(
                &store,
                2,
                &outbox,
                &BTreeSet::new(),
                super::GossipOutboxRecoveryProfile::default(),
            )
            .is_err()
        );
        store.delete(&intent_namespace, "malformed").unwrap();
        store
            .put(super::GOSSIP_MIGRATION_NAMESPACE, "2", b"malformed")
            .unwrap();
        assert!(
            super::recover_durable_gossip_outbox(
                &store,
                2,
                &outbox,
                &BTreeSet::new(),
                super::GossipOutboxRecoveryProfile::default(),
            )
            .is_err()
        );
        store
            .put(
                super::GOSSIP_MIGRATION_NAMESPACE,
                "2",
                &super::encode_gossip_migration(2, super::GOSSIP_MIGRATION_OPERATOR),
            )
            .unwrap();
        store
            .put(super::GOSSIP_COMPACTION_NAMESPACE, "2", b"malformed")
            .unwrap();
        assert!(
            super::recover_durable_gossip_outbox(
                &store,
                2,
                &outbox,
                &BTreeSet::new(),
                super::GossipOutboxRecoveryProfile::default(),
            )
            .is_err()
        );
    }

    #[test]
    fn contextual_gossip_migration_is_incremental_and_idempotent() {
        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let fixture = ShareValidationBenchmark::new().artifacts();
        persist_share_context(&store, &fixture);
        let admission = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        validate_and_store_share(
            &store,
            2,
            &admission,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        let outbox = DurableGossipOutbox::new(2);
        assert_eq!(
            super::recover_durable_gossip_outbox(
                &store,
                2,
                &outbox,
                &BTreeSet::new(),
                super::GossipOutboxRecoveryProfile::default(),
            )
            .unwrap(),
            0
        );
        assert_eq!(
            super::load_gossip_migration(&store, 2).unwrap(),
            super::GOSSIP_MIGRATION_OPERATOR
        );
        let share_profile = super::GossipOutboxRecoveryProfile {
            share: true,
            ..super::GossipOutboxRecoveryProfile::default()
        };
        assert_eq!(
            super::recover_durable_gossip_outbox(
                &store,
                2,
                &outbox,
                &BTreeSet::new(),
                share_profile,
            )
            .unwrap(),
            1
        );
        assert_eq!(
            super::load_gossip_migration(&store, 2).unwrap(),
            super::GOSSIP_MIGRATION_OPERATOR | super::GOSSIP_MIGRATION_SHARE
        );
        assert_eq!(
            super::recover_durable_gossip_outbox(
                &store,
                2,
                &outbox,
                &BTreeSet::new(),
                share_profile,
            )
            .unwrap(),
            1
        );
    }

