    #[tokio::test]
    async fn gossip_compaction_rebases_delivery_and_suppresses_retired_live_replay() {
        fn operator(sequence: u64) -> (OperatorRecordV2, Vec<u8>) {
            let signing_key = SigningKey::from_bytes(&[106; 32]);
            let mut operator = OperatorRecordV2 {
                protocol_version: CORE_V2,
                network_id: 2,
                operator_pubkey: signing_key.verifying_key().to_bytes(),
                sequence,
                supported_features: 0,
                payout_bucket_ids: vec![],
                contact_metadata_hash: None,
                signature_suite: ED25519_SUITE,
                signature: SignatureBytes::empty(),
            };
            operator.signature = sign_object(&signing_key, 2, &operator);
            let bytes = canonical_bytes(&operator);
            (operator, bytes)
        }

        let directory = secure_tempdir().unwrap();
        let path = directory.path().join(STATE_DATABASE);
        let peer_one = [107; 32];
        let peer_two = [108; 32];
        let peers = BTreeSet::from([peer_one, peer_two]);
        let outbox = Arc::new(DurableGossipOutbox::new(2));
        let application = Arc::new(DurableOverlayApplication {
            store: RedbStore::create(&path).unwrap(),
            network_id: 2,
            parent_admission: None,
            share_admission: None,
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: None,
            gossip_outbox: Some(outbox.clone()),
        });
        let operators = (1..=6).map(operator).collect::<Vec<_>>();
        for (offset, (operator, bytes)) in operators[..5].iter().enumerate() {
            let source = if offset == 0 { peer_one } else { [109; 32] };
            assert!(application.validate_and_store_gossip(
                source,
                GossipTopic::Operator,
                operator.object_id(),
                bytes,
            ));
        }
        application
            .store
            .put(
                super::GOSSIP_MIGRATION_NAMESPACE,
                "2",
                &super::encode_gossip_migration(2, super::GOSSIP_MIGRATION_OPERATOR),
            )
            .unwrap();
        super::recover_gossip_outbox_metadata(&application.store, 2, &peers).unwrap();
        let mut one =
            super::load_static_peer_acknowledgements(&application.store, 2, peer_one).unwrap();
        for sequence in [1, 2, 4] {
            one.acknowledge(sequence).unwrap();
        }
        one.next_scan_sequence = 5;
        super::persist_static_peer_acknowledgements(&application.store, 2, peer_one, &mut one)
            .unwrap();
        let mut two =
            super::load_static_peer_acknowledgements(&application.store, 2, peer_two).unwrap();
        for sequence in [1, 2, 3] {
            two.acknowledge(sequence).unwrap();
        }
        two.next_scan_sequence = 4;
        super::persist_static_peer_acknowledgements(&application.store, 2, peer_two, &mut two)
            .unwrap();

        // An in-flight admission prevents retirement even when a settled
        // prefix exists. This is the synchronization point between validation
        // and compaction.
        let pending = match outbox
            .prepare_publication(
                &application.store,
                GossipTopic::Operator,
                operators[5].0.object_id(),
                [109; 32],
                &operators[5].1,
            )
            .unwrap()
        {
            super::GossipPublicationPreparation::Intent(key) => key,
            other => panic!("expected publication intent, got {other:?}"),
        };
        assert_eq!(
            super::compact_durable_gossip_outbox(&application.store, 2, &peers, 1)
                .unwrap()
                .retired_objects,
            0
        );
        outbox
            .clear_publication(&application.store, &pending)
            .unwrap();

        let compacted =
            super::compact_durable_gossip_outbox(&application.store, 2, &peers, 1).unwrap();
        assert_eq!(compacted.retired_objects, 2);
        assert_eq!(compacted.remaining_objects, 3);
        assert_eq!(
            compacted.state,
            super::GossipCompactionState {
                generation: 1,
                retired_objects: 2,
            }
        );
        let records = application
            .store
            .scan_namespace(
                &super::network_namespace(super::GOSSIP_OUTBOX_NAMESPACE, 2),
                meshmine_storage::ScanLimits {
                    maximum_records: 8,
                    maximum_value_bytes: 64,
                    maximum_total_bytes: 1024,
                },
            )
            .unwrap();
        assert_eq!(records.len(), 3);
        for (offset, record) in records.iter().enumerate() {
            let locator = super::decode_gossip_outbox_locator(&record.value, 2).unwrap();
            assert_eq!(locator.sequence, u64::try_from(offset).unwrap() + 1);
            assert_eq!(locator.object_id, operators[offset + 2].0.object_id());
        }
        assert_eq!(
            super::load_active_gossip_sequence(
                &application.store,
                2,
                GossipTopic::Operator,
                operators[0].0.object_id(),
            )
            .unwrap(),
            None
        );
        assert_eq!(
            super::load_gossip_outbox_source(
                &application.store,
                2,
                GossipTopic::Operator,
                operators[0].0.object_id(),
            )
            .unwrap(),
            None
        );
        let one =
            super::load_static_peer_acknowledgements(&application.store, 2, peer_one).unwrap();
        assert!(!one.contains(1));
        assert!(one.contains(2));
        assert_eq!(one.next_scan_sequence, 1);
        let two =
            super::load_static_peer_acknowledgements(&application.store, 2, peer_two).unwrap();
        assert!(two.contains(1));
        assert!(!two.contains(2));

        // A queued source acknowledgement resolves the object's current
        // rebased locator, not its stale pre-compaction sequence.
        super::acknowledge_static_peer_gossip(
            application.clone(),
            peer_one,
            GossipTopic::Operator,
            operators[2].0.object_id(),
            StaticPeerDeliveryControl::new(),
        )
        .await
        .unwrap();
        assert!(
            super::load_static_peer_acknowledgements(&application.store, 2, peer_one,)
                .unwrap()
                .contains(1)
        );

        // Exact old network gossip remains valid protocol evidence but is a
        // retired delivery duplicate, so it cannot resurrect its locator.
        assert!(application.validate_and_store_gossip(
            peer_two,
            GossipTopic::Operator,
            operators[0].0.object_id(),
            &operators[0].1,
        ));
        let mut alternate_retired_wrapper = operators[0].1.clone();
        *alternate_retired_wrapper.last_mut().unwrap() ^= 1;
        assert!(!application.validate_and_store_gossip(
            peer_two,
            GossipTopic::Operator,
            operators[0].0.object_id(),
            &alternate_retired_wrapper,
        ));
        assert_eq!(
            super::observe_durable_gossip_delivery(&application.store, 2)
                .unwrap()
                .durable_objects,
            3
        );
        drop(application);
        drop(outbox);

        let store = RedbStore::create(&path).unwrap();
        let outbox = Arc::new(DurableGossipOutbox::new(2));
        assert_eq!(
            super::recover_durable_gossip_outbox(
                &store,
                2,
                outbox.as_ref(),
                &peers,
                super::GossipOutboxRecoveryProfile::default(),
            )
            .unwrap(),
            3
        );
        assert_eq!(
            super::load_gossip_compaction(&store, 2).unwrap(),
            super::GossipCompactionState {
                generation: 1,
                retired_objects: 2,
            }
        );
        let restarted = DurableOverlayApplication {
            store,
            network_id: 2,
            parent_admission: None,
            share_admission: None,
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: None,
            gossip_outbox: Some(outbox),
        };
        assert!(restarted.validate_and_store_gossip(
            [109; 32],
            GossipTopic::Operator,
            operators[5].0.object_id(),
            &operators[5].1,
        ));
        assert_eq!(
            super::load_active_gossip_sequence(
                &restarted.store,
                2,
                GossipTopic::Operator,
                operators[5].0.object_id(),
            )
            .unwrap(),
            Some(4)
        );
        let observed = super::observe_durable_gossip_delivery(&restarted.store, 2).unwrap();
        assert_eq!(observed.durable_objects, 4);
        assert_eq!(observed.compaction_generation, 1);
        assert_eq!(observed.retired_objects_total, 2);
    }

    #[test]
    fn production_compaction_threshold_reclaims_capacity_repeatedly() {
        assert_eq!(
            super::gossip_compaction_required_prefix(
                super::GOSSIP_COMPACTION_HIGH_WATER - 1,
                super::MIN_GOSSIP_COMPACTION_PREFIX,
            ),
            super::MIN_GOSSIP_COMPACTION_PREFIX
        );
        assert_eq!(
            super::gossip_compaction_required_prefix(
                super::GOSSIP_COMPACTION_HIGH_WATER,
                super::MIN_GOSSIP_COMPACTION_PREFIX,
            ),
            1
        );
        let store = MemoryStore::default();
        let outbox = DurableGossipOutbox::new(2);
        let peer = [110; 32];
        let peers = BTreeSet::from([peer]);
        let mut object_ids = Vec::new();
        for sequence in 1..=super::MIN_GOSSIP_COMPACTION_PREFIX {
            let mut object_id = [0; 32];
            object_id[..8].copy_from_slice(&u64::try_from(sequence).unwrap().to_le_bytes());
            store
                .put(
                    OPERATOR_NAMESPACE,
                    &format!("2/{}", hex::encode(object_id)),
                    b"authoritative",
                )
                .unwrap();
            assert_eq!(
                outbox
                    .publish(&store, GossipTopic::Operator, object_id, None)
                    .unwrap(),
                Some(u64::try_from(sequence).unwrap())
            );
            object_ids.push(object_id);
        }
        super::recover_gossip_outbox_metadata(&store, 2, &peers).unwrap();
        let mut acknowledgements =
            super::load_static_peer_acknowledgements(&store, 2, peer).unwrap();
        for sequence in 1..=u64::try_from(object_ids.len()).unwrap() {
            acknowledgements.acknowledge(sequence).unwrap();
        }
        super::persist_static_peer_acknowledgements(&store, 2, peer, &mut acknowledgements)
            .unwrap();
        assert!(outbox.compact(&store, &peers).is_err());
        store
            .put(
                super::GOSSIP_MIGRATION_NAMESPACE,
                "2",
                &super::encode_gossip_migration(2, super::GOSSIP_MIGRATION_OPERATOR),
            )
            .unwrap();
        let first = outbox.compact(&store, &peers).unwrap();
        assert_eq!(first.retired_objects, object_ids.len());
        assert_eq!(first.remaining_objects, 0);
        assert_eq!(first.state.generation, 1);

        let replacement = [111; 32];
        store
            .put(
                OPERATOR_NAMESPACE,
                &format!("2/{}", hex::encode(replacement)),
                b"replacement",
            )
            .unwrap();
        assert_eq!(
            outbox
                .publish(&store, GossipTopic::Operator, replacement, None)
                .unwrap(),
            Some(1)
        );
        let mut acknowledgements =
            super::load_static_peer_acknowledgements(&store, 2, peer).unwrap();
        acknowledgements.acknowledge(1).unwrap();
        super::persist_static_peer_acknowledgements(&store, 2, peer, &mut acknowledgements)
            .unwrap();
        let second = super::compact_durable_gossip_outbox(&store, 2, &peers, 1).unwrap();
        assert_eq!(second.retired_objects, 1);
        assert_eq!(second.remaining_objects, 0);
        assert_eq!(second.state.generation, 2);
        assert_eq!(
            second.state.retired_objects,
            u64::try_from(object_ids.len() + 1).unwrap()
        );
        let observed = super::observe_durable_gossip_delivery(&store, 2).unwrap();
        assert_eq!(observed.durable_objects, 0);
        assert_eq!(
            observed.remaining_capacity_objects,
            super::MAX_GOSSIP_OUTBOX_RECORDS
        );
        assert_eq!(observed.compaction_generation, 2);
        assert_eq!(
            observed.retired_objects_total,
            u64::try_from(object_ids.len() + 1).unwrap()
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn static_peer_supervisor_compacts_a_settled_production_prefix() {
        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let peer = [114; 32];
        let mut operations = Vec::new();
        let outbox_namespace = super::network_namespace(super::GOSSIP_OUTBOX_NAMESPACE, 2);
        let index_namespace = super::network_namespace(super::GOSSIP_OUTBOX_INDEX_NAMESPACE, 2);
        for sequence in 1..=super::MIN_GOSSIP_COMPACTION_PREFIX {
            let sequence = u64::try_from(sequence).unwrap();
            let mut object_id = [0; 32];
            object_id[..8].copy_from_slice(&sequence.to_le_bytes());
            operations.push(super::BatchOperation::put(
                OPERATOR_NAMESPACE,
                format!("2/{}", hex::encode(object_id)),
                b"authoritative".to_vec(),
            ));
            let locator = super::GossipOutboxLocator {
                sequence,
                topic: GossipTopic::Operator,
                object_id,
            };
            operations.push(super::BatchOperation::put(
                outbox_namespace.clone(),
                super::gossip_outbox_sequence_key(sequence),
                super::encode_gossip_outbox_locator(2, &locator),
            ));
            operations.push(super::BatchOperation::put(
                index_namespace.clone(),
                super::gossip_outbox_index_key(GossipTopic::Operator, &object_id),
                sequence.to_le_bytes().to_vec(),
            ));
        }
        operations.push(super::BatchOperation::put(
            super::GOSSIP_OUTBOX_COUNTER_NAMESPACE,
            "2",
            u64::try_from(super::MIN_GOSSIP_COMPACTION_PREFIX)
                .unwrap()
                .to_le_bytes()
                .to_vec(),
        ));
        operations.push(super::BatchOperation::put(
            super::GOSSIP_MIGRATION_NAMESPACE,
            "2",
            super::encode_gossip_migration(2, super::GOSSIP_MIGRATION_OPERATOR),
        ));
        let mut acknowledgements = super::StaticPeerAcknowledgements::default();
        for sequence in 1..=u64::try_from(super::MIN_GOSSIP_COMPACTION_PREFIX).unwrap() {
            acknowledgements.acknowledge(sequence).unwrap();
        }
        operations.push(super::BatchOperation::put(
            super::network_namespace(super::STATIC_PEER_ACK_NAMESPACE, 2),
            hex::encode(peer),
            super::encode_static_peer_acknowledgements(2, peer, &acknowledgements),
        ));
        store.apply_batch(&operations).unwrap();

        let application = Arc::new(DurableOverlayApplication {
            store,
            network_id: 2,
            parent_admission: None,
            share_admission: None,
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: None,
            gossip_outbox: Some(Arc::new(DurableGossipOutbox::new(2))),
        });
        let CertifiedKey { cert, .. } =
            generate_simple_self_signed(vec!["localhost".to_owned()]).unwrap();
        let probe = std::net::UdpSocket::bind("127.0.0.1:0").unwrap();
        let remote = probe.local_addr().unwrap();
        drop(probe);
        let config = StaticPeerNetworkConfig {
            peers: vec![StaticPeerConfig {
                remote,
                server_name: "localhost".to_owned(),
                expected_transport_pubkey: peer,
                trusted_server_certificates: vec![cert.der().to_vec()],
            }],
            reconnect_initial: Duration::from_millis(20),
            reconnect_maximum: Duration::from_millis(40),
            forward_queue: 1,
            replay_interval: Duration::from_millis(20),
            maximum_replay_objects_per_pass: 1,
            maximum_replay_bytes_per_pass: 1024 * 1024,
        };
        super::recover_durable_gossip_outbox(
            &application.store,
            2,
            application.gossip_outbox.as_ref().unwrap().as_ref(),
            &BTreeSet::from([peer]),
            super::GossipOutboxRecoveryProfile::default(),
        )
        .unwrap();
        let (_forward_tx, forward_rx) = GossipForwardRouter::bounded(1);
        let (shutdown_tx, shutdown_rx) = watch::channel(false);
        let task = tokio::spawn(run_static_peer_network(
            config,
            TransportIdentity::new(SigningKey::from_bytes(&[115; 32]), None),
            2,
            forward_rx,
            application.clone(),
            shutdown_rx,
        ));
        for _ in 0..100 {
            if super::load_gossip_compaction(&application.store, 2)
                .unwrap()
                .generation
                == 1
            {
                break;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
        let observed = super::observe_durable_gossip_delivery(&application.store, 2).unwrap();
        assert_eq!(observed.durable_objects, 0);
        assert_eq!(observed.compaction_generation, 1);
        assert_eq!(
            observed.retired_objects_total,
            u64::try_from(super::MIN_GOSSIP_COMPACTION_PREFIX).unwrap()
        );
        shutdown_tx.send(true).unwrap();
        tokio::time::timeout(Duration::from_secs(1), task)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
    }

    #[tokio::test]
    async fn durable_outbox_repairs_indexes_rotates_retries_and_suppresses_source_echo() {
        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let outbox = Arc::new(DurableGossipOutbox::new(2));
        let (forward_tx, mut forward_rx) = GossipForwardRouter::bounded(1);
        let application = Arc::new(DurableOverlayApplication {
            store,
            network_id: 2,
            parent_admission: None,
            share_admission: None,
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: Some(forward_tx),
            gossip_outbox: Some(outbox.clone()),
        });
        let signing_key = SigningKey::from_bytes(&[94; 32]);
        let peer = [95; 32];
        for sequence in 1..=5 {
            let mut operator = OperatorRecordV2 {
                protocol_version: CORE_V2,
                network_id: 2,
                operator_pubkey: signing_key.verifying_key().to_bytes(),
                sequence,
                supported_features: 0,
                payout_bucket_ids: vec![],
                contact_metadata_hash: None,
                signature_suite: ED25519_SUITE,
                signature: SignatureBytes::empty(),
            };
            operator.signature = sign_object(&signing_key, 2, &operator);
            assert!(application.validate_and_store_gossip(
                [250; 32],
                GossipTopic::Operator,
                operator.object_id(),
                &canonical_bytes(&operator),
            ));
        }
        let mut source_operator = OperatorRecordV2 {
            protocol_version: CORE_V2,
            network_id: 2,
            operator_pubkey: signing_key.verifying_key().to_bytes(),
            sequence: 6,
            supported_features: 0,
            payout_bucket_ids: vec![],
            contact_metadata_hash: None,
            signature_suite: ED25519_SUITE,
            signature: SignatureBytes::empty(),
        };
        source_operator.signature = sign_object(&signing_key, 2, &source_operator);
        assert!(application.validate_and_store_gossip(
            peer,
            GossipTopic::Operator,
            source_operator.object_id(),
            &canonical_bytes(&source_operator),
        ));
        let mut invalid_wrapper = canonical_bytes(&source_operator);
        *invalid_wrapper.last_mut().unwrap() ^= 1;
        assert!(!application.validate_and_store_gossip(
            peer,
            GossipTopic::Operator,
            source_operator.object_id(),
            &invalid_wrapper,
        ));
        assert!(
            application
                .store
                .scan_namespace(
                    &super::network_namespace(super::GOSSIP_PUBLICATION_INTENT_NAMESPACE, 2),
                    meshmine_storage::ScanLimits {
                        maximum_records: super::MAX_GOSSIP_PUBLICATION_INTENTS,
                        maximum_value_bytes: 128,
                        maximum_total_bytes: (super::MAX_GOSSIP_PUBLICATION_INTENTS * 128) as u64,
                    },
                )
                .unwrap()
                .is_empty()
        );
        let first = forward_rx.accounting.recv().await.unwrap();
        let index_namespace = super::network_namespace(super::GOSSIP_OUTBOX_INDEX_NAMESPACE, 2);
        application
            .store
            .delete(
                &index_namespace,
                &super::gossip_outbox_index_key(first.topic, &first.object_id),
            )
            .unwrap();
        super::recover_gossip_outbox_metadata(&application.store, 2, &BTreeSet::from([peer]))
            .unwrap();
        assert!(
            application
                .store
                .get(
                    &index_namespace,
                    &super::gossip_outbox_index_key(first.topic, &first.object_id),
                )
                .unwrap()
                .is_some()
        );

        let mut acknowledgements = super::StaticPeerAcknowledgements {
            next_scan_sequence: 4,
            acknowledged: vec![],
        };
        acknowledgements.acknowledge(4).unwrap();
        super::persist_static_peer_acknowledgements(
            &application.store,
            2,
            peer,
            &mut acknowledgements,
        )
        .unwrap();
        let (rotated, replay, changed) =
            super::load_static_peer_replay_batch(&application, peer, 2, 1024 * 1024).unwrap();
        assert!(changed);
        assert_eq!(
            replay
                .iter()
                .map(|object| object.sequence)
                .collect::<Vec<_>>(),
            vec![5, 1]
        );
        assert_eq!(rotated.next_scan_sequence, 2);
        assert!(rotated.contains(6));

        let connected = Arc::new(RwLock::new(BTreeMap::new()));
        let delivery = StaticPeerDeliveryControl::new();
        super::forward_gossip_to_static_peers(
            application.clone(),
            connected,
            Arc::new(BTreeMap::from([(peer, delivery)])),
            ForwardedGossip {
                source_peer: peer,
                ..first
            },
        )
        .await
        .unwrap();
        assert!(
            super::load_static_peer_acknowledgements(&application.store, 2, peer)
                .unwrap()
                .contains(1)
        );

        let ack_namespace = super::network_namespace(super::STATIC_PEER_ACK_NAMESPACE, 2);
        application
            .store
            .put(&ack_namespace, &hex::encode(peer), b"malformed")
            .unwrap();
        assert!(
            super::recover_gossip_outbox_metadata(&application.store, 2, &BTreeSet::from([peer]),)
                .is_err()
        );
    }

