    #[test]
    fn reorg_closed_share_is_suppressed_and_compacted_without_a_peer_acknowledgement() {
        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        persist_share_context(&store, &fixture);
        let shares = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        validate_and_store_share(
            &store,
            2,
            &shares,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        let peer = [130; 32];
        let outbox = Arc::new(DurableGossipOutbox::new(2));
        assert_eq!(
            outbox
                .publish(&store, GossipTopic::Share, fixture.share.object_id(), None,)
                .unwrap(),
            Some(1)
        );
        super::recover_gossip_outbox_metadata(&store, 2, &BTreeSet::from([peer])).unwrap();
        store
            .put(
                REORG_CLOSED_SESSION_NAMESPACE,
                &hex::encode(fixture.session.object_id()),
                &11u64.to_le_bytes(),
            )
            .unwrap();
        let application = DurableOverlayApplication {
            store,
            network_id: 2,
            parent_admission: None,
            share_admission: None,
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: None,
            gossip_outbox: Some(outbox),
        };
        let (acknowledgements, replay, _) =
            super::load_static_peer_replay_batch(&application, peer, 8, 1024 * 1024).unwrap();
        assert!(replay.is_empty());
        assert!(!acknowledgements.contains(1));
        application
            .store
            .put(
                super::GOSSIP_MIGRATION_NAMESPACE,
                "2",
                &super::encode_gossip_migration(2, super::GOSSIP_MIGRATION_SHARE),
            )
            .unwrap();
        let observed = super::observe_durable_gossip_delivery(&application.store, 2).unwrap();
        assert_eq!(observed.locally_suppressed_objects, 1);
        assert_eq!(observed.tracked_peers[0].settled_objects, 0);
        assert_eq!(observed.tracked_peers[0].locally_suppressed_objects, 1);
        assert_eq!(observed.tracked_peers[0].pending_objects, 0);
        let compacted =
            super::compact_durable_gossip_outbox(&application.store, 2, &BTreeSet::from([peer]), 1)
                .unwrap();
        assert_eq!(compacted.retired_objects, 1);
        assert_eq!(compacted.remaining_objects, 0);
        assert!(
            super::load_static_peer_acknowledgements(&application.store, 2, peer)
                .unwrap()
                .acknowledged
                .is_empty()
        );
        assert!(
            ProtocolJournal::new(&application.store)
                .load(
                    ProtocolRecordKind::AcceptedShare,
                    &fixture.share.object_id(),
                )
                .unwrap()
                .is_some()
        );
    }

    #[test]
    fn durable_outbox_recovers_every_composed_contextual_gossip_topic_in_dependency_order() {
        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        persist_share_context(&store, &fixture);
        initialize_parent_reorg_repair(&store, 2);
        validate_and_store_parent(
            &store,
            2,
            &ParentAdmission {
                roster: fixture.settlement_roster.clone(),
                oracle: Arc::new(ParentOracle(true)),
            },
            fixture.parent.object_id(),
            &canonical_bytes(&fixture.parent),
        )
        .unwrap();
        let shares = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        validate_and_store_share(
            &store,
            2,
            &shares,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        let (batch, close) = certified_receipt_and_close(&benchmark, &fixture);
        let receipts = receipt_admission(&store, &fixture);
        validate_and_store_receipt_batch(
            &store,
            2,
            &receipts,
            batch.object_id(),
            &canonical_bytes(&batch),
        )
        .unwrap();
        validate_and_store_session_close(
            &store,
            2,
            &receipts,
            close.object_id(),
            &canonical_bytes(&close),
        )
        .unwrap();
        let entropy_hash = [98; 32];
        let oracle = Arc::new(MutableCanonicalOracle::default());
        oracle.set(fixture.parent.parent_height + 1, entropy_hash, true);
        let payouts = payout_admission(&store, &fixture, oracle, [99; 32]);
        let (snapshot, plan) =
            certified_snapshot_and_plan(&benchmark, &fixture, &close, entropy_hash, [99; 32]);
        validate_and_store_payout_snapshot(
            &store,
            2,
            &payouts,
            snapshot.object_id(),
            &canonical_bytes(&snapshot),
        )
        .unwrap();
        validate_and_store_payout_plan(
            &store,
            2,
            &payouts,
            plan.object_id(),
            &canonical_bytes(&plan),
        )
        .unwrap();

        let outbox = DurableGossipOutbox::new(2);
        assert_eq!(
            super::recover_durable_gossip_outbox(
                &store,
                2,
                &outbox,
                &BTreeSet::new(),
                super::GossipOutboxRecoveryProfile {
                    parent: true,
                    share: true,
                    receipt: true,
                    payout: true,
                },
            )
            .unwrap(),
            6
        );
        let records = store
            .scan_namespace(
                &super::network_namespace(super::GOSSIP_OUTBOX_NAMESPACE, 2),
                meshmine_storage::ScanLimits {
                    maximum_records: 16,
                    maximum_value_bytes: 64,
                    maximum_total_bytes: 1024,
                },
            )
            .unwrap();
        let topics = records
            .iter()
            .map(|record| {
                super::decode_gossip_outbox_locator(&record.value, 2)
                    .unwrap()
                    .topic
            })
            .collect::<Vec<_>>();
        assert_eq!(
            topics,
            vec![
                GossipTopic::Parent,
                GossipTopic::Share,
                GossipTopic::ReceiptBatch,
                GossipTopic::SessionClose,
                GossipTopic::PayoutSnapshot,
                GossipTopic::PayoutPlan,
            ]
        );
        assert_eq!(
            super::load_gossip_migration(&store, 2).unwrap(),
            super::GOSSIP_MIGRATION_ALL
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn static_peer_supervisor_refuses_an_unexpected_transport_identity() {
        let CertifiedKey { cert, key_pair } =
            generate_simple_self_signed(vec!["localhost".to_owned()]).unwrap();
        let certificate = cert.der().to_vec();
        let server_identity = TransportIdentity::new(SigningKey::from_bytes(&[81; 32]), None);
        let directory = secure_tempdir().unwrap();
        let destination = Arc::new(DurableOverlayApplication {
            store: RedbStore::create(directory.path().join("destination.redb")).unwrap(),
            network_id: 2,
            parent_admission: None,
            share_admission: None,
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: None,
            gossip_outbox: None,
        });
        let (limits, topic_limits) = default_overlay_limits();
        let server = QuicOverlayServer::bind(
            "127.0.0.1:0".parse().unwrap(),
            certificate.clone(),
            key_pair.serialize_der(),
            server_identity,
            2,
            OverlayNode::new(2, limits, topic_limits),
            destination.clone(),
            QuicTransportLimits::default(),
        )
        .unwrap();
        let address = server.local_addr().unwrap();
        let (server_shutdown_tx, server_shutdown_rx) = watch::channel(false);
        let server_task = tokio::spawn(server.run_until(server_shutdown_rx));

        let (forward_tx, forward_rx) = GossipForwardRouter::bounded(8);
        let source = Arc::new(DurableOverlayApplication {
            store: RedbStore::create(directory.path().join("source.redb")).unwrap(),
            network_id: 2,
            parent_admission: None,
            share_admission: None,
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: Some(forward_tx),
            gossip_outbox: Some(Arc::new(DurableGossipOutbox::new(2))),
        });
        let config = StaticPeerNetworkConfig {
            peers: vec![StaticPeerConfig {
                remote: address,
                server_name: "localhost".to_owned(),
                expected_transport_pubkey: [82; 32],
                trusted_server_certificates: vec![certificate],
            }],
            reconnect_initial: Duration::from_millis(20),
            reconnect_maximum: Duration::from_millis(40),
            forward_queue: 8,
            replay_interval: Duration::from_millis(20),
            maximum_replay_objects_per_pass: 8,
            maximum_replay_bytes_per_pass: 1024 * 1024,
        };
        super::recover_durable_gossip_outbox(
            &source.store,
            2,
            source.gossip_outbox.as_ref().unwrap().as_ref(),
            &BTreeSet::from([[82; 32]]),
            super::GossipOutboxRecoveryProfile::default(),
        )
        .unwrap();
        let (peer_shutdown_tx, peer_shutdown_rx) = watch::channel(false);
        let peer_task = tokio::spawn(run_static_peer_network(
            config,
            TransportIdentity::new(SigningKey::from_bytes(&[83; 32]), None),
            2,
            forward_rx,
            source.clone(),
            peer_shutdown_rx,
        ));

        let signing_key = SigningKey::from_bytes(&[84; 32]);
        let mut operator = OperatorRecordV2 {
            protocol_version: CORE_V2,
            network_id: 2,
            operator_pubkey: signing_key.verifying_key().to_bytes(),
            sequence: 1,
            supported_features: 0,
            payout_bucket_ids: vec![],
            contact_metadata_hash: None,
            signature_suite: ED25519_SUITE,
            signature: SignatureBytes::empty(),
        };
        operator.signature = sign_object(&signing_key, 2, &operator);
        let object_id = operator.object_id();
        let bytes = canonical_bytes(&operator);
        for _ in 0..15 {
            assert!(source.validate_and_store_gossip(
                [250; 32],
                GossipTopic::Operator,
                object_id,
                &bytes,
            ));
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
        assert_eq!(
            destination
                .store
                .get(OPERATOR_NAMESPACE, &format!("2/{}", hex::encode(object_id)),)
                .unwrap(),
            None
        );

        peer_shutdown_tx.send(true).unwrap();
        tokio::time::timeout(Duration::from_secs(1), peer_task)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        server_shutdown_tx.send(true).unwrap();
        tokio::time::timeout(Duration::from_secs(1), server_task)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
    }

    #[tokio::test]
    async fn live_observability_http_is_bounded_read_only_and_shutdown_aware() {
        async fn request(address: std::net::SocketAddr, request: &[u8]) -> Vec<u8> {
            let mut stream = TcpStream::connect(address).await.unwrap();
            stream.write_all(request).await.unwrap();
            let mut response = Vec::new();
            stream.read_to_end(&mut response).await.unwrap();
            response
        }

        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let application = Arc::new(DurableOverlayApplication {
            store,
            network_id: 2,
            parent_admission: None,
            share_admission: None,
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: None,
            gossip_outbox: None,
        });
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let (shutdown_tx, shutdown_rx) = watch::channel(false);
        let task = tokio::spawn(run_observability_http_server(
            listener,
            application,
            vec![],
            shutdown_rx,
        ));

        let response = request(
            address,
            b"GET /v1/observability HTTP/1.1\r\nHost: localhost\r\n\r\n",
        )
        .await;
        assert!(response.starts_with(b"HTTP/1.1 200 OK\r\n"));
        assert!(
            response
                .windows(b"Cache-Control: no-store".len())
                .any(|window| window == b"Cache-Control: no-store")
        );
        let body = response
            .windows(4)
            .position(|window| window == b"\r\n\r\n")
            .map(|index| &response[index + 4..])
            .unwrap();
        let json: serde_json::Value = serde_json::from_slice(body).unwrap();
        assert_eq!(json["schema_version"], 3);
        assert_eq!(json["network_id"], 2);
        assert_eq!(json["gossip_delivery"]["durable_objects"], 0);
        assert_eq!(json["gossip_delivery"]["pending_publication_intents"], 0);
        assert_eq!(
            json["gossip_delivery"]["migrated_topic_groups"],
            serde_json::json!([])
        );
        assert_eq!(json["gossip_delivery"]["compaction_generation"], 0);
        assert_eq!(json["gossip_delivery"]["retired_objects_total"], 0);
        assert!(json["gossip_delivery"]["tracked_peers"].is_array());

        let response = request(
            address,
            b"POST /v1/observability HTTP/1.1\r\nHost: localhost\r\n\r\n",
        )
        .await;
        assert!(response.starts_with(b"HTTP/1.1 405 Method Not Allowed\r\n"));
        assert!(
            response
                .windows(b"Allow: GET".len())
                .any(|window| window == b"Allow: GET")
        );

        let response = request(address, b"GET /unknown HTTP/1.1\r\nHost: localhost\r\n\r\n").await;
        assert!(response.starts_with(b"HTTP/1.1 404 Not Found\r\n"));

        let mut oversized = b"GET /v1/observability HTTP/1.1\r\nX-Fill: ".to_vec();
        oversized.resize(MAX_OBSERVABILITY_HTTP_HEADER_BYTES, b'x');
        let response = request(address, &oversized).await;
        assert!(response.starts_with(b"HTTP/1.1 431 Request Header Fields Too Large\r\n"));

        shutdown_tx.send(true).unwrap();
        tokio::time::timeout(std::time::Duration::from_secs(1), task)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
    }

    #[test]
    fn bounded_observability_reports_exact_durable_metrics_and_fails_closed() {
        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        persist_share_context(&store, &fixture);
        let share_admission = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        validate_and_store_share(
            &store,
            2,
            &share_admission,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        let (batch, close) = certified_receipt_and_close(&benchmark, &fixture);
        let receipt_admission = receipt_admission(&store, &fixture);
        validate_and_store_receipt_batch(
            &store,
            2,
            &receipt_admission,
            batch.object_id(),
            &canonical_bytes(&batch),
        )
        .unwrap();
        validate_and_store_session_close(
            &store,
            2,
            &receipt_admission,
            close.object_id(),
            &canonical_bytes(&close),
        )
        .unwrap();
        let entropy_hash = [91; 32];
        let oracle = Arc::new(MutableCanonicalOracle::default());
        oracle.set(fixture.parent.parent_height + 1, entropy_hash, true);
        let payout_admission = payout_admission(&store, &fixture, oracle, [92; 32]);
        let (snapshot, plan) =
            certified_snapshot_and_plan(&benchmark, &fixture, &close, entropy_hash, [92; 32]);
        validate_and_store_payout_snapshot(
            &store,
            2,
            &payout_admission,
            snapshot.object_id(),
            &canonical_bytes(&snapshot),
        )
        .unwrap();
        validate_and_store_payout_plan(
            &store,
            2,
            &payout_admission,
            plan.object_id(),
            &canonical_bytes(&plan),
        )
        .unwrap();
        let rosters = vec![
            fixture.mask_roster.clone(),
            fixture.receipt_roster.clone(),
            fixture.availability_roster.clone(),
            fixture.settlement_roster.clone(),
        ];
        let observed = build_observability_snapshot(&store, 2, &rosters).unwrap();
        assert_eq!(observed.schema_version, 3);
        assert_eq!(observed.gossip_delivery.durable_objects, 0);
        assert_eq!(observed.gossip_delivery.pending_publication_intents, 0);
        assert!(observed.gossip_delivery.migrated_topic_groups.is_empty());
        assert_eq!(observed.gossip_delivery.compaction_generation, 0);
        assert_eq!(observed.gossip_delivery.retired_objects_total, 0);
        assert!(observed.gossip_delivery.tracked_peers.is_empty());
        assert_eq!(observed.gossip_delivery.pending_for_any_tracked_peer, None);
        assert_eq!(observed.templates.body_packages, 1);
        assert_eq!(observed.templates.unique_template_cores, 1);
        assert_eq!(observed.availability.availability_certificates, 1);
        assert_eq!(observed.availability.certified_body_packages, 1);
        assert_eq!(observed.shares.accepted_shares, 1);
        assert_eq!(observed.shares.receipt_credited_shares, 1);
        assert_eq!(observed.shares.uncredited_shares, 0);
        assert_eq!(observed.shares.credited_work_by_operator.len(), 1);
        assert_eq!(observed.sessions.certified_closes, 1);
        assert_eq!(observed.assignments.assignments, 1);
        assert_eq!(observed.committees.configured_rosters.len(), 4);
        assert_eq!(observed.committees.key_overlaps.len(), 6);
        let payout = observed.payout.latest_snapshot.unwrap();
        assert_eq!(payout.snapshot_id, hex::encode(snapshot.object_id()));
        assert_eq!(payout.work_buckets.len(), 1);
        assert_eq!(payout.plans.len(), 1);
        assert!(observed.coverage.iter().any(|coverage| {
            coverage.metric == "asic_job_switch_latency" && coverage.status == "unavailable"
        }));

        let outbox = DurableGossipOutbox::new(2);
        let first_sequence = outbox
            .publish(&store, GossipTopic::Share, fixture.share.object_id(), None)
            .unwrap()
            .unwrap();
        let source_peer = [101; 32];
        let second_sequence = outbox
            .publish(
                &store,
                GossipTopic::ReceiptBatch,
                batch.object_id(),
                Some(source_peer),
            )
            .unwrap()
            .unwrap();
        let third_sequence = outbox
            .publish(&store, GossipTopic::PayoutPlan, plan.object_id(), None)
            .unwrap()
            .unwrap();
        assert_eq!((first_sequence, second_sequence, third_sequence), (1, 2, 3));
        let pending_intent = match outbox
            .prepare_publication(
                &store,
                GossipTopic::Share,
                fixture.share.object_id(),
                [104; 32],
                &canonical_bytes(&fixture.share),
            )
            .unwrap()
        {
            super::GossipPublicationPreparation::Intent(key) => key,
            other => panic!("expected publication intent, got {other:?}"),
        };
        store
            .put(
                super::GOSSIP_MIGRATION_NAMESPACE,
                "2",
                &super::encode_gossip_migration(
                    2,
                    super::GOSSIP_MIGRATION_OPERATOR | super::GOSSIP_MIGRATION_SHARE,
                ),
            )
            .unwrap();
        let second_peer = [102; 32];
        let zero_ack_peer = [103; 32];
        super::recover_gossip_outbox_metadata(
            &store,
            2,
            &BTreeSet::from([source_peer, second_peer, zero_ack_peer]),
        )
        .unwrap();
        let mut source_acknowledgements =
            super::load_static_peer_acknowledgements(&store, 2, source_peer).unwrap();
        source_acknowledgements.acknowledge(1).unwrap();
        source_acknowledgements.acknowledge(2).unwrap();
        super::persist_static_peer_acknowledgements(
            &store,
            2,
            source_peer,
            &mut source_acknowledgements,
        )
        .unwrap();
        let mut second_acknowledgements =
            super::load_static_peer_acknowledgements(&store, 2, second_peer).unwrap();
        second_acknowledgements.acknowledge(1).unwrap();
        super::persist_static_peer_acknowledgements(
            &store,
            2,
            second_peer,
            &mut second_acknowledgements,
        )
        .unwrap();
        let delivery_observed = build_observability_snapshot(&store, 2, &rosters).unwrap();
        assert_eq!(delivery_observed.gossip_delivery.durable_objects, 3);
        assert_eq!(
            delivery_observed
                .gossip_delivery
                .pending_publication_intents,
            1
        );
        assert_eq!(
            delivery_observed.gossip_delivery.migrated_topic_groups,
            vec!["operator".to_owned(), "share".to_owned()]
        );
        assert_eq!(delivery_observed.gossip_delivery.compaction_generation, 0);
        assert_eq!(delivery_observed.gossip_delivery.retired_objects_total, 0);
        assert_eq!(
            delivery_observed.gossip_delivery.remaining_capacity_objects,
            super::MAX_GOSSIP_OUTBOX_RECORDS - 3
        );
        assert_eq!(delivery_observed.gossip_delivery.source_mapped_objects, 1);
        assert_eq!(
            delivery_observed.gossip_delivery.topic_counts,
            BTreeMap::from([
                ("payout-plan".to_owned(), 1),
                ("receipt-batch".to_owned(), 1),
                ("share".to_owned(), 1),
            ])
        );
        assert_eq!(delivery_observed.gossip_delivery.tracked_peers.len(), 3);
        let source_delivery = delivery_observed
            .gossip_delivery
            .tracked_peers
            .iter()
            .find(|peer| peer.transport_pubkey == hex::encode(source_peer))
            .unwrap();
        assert_eq!(source_delivery.settled_objects, 2);
        assert_eq!(source_delivery.pending_objects, 1);
        let zero_delivery = delivery_observed
            .gossip_delivery
            .tracked_peers
            .iter()
            .find(|peer| peer.transport_pubkey == hex::encode(zero_ack_peer))
            .unwrap();
        assert_eq!(zero_delivery.settled_objects, 0);
        assert_eq!(zero_delivery.pending_objects, 3);
        assert_eq!(
            delivery_observed
                .gossip_delivery
                .settled_for_every_tracked_peer,
            Some(0)
        );
        assert_eq!(
            delivery_observed
                .gossip_delivery
                .pending_for_any_tracked_peer,
            Some(3)
        );
        outbox.clear_publication(&store, &pending_intent).unwrap();

        let index_namespace = super::network_namespace(super::GOSSIP_OUTBOX_INDEX_NAMESPACE, 2);
        let index_key = super::gossip_outbox_index_key(GossipTopic::PayoutPlan, &plan.object_id());
        store.delete(&index_namespace, &index_key).unwrap();
        assert!(build_observability_snapshot(&store, 2, &rosters).is_err());
        immutable_put(
            &store,
            &index_namespace,
            &index_key,
            &third_sequence.to_le_bytes(),
        )
        .unwrap();

        let intent_namespace =
            super::network_namespace(super::GOSSIP_PUBLICATION_INTENT_NAMESPACE, 2);
        store
            .put(&intent_namespace, "malformed", b"malformed")
            .unwrap();
        assert!(build_observability_snapshot(&store, 2, &rosters).is_err());
        store.delete(&intent_namespace, "malformed").unwrap();
        store
            .put(super::GOSSIP_MIGRATION_NAMESPACE, "2", b"malformed")
            .unwrap();
        assert!(build_observability_snapshot(&store, 2, &rosters).is_err());
        store
            .put(
                super::GOSSIP_MIGRATION_NAMESPACE,
                "2",
                &super::encode_gossip_migration(
                    2,
                    super::GOSSIP_MIGRATION_OPERATOR | super::GOSSIP_MIGRATION_SHARE,
                ),
            )
            .unwrap();
        store
            .put(super::GOSSIP_COMPACTION_NAMESPACE, "2", b"malformed")
            .unwrap();
        assert!(build_observability_snapshot(&store, 2, &rosters).is_err());
        store
            .delete(super::GOSSIP_COMPACTION_NAMESPACE, "2")
            .unwrap();

        immutable_put(
            &store,
            REORG_ORPHAN_PARENT_NAMESPACE,
            &hex::encode(fixture.parent.object_id()),
            &0u64.to_le_bytes(),
        )
        .unwrap();
        let reorg_observed = build_observability_snapshot(&store, 2, &rosters).unwrap();
        assert_eq!(reorg_observed.shares.accepted_shares_on_orphaned_parents, 1);
        assert_eq!(reorg_observed.shares.credited_shares_on_orphaned_parents, 1);

        ProtocolJournal::new(&store)
            .persist(
                ProtocolRecordKind::BodyPackage,
                &[99; 32],
                &canonical_bytes(&fixture.body),
            )
            .unwrap();
        assert!(build_observability_snapshot(&store, 2, &rosters).is_err());
    }

    #[tokio::test]
    async fn supervised_hns_sync_stops_on_shutdown_partial_or_oracle_failure() {
        let calls = Arc::new(AtomicUsize::new(0));
        let (shutdown_tx, shutdown_rx) = watch::channel(false);
        let callback_calls = calls.clone();
        let callback_shutdown = shutdown_tx.clone();
        let callback = Arc::new(move || {
            callback_calls.fetch_add(1, Ordering::SeqCst);
            callback_shutdown.send(true).unwrap();
            Ok(synchronized_summary(0))
        });
        tokio::time::timeout(
            std::time::Duration::from_secs(1),
            run_hns_sync_loop(callback, std::time::Duration::from_millis(1), shutdown_rx),
        )
        .await
        .unwrap()
        .unwrap();
        assert_eq!(calls.load(Ordering::SeqCst), 1);

        let (_partial_tx, partial_rx) = watch::channel(false);
        let partial = Arc::new(|| {
            let mut summary = synchronized_summary(1);
            summary.complete = false;
            Ok(summary)
        });
        assert!(
            tokio::time::timeout(
                std::time::Duration::from_secs(1),
                run_hns_sync_loop(partial, std::time::Duration::from_millis(1), partial_rx,)
            )
            .await
            .unwrap()
            .is_err()
        );

        let (_failure_tx, failure_rx) = watch::channel(false);
        let failure = Arc::new(|| Err("synthetic hsd failure".to_owned()));
        assert!(
            tokio::time::timeout(
                std::time::Duration::from_secs(1),
                run_hns_sync_loop(failure, std::time::Duration::from_millis(1), failure_rx,)
            )
            .await
            .unwrap()
            .is_err()
        );
    }

    #[test]
    fn reusable_hns_reconciler_catches_up_bounds_work_and_replaces_a_reorged_tip() {
        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let fixture = ShareValidationBenchmark::new().artifacts();
        let oracle = Arc::new(MutableCanonicalOracle::default());
        let admission = payout_admission(&store, &fixture, oracle.clone(), [90; 32]);
        let source = MutablePaymentBlockSource::default();

        source.set_block(ordinary_hns_block(10, [10; 32], [9; 32]));
        source.set_block(ordinary_hns_block(11, [11; 32], [10; 32]));
        oracle.set(10, [10; 32], true);
        oracle.set(11, [11; 32], true);
        let initial = reconcile_hns_once(&store, 2, &admission, &source, Some(10), 3).unwrap();
        assert!(initial.complete);
        assert_eq!(initial.appended_events, 2);
        assert_eq!(initial.synchronized_tip, Some((11, [11; 32])));

        source.set_block(ordinary_hns_block(12, [12; 32], [11; 32]));
        oracle.set(12, [12; 32], true);
        let advanced = reconcile_hns_once(&store, 2, &admission, &source, Some(10), 3).unwrap();
        assert!(advanced.complete);
        assert_eq!(advanced.appended_events, 1);

        source.set_block(ordinary_hns_block(13, [13; 32], [12; 32]));
        source.set_block(ordinary_hns_block(14, [14; 32], [13; 32]));
        oracle.set(13, [13; 32], true);
        oracle.set(14, [14; 32], true);
        let partial = reconcile_hns_once(&store, 2, &admission, &source, Some(10), 1).unwrap();
        assert!(!partial.complete);
        assert_eq!(partial.appended_events, 1);
        assert_eq!(partial.synchronized_tip, Some((13, [13; 32])));
        let caught_up = reconcile_hns_once(&store, 2, &admission, &source, Some(10), 4).unwrap();
        assert!(caught_up.complete);
        assert_eq!(caught_up.synchronized_tip, Some((14, [14; 32])));

        oracle.set(14, [14; 32], false);
        oracle.set(14, [114; 32], true);
        source.set_block(ordinary_hns_block(14, [114; 32], [13; 32]));
        source.set_best_height(14);
        let reorged = reconcile_hns_once(&store, 2, &admission, &source, Some(10), 2).unwrap();
        assert!(reorged.complete);
        assert_eq!(reorged.appended_events, 2);
        assert_eq!(reorged.synchronized_tip, Some((14, [114; 32])));
        assert_eq!(reorged.total_events, 7);

        assert!(reconcile_hns_once(&store, 2, &admission, &source, Some(9), 2).is_err());
        assert!(
            reconcile_hns_once(&store, 2, &admission, &source, None, 2)
                .unwrap()
                .complete
        );
    }

