    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn durable_daemon_serves_after_restart_and_validates_operator_gossip() {
        let server_directory = secure_tempdir().unwrap();
        let client_directory = secure_tempdir().unwrap();
        for directory in [&server_directory, &client_directory] {
            overlay_init(vec![
                "--dir".to_owned(),
                directory.path().display().to_string(),
            ])
            .unwrap();
        }
        let object_id = [8; 32];
        let request = OverlayRequest {
            protocol_version: CORE_V2,
            network_id: 7,
            protocol: RequestProtocol::BodyShard,
            object_id,
            shard_index: Some(3),
        };
        {
            let store = RedbStore::create(server_directory.path().join(STATE_DATABASE)).unwrap();
            immutable_put(
                &store,
                RESPONSE_NAMESPACE,
                &response_key(&request),
                b"persistent-shard",
            )
            .unwrap();
        }

        let operator_key = SigningKey::from_bytes(&[19; 32]);
        let mut operator = OperatorRecordV2 {
            protocol_version: CORE_V2,
            network_id: 7,
            operator_pubkey: operator_key.verifying_key().to_bytes(),
            sequence: 4,
            supported_features: 0,
            payout_bucket_ids: vec![],
            contact_metadata_hash: None,
            signature_suite: ED25519_SUITE,
            signature: SignatureBytes::empty(),
        };
        operator.signature = sign_object(&operator_key, 7, &operator);
        let operator_id = operator.object_id();
        let mut encoded = Encoder::new();
        operator.encode(&mut encoded);
        let operator_bytes = encoded.into_bytes();

        for restart in 0..2 {
            let certificate =
                read_bounded(&server_directory.path().join(QUIC_CERTIFICATE), 64 * 1024).unwrap();
            let private_key =
                read_bounded(&server_directory.path().join(QUIC_PRIVATE_KEY), 64 * 1024).unwrap();
            let (limits, topic_limits) = default_overlay_limits();
            let server = QuicOverlayServer::bind(
                "127.0.0.1:0".parse().unwrap(),
                certificate.clone(),
                private_key,
                load_transport_identity(server_directory.path()).unwrap(),
                7,
                OverlayNode::new(7, limits, topic_limits),
                Arc::new(DurableOverlayApplication {
                    store: RedbStore::create(server_directory.path().join(STATE_DATABASE)).unwrap(),
                    network_id: 7,
                    parent_admission: None,
                    share_admission: None,
                    receipt_admission: None,
                    payout_admission: None,
                    gossip_forward_tx: None,
                    gossip_outbox: None,
                }),
                QuicTransportLimits::default(),
            )
            .unwrap();
            let address = server.local_addr().unwrap();
            let (shutdown_tx, shutdown_rx) = watch::channel(false);
            let task = tokio::spawn(server.run_until(shutdown_rx));
            let peer = QuicOverlayPeer::connect(
                default_client_bind(address),
                address,
                "localhost",
                certificate,
                load_transport_identity(client_directory.path()).unwrap(),
                7,
                QuicTransportLimits::default(),
            )
            .await
            .unwrap();
            assert_eq!(
                peer.request(RequestProtocol::BodyShard, object_id, Some(3))
                    .await
                    .unwrap(),
                Some(b"persistent-shard".to_vec())
            );
            if restart == 0 {
                peer.gossip(
                    GossipTopic::Operator,
                    operator_id,
                    false,
                    0,
                    operator_bytes.clone(),
                )
                .await
                .unwrap();
            }
            peer.close().await;
            shutdown_tx.send(true).unwrap();
            task.await.unwrap().unwrap();
        }

        let store = RedbStore::create(server_directory.path().join(STATE_DATABASE)).unwrap();
        assert_eq!(
            store
                .get(
                    OPERATOR_NAMESPACE,
                    &format!("7/{}", hex::encode(operator_id))
                )
                .unwrap(),
            Some(operator_bytes)
        );
        let recovered = recover_overlay_state(&store).unwrap();
        assert_eq!(recovered.operator_records, 1);
        assert_eq!(recovered.response_records, 1);
    }

