    struct ParentOracle(bool);

    impl meshmine_share::ParentChainOracle for ParentOracle {
        fn verify_header_and_chainwork(&self, _certificate: &SessionParentCertificateV2) -> bool {
            self.0
        }
    }

    struct PausedParentOracle {
        rendezvous: Arc<Barrier>,
    }

    impl meshmine_share::ParentChainOracle for PausedParentOracle {
        fn verify_header_and_chainwork(&self, _certificate: &SessionParentCertificateV2) -> bool {
            self.rendezvous.wait();
            self.rendezvous.wait();
            true
        }
    }

    fn parent_migration_fixture(network_id: u8) -> (ParentAdmission, SigningKey, SigningKey) {
        let first_key = SigningKey::from_bytes(&[201; 32]);
        let second_key = SigningKey::from_bytes(&[202; 32]);
        let admission = ParentAdmission {
            roster: meshmine_share::CommitteeRoster {
                protocol_version: CORE_V2,
                network_id,
                role: meshmine_share::CommitteeRole::Settlement,
                epoch: 0,
                threshold: 2,
                members: [
                    first_key.verifying_key().to_bytes(),
                    second_key.verifying_key().to_bytes(),
                ]
                .into_iter()
                .collect(),
            },
            oracle: Arc::new(ParentOracle(true)),
        };
        (admission, first_key, second_key)
    }

    fn signed_parent_for_migration(
        network_id: u8,
        first_key: &SigningKey,
        second_key: &SigningKey,
        sequence: u64,
        previous: Hash256,
        parent_hash: Hash256,
    ) -> SessionParentCertificateV2 {
        let mut certificate = SessionParentCertificateV2 {
            protocol_version: CORE_V2,
            network_id,
            parent_hash,
            parent_height: 10_000 + u32::try_from(sequence).unwrap(),
            parent_chainwork: U256([203; 32]),
            observed_ntime: 30_000 + sequence,
            certificate_sequence: sequence,
            previous_parent_certificate_id: previous,
            signer_set: SignatureSet::empty_ed25519(),
        };
        certificate.signer_set = assemble_ed25519_set(vec![
            sign_certificate(first_key, network_id, &certificate),
            sign_certificate(second_key, network_id, &certificate),
        ])
        .unwrap();
        certificate
    }

    fn persist_legacy_parent_chain(
        store: &dyn DurableStore,
        network_id: u8,
        parents: &[SessionParentCertificateV2],
    ) {
        let journal = ProtocolJournal::new(store);
        for parent in parents {
            let parent_id = parent.object_id();
            journal
                .persist(
                    ProtocolRecordKind::ParentCertificate,
                    &parent_id,
                    &canonical_bytes(parent),
                )
                .unwrap();
            store
                .put(
                    super::PARENT_ACCEPTED_NAMESPACE,
                    &super::parent_acceptance_key(network_id, parent_id),
                    &super::encode_parent_acceptance(
                        network_id,
                        parent.certificate_sequence,
                        parent_id,
                    ),
                )
                .unwrap();
        }
        let head = parents.last().unwrap();
        store
            .put(
                PARENT_HEAD_NAMESPACE,
                &network_id.to_string(),
                &super::encode_parent_head(head.certificate_sequence, head.object_id()),
            )
            .unwrap();
    }

    struct BarrierParentOracle(Arc<Barrier>);

    impl ParentChainOracle for BarrierParentOracle {
        fn verify_header_and_chainwork(&self, _certificate: &SessionParentCertificateV2) -> bool {
            self.0.wait();
            true
        }
    }

    struct CountingParentOracle {
        accepted: bool,
        calls: Arc<AtomicUsize>,
    }

    impl ParentChainOracle for CountingParentOracle {
        fn verify_header_and_chainwork(&self, _certificate: &SessionParentCertificateV2) -> bool {
            self.calls.fetch_add(1, Ordering::SeqCst);
            self.accepted
        }
    }

    #[test]
    fn share_admission_is_exact_durable_and_restart_recoverable() {
        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        persist_share_context(&store, &fixture);
        let admission = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        let share_bytes = canonical_bytes(&fixture.share);
        let share_id = fixture.share.object_id();
        let work_key = fixture.share.work_key();

        validate_and_store_share(&store, 2, &admission, share_id, &share_bytes).unwrap();
        // Repeating the exact object is idempotent.
        validate_and_store_share(&store, 2, &admission, share_id, &share_bytes).unwrap();
        assert_eq!(
            ProtocolJournal::new(&store)
                .load(ProtocolRecordKind::AcceptedWorkKey, &work_key)
                .unwrap(),
            Some(share_id.to_vec())
        );

        let rewrapped = benchmark.rewrapped_share();
        assert_ne!(rewrapped.object_id(), share_id);
        assert_eq!(rewrapped.work_key(), work_key);
        assert!(
            validate_and_store_share(
                &store,
                2,
                &admission,
                rewrapped.object_id(),
                &canonical_bytes(&rewrapped)
            )
            .is_err()
        );
        assert!(
            ProtocolJournal::new(&store)
                .load(ProtocolRecordKind::AcceptedShare, &rewrapped.object_id())
                .unwrap()
                .is_none()
        );

        drop(admission);
        let mut restarted = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        assert!(
            restarted
                .dags
                .lock()
                .unwrap()
                .get(&fixture.session.object_id())
                .unwrap()
                .known_ids()
                .contains(&share_id)
        );
        validate_and_store_share(&store, 2, &restarted, share_id, &share_bytes).unwrap();
        // Replay uses the durable first-observation time, not the current
        // wall clock after a potentially long outage.
        restarted.clock = Arc::new(FixedClock(u64::MAX));
        super::revalidate_recovered_shares(&store, 2, &restarted).unwrap();
    }

