    #[test]
    fn active_share_migration_rejects_source_less_closures_and_multiple_closes() {
        for legacy_phase in [1u8, 2] {
            let mut old_marker = Vec::new();
            old_marker.extend_from_slice(&super::ACTIVE_SHARE_MIGRATION_LEGACY_MAGIC);
            old_marker.extend_from_slice(&CORE_V2.to_le_bytes());
            old_marker.push(2);
            old_marker.push(legacy_phase);
            old_marker.push(1);
            old_marker.extend_from_slice(&[legacy_phase; 32]);
            assert_eq!(
                super::decode_active_share_migration(2, &old_marker).unwrap(),
                super::ActiveShareMigrationState {
                    phase: super::ActiveShareMigrationPhase::SessionCloses,
                    cursor: None,
                }
            );
        }

        let source_less = MemoryStore::default();
        let session_id = [211; 32];
        source_less
            .put(
                &super::session_closure_namespace(2),
                &hex::encode(session_id),
                &super::session_closure_value(2, session_id),
            )
            .unwrap();
        let error = super::ensure_active_share_index(&source_less, 2).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("lacks normal-close or reorg evidence")
        );
        assert_eq!(
            super::load_active_share_migration(&source_less, 2)
                .unwrap()
                .phase,
            super::ActiveShareMigrationPhase::Validate
        );

        let duplicate = MemoryStore::default();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        let (_, first) = certified_receipt_and_close(&benchmark, &fixture);
        let mut second = first.clone();
        second.close_reason = second.close_reason.wrapping_add(1);
        assert_ne!(first.object_id(), second.object_id());
        for legacy_phase in [1u8, 2] {
            let legacy = MemoryStore::default();
            let legacy_journal = ProtocolJournal::new(&legacy);
            legacy_journal
                .persist(
                    ProtocolRecordKind::MaskSession,
                    &fixture.session.object_id(),
                    &canonical_bytes(&fixture.session),
                )
                .unwrap();
            legacy_journal
                .persist(
                    ProtocolRecordKind::SessionClose,
                    &first.object_id(),
                    &canonical_bytes(&first),
                )
                .unwrap();
            let mut old_marker = Vec::new();
            old_marker.extend_from_slice(&super::ACTIVE_SHARE_MIGRATION_LEGACY_MAGIC);
            old_marker.extend_from_slice(&CORE_V2.to_le_bytes());
            old_marker.push(2);
            old_marker.push(legacy_phase);
            old_marker.push(1);
            old_marker.extend_from_slice(&[u8::MAX; 32]);
            legacy
                .put(super::ACTIVE_SHARE_MIGRATION_NAMESPACE, "2", &old_marker)
                .unwrap();
            super::ensure_active_share_index(&legacy, 2).unwrap();
            assert!(
                legacy
                    .get(
                        &super::session_normal_close_namespace(2),
                        &hex::encode(first.session_id),
                    )
                    .unwrap()
                    .is_some(),
                "legacy phase {legacy_phase} skipped close replay"
            );
        }
        let journal = ProtocolJournal::new(&duplicate);
        for close in [&first, &second] {
            journal
                .persist(
                    ProtocolRecordKind::SessionClose,
                    &close.object_id(),
                    &canonical_bytes(close),
                )
                .unwrap();
        }
        let error = super::ensure_active_share_index(&duplicate, 2).unwrap_err();
        assert!(error.to_string().contains("multiple closes"));
        assert!(
            duplicate
                .get(
                    &super::session_closure_namespace(2),
                    &hex::encode(first.session_id),
                )
                .unwrap()
                .is_none()
        );

        let legacy_ready = MemoryStore::default();
        let mut old_marker = Vec::new();
        old_marker.extend_from_slice(&super::ACTIVE_SHARE_MIGRATION_LEGACY_MAGIC);
        old_marker.extend_from_slice(&CORE_V2.to_le_bytes());
        old_marker.push(2);
        old_marker.push(3);
        old_marker.push(0);
        legacy_ready
            .put(super::ACTIVE_SHARE_MIGRATION_NAMESPACE, "2", &old_marker)
            .unwrap();
        super::ensure_active_share_index(&legacy_ready, 2).unwrap();
        let upgraded = legacy_ready
            .get(super::ACTIVE_SHARE_MIGRATION_NAMESPACE, "2")
            .unwrap()
            .unwrap();
        assert_eq!(&upgraded[..4], &super::ACTIVE_SHARE_MIGRATION_MAGIC);
        assert_eq!(
            super::load_active_share_migration(&legacy_ready, 2)
                .unwrap()
                .phase,
            super::ActiveShareMigrationPhase::Ready
        );
    }

    #[test]
    fn active_share_close_migration_preserves_exact_normal_and_reorg_only_provenance() {
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        let (_, close) = certified_receipt_and_close(&benchmark, &fixture);
        let session_id = fixture.session.object_id();
        let close_id = close.object_id();
        let key = hex::encode(session_id);

        let reorg_only = MemoryStore::default();
        persist_session_close_evidence(&reorg_only, &fixture.session, &close);
        reorg_only
            .put(REORG_CLOSED_SESSION_NAMESPACE, &key, &7u64.to_le_bytes())
            .unwrap();
        super::ensure_active_share_index(&reorg_only, 2).unwrap();
        assert!(
            reorg_only
                .get(&super::session_normal_close_namespace(2), &key)
                .unwrap()
                .is_none()
        );
        assert!(
            reorg_only
                .get(&super::session_normal_close_proof_namespace(2), &key)
                .unwrap()
                .is_none()
        );
        assert_eq!(
            reorg_only
                .get(&super::session_reorg_close_namespace(2), &key)
                .unwrap(),
            Some(super::session_reorg_close_value(2, session_id, close_id))
        );
        super::ensure_normal_closed_session_index(&reorg_only, 2).unwrap();
        assert!(
            reorg_only
                .scan_namespace(
                    &super::normal_closed_session_index_namespace(2),
                    ScanLimits {
                        maximum_records: 1,
                        maximum_value_bytes: 81,
                        maximum_total_bytes: 128,
                    },
                )
                .unwrap()
                .is_empty()
        );

        let normal_first = MemoryStore::default();
        let entry = persist_legacy_normal_closed_session(&normal_first, &fixture.session, &close);
        normal_first
            .put(REORG_CLOSED_SESSION_NAMESPACE, &key, &8u64.to_le_bytes())
            .unwrap();
        super::ensure_normal_closed_session_index(&normal_first, 2).unwrap();
        assert!(
            normal_first
                .get(&super::session_reorg_close_namespace(2), &key)
                .unwrap()
                .is_none()
        );
        assert_eq!(
            normal_first
                .get(
                    &super::normal_closed_session_index_namespace(2),
                    &super::normal_closed_session_index_key(entry.lane_id, entry.session_sequence,),
                )
                .unwrap(),
            Some(super::encode_normal_closed_session_index_value(2, &entry))
        );

        let ambiguous = MemoryStore::default();
        persist_session_close_evidence(&ambiguous, &fixture.session, &close);
        ambiguous
            .put(
                &super::session_normal_close_namespace(2),
                &key,
                &super::session_normal_close_value(2, session_id, close_id),
            )
            .unwrap();
        ambiguous
            .put(
                &super::session_closure_namespace(2),
                &key,
                &super::session_closure_value(2, session_id),
            )
            .unwrap();
        ambiguous
            .put(REORG_CLOSED_SESSION_NAMESPACE, &key, &9u64.to_le_bytes())
            .unwrap();
        let error = super::ensure_active_share_index(&ambiguous, 2).unwrap_err();
        assert!(error.to_string().contains("ambiguous provenance"));
        assert!(
            ambiguous
                .get(&super::session_normal_close_proof_namespace(2), &key)
                .unwrap()
                .is_none()
        );
    }

    #[test]
    fn active_share_close_migration_reclassifies_an_injected_reorg_race() {
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        let (_, close) = certified_receipt_and_close(&benchmark, &fixture);
        let session_id = fixture.session.object_id();
        let close_id = close.object_id();
        let key = hex::encode(session_id);
        let store = ReorgWinningCloseStore::during_migration(session_id);
        persist_session_close_evidence(&store, &fixture.session, &close);

        super::ensure_active_share_index(&store, 2).unwrap();

        assert!(store.migration_injected.load(Ordering::SeqCst));
        assert!(
            store
                .get(&super::session_normal_close_namespace(2), &key)
                .unwrap()
                .is_none()
        );
        assert!(
            store
                .get(&super::session_normal_close_proof_namespace(2), &key)
                .unwrap()
                .is_none()
        );
        assert_eq!(
            store
                .get(&super::session_reorg_close_namespace(2), &key)
                .unwrap(),
            Some(super::session_reorg_close_value(2, session_id, close_id))
        );
    }

    #[test]
    fn active_share_close_migration_rejects_cross_page_close_ambiguity() {
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        let (_, first) = certified_receipt_and_close(&benchmark, &fixture);
        let mut second = first.clone();
        second.close_reason = second.close_reason.wrapping_add(1);
        let (earlier, later) = if first.object_id() < second.object_id() {
            (first, second)
        } else {
            (second, first)
        };
        let store = MemoryStore::default();
        let journal = ProtocolJournal::new(&store);
        for close in [&earlier, &later] {
            journal
                .persist(
                    ProtocolRecordKind::SessionClose,
                    &close.object_id(),
                    &canonical_bytes(close),
                )
                .unwrap();
        }
        let session_id = earlier.session_id;
        let key = hex::encode(session_id);
        store
            .put(REORG_CLOSED_SESSION_NAMESPACE, &key, &3u64.to_le_bytes())
            .unwrap();
        store
            .put(
                &super::session_closure_namespace(2),
                &key,
                &super::session_closure_value(2, session_id),
            )
            .unwrap();
        store
            .put(
                &super::session_reorg_close_namespace(2),
                &key,
                &super::session_reorg_close_value(2, session_id, earlier.object_id()),
            )
            .unwrap();
        store
            .put(
                super::ACTIVE_SHARE_MIGRATION_NAMESPACE,
                "2",
                &super::encode_active_share_migration(
                    2,
                    &super::ActiveShareMigrationState {
                        phase: super::ActiveShareMigrationPhase::SessionCloses,
                        cursor: Some(earlier.object_id()),
                    },
                ),
            )
            .unwrap();

        let error = super::ensure_active_share_index(&store, 2).unwrap_err();
        assert!(error.to_string().contains("multiple closes"));
    }

    #[test]
    fn durable_disconnect_repairs_reorg_provenance_before_close_migration() {
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        let (_, close) = certified_receipt_and_close(&benchmark, &fixture);
        let store = MemoryStore::default();
        persist_share_context(&store, &fixture);
        persist_session_close_evidence(&store, &fixture.session, &close);
        let accepting_parent_admission = ParentAdmission {
            roster: fixture.settlement_roster.clone(),
            oracle: Arc::new(ParentOracle(true)),
        };
        initialize_parent_reorg_repair(&store, 2);
        validate_and_store_parent(
            &store,
            2,
            &accepting_parent_admission,
            fixture.parent.object_id(),
            &canonical_bytes(&fixture.parent),
        )
        .unwrap();
        assert!(store.get(PARENT_HEAD_NAMESPACE, "2").unwrap().is_some());
        let previous_block_hash = [193; 32];
        let events = [
            CanonicalPaymentEvent {
                sequence: 0,
                action: CanonicalPaymentAction::Connect,
                height: fixture.parent.parent_height,
                block_hash: fixture.parent.parent_hash,
                previous_block_hash,
                paid_plan: None,
            },
            CanonicalPaymentEvent {
                sequence: 1,
                action: CanonicalPaymentAction::Disconnect,
                height: fixture.parent.parent_height,
                block_hash: fixture.parent.parent_hash,
                previous_block_hash,
                paid_plan: None,
            },
        ];
        let journal = ProtocolJournal::new(&store);
        for event in &events {
            journal
                .persist(
                    ProtocolRecordKind::CanonicalPlanPayment,
                    &event.sequence.to_le_bytes(),
                    &encode_canonical_payment_event(2, event),
                )
                .unwrap();
        }
        store
            .delete(super::PARENT_REORG_REPAIR_NAMESPACE, "2")
            .unwrap();
        let session_id = fixture.session.object_id();
        let key = hex::encode(session_id);
        assert!(
            store
                .get(REORG_CLOSED_SESSION_NAMESPACE, &key)
                .unwrap()
                .is_none()
        );

        let parent_admission = ParentAdmission {
            roster: fixture.settlement_roster.clone(),
            // Marker repair must rewind the durable head before recovery ever
            // asks this rejecting oracle to validate the detached parent.
            oracle: Arc::new(ParentOracle(false)),
        };
        recover_parent_head(&store, 2, &parent_admission).unwrap();
        assert!(store.get(PARENT_HEAD_NAMESPACE, "2").unwrap().is_none());
        assert_eq!(
            store.get(REORG_CLOSED_SESSION_NAMESPACE, &key).unwrap(),
            Some(1u64.to_le_bytes().to_vec())
        );

        super::ensure_active_share_index(&store, 2).unwrap();

        assert_eq!(
            store.get(REORG_CLOSED_SESSION_NAMESPACE, &key).unwrap(),
            Some(1u64.to_le_bytes().to_vec())
        );
        assert!(
            store
                .get(&super::session_normal_close_namespace(2), &key)
                .unwrap()
                .is_none()
        );
        assert!(
            store
                .get(&super::session_normal_close_proof_namespace(2), &key)
                .unwrap()
                .is_none()
        );
        assert_eq!(
            store
                .get(&super::session_reorg_close_namespace(2), &key)
                .unwrap(),
            Some(super::session_reorg_close_value(
                2,
                session_id,
                close.object_id(),
            ))
        );
    }

    #[test]
    fn aggregate_disconnect_repair_scans_parent_and_session_evidence_once() {
        for disconnect_count in [1u64, 32] {
            let store = ReorgRepairProbeStore::counting();
            let journal = ProtocolJournal::new(&store);
            let previous_block_hash = [214; 32];
            for index in 0..disconnect_count {
                let mut block_hash = [0; 32];
                block_hash[24..].copy_from_slice(&index.to_be_bytes());
                let connect = CanonicalPaymentEvent {
                    sequence: index * 2,
                    action: CanonicalPaymentAction::Connect,
                    height: 500,
                    block_hash,
                    previous_block_hash,
                    paid_plan: None,
                };
                let disconnect = CanonicalPaymentEvent {
                    sequence: index * 2 + 1,
                    action: CanonicalPaymentAction::Disconnect,
                    ..connect.clone()
                };
                for event in [connect, disconnect] {
                    journal
                        .persist(
                            ProtocolRecordKind::CanonicalPlanPayment,
                            &event.sequence.to_le_bytes(),
                            &encode_canonical_payment_event(2, &event),
                        )
                        .unwrap();
                }
            }

            super::repair_reorg_markers_from_durable_disconnects(&store, 2).unwrap();

            assert_eq!(store.canonical_scans.load(Ordering::SeqCst), 1);
            assert_eq!(store.parent_scans.load(Ordering::SeqCst), 1);
            assert_eq!(store.session_scans.load(Ordering::SeqCst), 1);
            assert_eq!(
                store
                    .scan_namespace(
                        super::REORG_DISCONNECTED_BLOCK_NAMESPACE,
                        ScanLimits {
                            maximum_records: usize::try_from(disconnect_count).unwrap(),
                            maximum_value_bytes: 51,
                            maximum_total_bytes: 16 * 1024,
                        },
                    )
                    .unwrap()
                    .len(),
                usize::try_from(disconnect_count).unwrap()
            );
        }
    }

    #[test]
    fn pending_cleanup_restart_only_prunes_hot_rows_and_cas_advances_ready() {
        let store = ReorgRepairProbeStore::counting();
        initialize_parent_reorg_repair(&store, 2);
        let session_id = [231; 32];
        let share_id = [232; 32];
        let active_key = super::active_share_key(session_id, share_id);
        store
            .put(
                &super::session_closure_namespace(2),
                &hex::encode(session_id),
                &super::session_closure_value(2, session_id),
            )
            .unwrap();
        store
            .put(
                &super::active_share_namespace(2),
                &active_key,
                &super::encode_active_share_value(2, session_id, share_id, [233; 32]),
            )
            .unwrap();
        let pending = super::ParentReorgRepairState::PendingCleanup {
            event_count: 17,
            event_commitment: [234; 32],
        };
        store
            .put(
                super::PARENT_REORG_REPAIR_NAMESPACE,
                "2",
                &super::encode_parent_reorg_repair(2, pending),
            )
            .unwrap();
        store.canonical_scans.store(0, Ordering::SeqCst);
        store.parent_scans.store(0, Ordering::SeqCst);
        store.session_scans.store(0, Ordering::SeqCst);

        let ready = super::ensure_parent_reorg_repair_ready(&store, 2).unwrap();
        let expected = super::ParentReorgRepairState::Ready {
            event_count: 17,
            event_commitment: [234; 32],
        };
        assert_eq!(ready, expected);
        assert_eq!(
            store
                .get(super::PARENT_REORG_REPAIR_NAMESPACE, "2")
                .unwrap(),
            Some(super::encode_parent_reorg_repair(2, expected))
        );
        assert!(
            store
                .get(&super::active_share_namespace(2), &active_key)
                .unwrap()
                .is_none()
        );
        assert_eq!(store.canonical_scans.load(Ordering::SeqCst), 0);
        assert_eq!(store.parent_scans.load(Ordering::SeqCst), 0);
        assert_eq!(store.session_scans.load(Ordering::SeqCst), 0);
    }

    #[test]
    fn ready_parent_restart_is_head_only_without_inventory_or_ancestor_walks() {
        let (base_admission, first_key, second_key) = parent_migration_fixture(7);
        let oracle_calls = Arc::new(AtomicUsize::new(0));
        let admission = ParentAdmission {
            roster: base_admission.roster,
            oracle: Arc::new(CountingParentOracle {
                accepted: true,
                calls: oracle_calls.clone(),
            }),
        };
        let first = signed_parent_for_migration(7, &first_key, &second_key, 0, [0; 32], [235; 32]);
        let second = signed_parent_for_migration(
            7,
            &first_key,
            &second_key,
            1,
            first.object_id(),
            [236; 32],
        );
        let third = signed_parent_for_migration(
            7,
            &first_key,
            &second_key,
            2,
            second.object_id(),
            [237; 32],
        );
        let store = ReorgRepairProbeStore::counting();
        initialize_parent_reorg_repair(&store, 7);
        for parent in [&first, &second, &third] {
            validate_and_store_parent(
                &store,
                7,
                &admission,
                parent.object_id(),
                &canonical_bytes(parent),
            )
            .unwrap();
        }
        store.canonical_scans.store(0, Ordering::SeqCst);
        store.parent_scans.store(0, Ordering::SeqCst);
        store.session_scans.store(0, Ordering::SeqCst);
        store.parent_gets.store(0, Ordering::SeqCst);
        store.paged_scans.store(0, Ordering::SeqCst);
        oracle_calls.store(0, Ordering::SeqCst);

        recover_parent_head(&store, 7, &admission).unwrap();

        assert_eq!(store.canonical_scans.load(Ordering::SeqCst), 0);
        assert_eq!(store.parent_scans.load(Ordering::SeqCst), 0);
        assert_eq!(store.session_scans.load(Ordering::SeqCst), 0);
        assert_eq!(store.parent_gets.load(Ordering::SeqCst), 1);
        assert_eq!(store.paged_scans.load(Ordering::SeqCst), 0);
        assert_eq!(oracle_calls.load(Ordering::SeqCst), 1);
    }

    #[test]
    fn parent_admission_rejects_absent_and_pending_reorg_fences() {
        let (admission, first_key, second_key) = parent_migration_fixture(7);
        let parent = signed_parent_for_migration(7, &first_key, &second_key, 0, [0; 32], [238; 32]);
        let parent_id = parent.object_id();
        let payload = canonical_bytes(&parent);
        let store = MemoryStore::default();

        for fence in [
            None,
            Some(super::ParentReorgRepairState::PendingCleanup {
                event_count: 1,
                event_commitment: [239; 32],
            }),
        ] {
            if let Some(fence) = fence {
                store
                    .put(
                        super::PARENT_REORG_REPAIR_NAMESPACE,
                        "7",
                        &super::encode_parent_reorg_repair(7, fence),
                    )
                    .unwrap();
            }
            let error = validate_and_store_parent(&store, 7, &admission, parent_id, &payload)
                .unwrap_err()
                .to_string();
            assert!(error.contains("ready reorg repair fence"));
            assert!(store.get(PARENT_HEAD_NAMESPACE, "7").unwrap().is_none());
            assert!(
                ProtocolJournal::new(&store)
                    .load(ProtocolRecordKind::ParentCertificate, &parent_id)
                    .unwrap()
                    .is_none()
            );
        }
    }

