    #[test]
    fn disconnect_event_and_normal_close_have_one_atomic_order() {
        for winner in [EventCloseRaceWinner::Event, EventCloseRaceWinner::Close] {
            let benchmark = ShareValidationBenchmark::new();
            let fixture = benchmark.artifacts();
            let store = Arc::new(EventCloseRaceStore::new(winner));
            persist_share_context(store.as_ref(), &fixture);
            let shares = share_admission(store.as_ref(), &fixture, Arc::new(ParentOracle(true)));
            validate_and_store_share(
                store.as_ref(),
                2,
                &shares,
                fixture.share.object_id(),
                &canonical_bytes(&fixture.share),
            )
            .unwrap();
            let mut receipts = receipt_admission(store.as_ref(), &fixture);
            receipts.share_dags = shares.dags.clone();
            let (batch, close) = certified_receipt_and_close(&benchmark, &fixture);
            validate_and_store_receipt_batch(
                store.as_ref(),
                2,
                &receipts,
                batch.object_id(),
                &canonical_bytes(&batch),
            )
            .unwrap();
            let payout = Arc::new(payout_admission(
                store.as_ref(),
                &fixture,
                Arc::new(MutableCanonicalOracle::default()),
                [217; 32],
            ));
            let previous_block_hash = [218; 32];
            append_canonical_payment_event(
                store.as_ref(),
                2,
                payout.as_ref(),
                CanonicalPaymentEvent {
                    sequence: 0,
                    action: CanonicalPaymentAction::Connect,
                    height: fixture.parent.parent_height,
                    block_hash: fixture.parent.parent_hash,
                    previous_block_hash,
                    paid_plan: None,
                },
            )
            .unwrap();
            let receipts = Arc::new(receipts);
            let close_id = close.object_id();
            let close_payload = canonical_bytes(&close);
            let close_store = store.clone();
            let close_admission = receipts.clone();
            let close_thread = std::thread::spawn(move || {
                validate_and_store_session_close(
                    close_store.as_ref(),
                    2,
                    close_admission.as_ref(),
                    close_id,
                    &close_payload,
                )
                .map_err(|error| error.to_string())
            });
            let event_store = store.clone();
            let event_admission = payout.clone();
            let event = CanonicalPaymentEvent {
                sequence: 1,
                action: CanonicalPaymentAction::Disconnect,
                height: fixture.parent.parent_height,
                block_hash: fixture.parent.parent_hash,
                previous_block_hash,
                paid_plan: None,
            };
            let event_thread = std::thread::spawn(move || {
                append_canonical_payment_event(
                    event_store.as_ref(),
                    2,
                    event_admission.as_ref(),
                    event,
                )
                .map_err(|error| error.to_string())
            });
            let close_result = close_thread.join().unwrap();
            let event_result = event_thread.join().unwrap();
            assert!(event_result.is_ok());

            let session_id = fixture.session.object_id();
            let session_key = hex::encode(session_id);
            let entry =
                super::normal_closed_session_index_entry(2, &fixture.session, &close).unwrap();
            let index_key =
                super::normal_closed_session_index_key(entry.lane_id, entry.session_sequence);
            match winner {
                EventCloseRaceWinner::Event => {
                    assert!(close_result.is_err());
                    assert!(
                        store
                            .get(&super::session_normal_close_namespace(2), &session_key)
                            .unwrap()
                            .is_none()
                    );
                    assert!(
                        store
                            .get(
                                &super::session_normal_close_proof_namespace(2),
                                &session_key,
                            )
                            .unwrap()
                            .is_none()
                    );
                    assert!(
                        store
                            .get(&super::normal_closed_session_index_namespace(2), &index_key)
                            .unwrap()
                            .is_none()
                    );
                }
                EventCloseRaceWinner::Close => {
                    assert!(close_result.is_ok());
                    assert!(
                        store
                            .get(&super::session_normal_close_namespace(2), &session_key)
                            .unwrap()
                            .is_some()
                    );
                    assert!(
                        store
                            .get(
                                &super::session_normal_close_proof_namespace(2),
                                &session_key,
                            )
                            .unwrap()
                            .is_some()
                    );
                    assert!(
                        store
                            .get(&super::normal_closed_session_index_namespace(2), &index_key)
                            .unwrap()
                            .is_some()
                    );
                }
            }
            assert_eq!(
                super::load_reorg_marker(
                    store.as_ref(),
                    REORG_CLOSED_SESSION_NAMESPACE,
                    &session_id,
                )
                .unwrap(),
                Some(1)
            );
            assert_eq!(
                super::load_disconnected_block_tombstone(
                    store.as_ref(),
                    2,
                    fixture.parent.parent_height,
                    fixture.parent.parent_hash,
                )
                .unwrap(),
                Some(1)
            );
        }
    }

    #[test]
    fn disconnect_event_and_mask_session_import_have_one_atomic_order() {
        for winner in [
            EventSessionRaceWinner::Event,
            EventSessionRaceWinner::Session,
        ] {
            let benchmark = ShareValidationBenchmark::new();
            let fixture = benchmark.artifacts();
            let store = Arc::new(EventSessionRaceStore::new(winner));
            let parent_id = fixture.parent.object_id();
            ProtocolJournal::new(store.as_ref())
                .persist(
                    ProtocolRecordKind::ParentCertificate,
                    &parent_id,
                    &canonical_bytes(&fixture.parent),
                )
                .unwrap();
            let payout = Arc::new(PayoutAdmission {
                settlement_roster: fixture.settlement_roster.clone(),
                receipt_roster: fixture.receipt_roster.clone(),
                policy: payout_policy(&fixture, [221; 32]),
                hns_oracle: Arc::new(MutableCanonicalOracle::default()),
                share_dags: None,
                state: Mutex::new(super::PayoutAdmissionState::default()),
            });
            let previous_block_hash = [222; 32];
            append_canonical_payment_event(
                store.as_ref(),
                2,
                payout.as_ref(),
                CanonicalPaymentEvent {
                    sequence: 0,
                    action: CanonicalPaymentAction::Connect,
                    height: fixture.parent.parent_height,
                    block_hash: fixture.parent.parent_hash,
                    previous_block_hash,
                    paid_plan: None,
                },
            )
            .unwrap();

            let session = fixture.session.clone();
            let session_id = session.object_id();
            let session_payload = canonical_bytes(&session);
            let session_store = store.clone();
            let session_thread = std::thread::spawn(move || {
                persist_mask_session_with_reorg_guards(
                    session_store.as_ref(),
                    2,
                    &session,
                    &session_payload,
                )
                .map_err(|error| error.to_string())
            });
            let event_store = store.clone();
            let event_admission = payout.clone();
            let event = CanonicalPaymentEvent {
                sequence: 1,
                action: CanonicalPaymentAction::Disconnect,
                height: fixture.parent.parent_height,
                block_hash: fixture.parent.parent_hash,
                previous_block_hash,
                paid_plan: None,
            };
            let event_thread = std::thread::spawn(move || {
                append_canonical_payment_event(
                    event_store.as_ref(),
                    2,
                    event_admission.as_ref(),
                    event,
                )
                .map_err(|error| error.to_string())
            });
            let session_result = session_thread.join().unwrap();
            let event_result = event_thread.join().unwrap();
            assert!(event_result.is_ok());
            assert_eq!(
                super::load_disconnected_block_tombstone(
                    store.as_ref(),
                    2,
                    fixture.parent.parent_height,
                    fixture.parent.parent_hash,
                )
                .unwrap(),
                Some(1)
            );

            let session_evidence = ProtocolJournal::new(store.as_ref())
                .load(ProtocolRecordKind::MaskSession, &session_id)
                .unwrap();
            match winner {
                EventSessionRaceWinner::Event => {
                    assert!(session_result.is_err());
                    assert!(session_evidence.is_none());
                    assert!(
                        super::load_reorg_marker(
                            store.as_ref(),
                            REORG_CLOSED_SESSION_NAMESPACE,
                            &session_id,
                        )
                        .unwrap()
                        .is_none()
                    );
                    assert!(
                        store
                            .get(MASK_SESSION_INVENTORY_GENERATION_NAMESPACE, "2")
                            .unwrap()
                            .is_none()
                    );
                }
                EventSessionRaceWinner::Session => {
                    assert!(session_result.is_ok());
                    assert_eq!(session_evidence, Some(canonical_bytes(&fixture.session)));
                    assert_eq!(
                        super::load_reorg_marker(
                            store.as_ref(),
                            REORG_CLOSED_SESSION_NAMESPACE,
                            &session_id,
                        )
                        .unwrap(),
                        Some(1)
                    );
                    assert!(super::has_session_closure(store.as_ref(), 2, session_id).unwrap());
                    assert_eq!(
                        store
                            .get(MASK_SESSION_INVENTORY_GENERATION_NAMESPACE, "2")
                            .unwrap(),
                        Some(1u64.to_le_bytes().to_vec())
                    );
                }
            }
        }
    }

