    #[test]
    fn certified_receipt_and_close_are_durable_and_restart_verified() {
        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        persist_share_context(&store, &fixture);
        let share_admission = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        validate_and_store_share(
            &store,
            2,
            &share_admission,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        let mut admission = receipt_admission(&store, &fixture);
        admission.share_dags = share_admission.dags.clone();
        let (batch, close) = certified_receipt_and_close(&benchmark, &fixture);
        let batch_bytes = canonical_bytes(&batch);
        let close_bytes = canonical_bytes(&close);
        validate_and_store_receipt_batch(&store, 2, &admission, batch.object_id(), &batch_bytes)
            .unwrap();
        assert!(
            store
                .get(
                    &super::active_receipt_head_namespace(2),
                    &super::active_receipt_head_key(fixture.session.object_id()),
                )
                .unwrap()
                .is_some()
        );
        validate_and_store_session_close(&store, 2, &admission, close.object_id(), &close_bytes)
            .unwrap();
        assert!(
            admission
                .sessions
                .lock()
                .unwrap()
                .get(&fixture.session.object_id())
                .is_none()
        );
        assert!(
            !share_admission
                .dags
                .lock()
                .unwrap()
                .contains_key(&fixture.session.object_id())
        );
        assert!(
            store
                .get(
                    &super::active_share_namespace(2),
                    &super::active_share_key(
                        fixture.session.object_id(),
                        fixture.share.object_id(),
                    ),
                )
                .unwrap()
                .is_none()
        );
        assert!(
            store
                .get(
                    &super::active_receipt_head_namespace(2),
                    &super::active_receipt_head_key(fixture.session.object_id()),
                )
                .unwrap()
                .is_none()
        );
        let late_share = independent_fixture_share(&fixture);
        assert!(
            validate_and_store_share(
                &store,
                2,
                &share_admission,
                late_share.object_id(),
                &canonical_bytes(&late_share),
            )
            .is_err()
        );
        validate_and_store_share(
            &store,
            2,
            &share_admission,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        // Both exact messages remain idempotent after closure.
        validate_and_store_receipt_batch(&store, 2, &admission, batch.object_id(), &batch_bytes)
            .unwrap();
        validate_and_store_session_close(&store, 2, &admission, close.object_id(), &close_bytes)
            .unwrap();

        drop(admission);
        assert!(
            recover_active_receipt_sessions(&store, 2, &fixture.receipt_roster)
                .unwrap()
                .is_empty()
        );
        let recovered = recover_receipt_sessions(
            &store,
            2,
            &fixture.receipt_roster,
            &fixture.settlement_roster,
        )
        .unwrap();
        let state = recovered.get(&fixture.session.object_id()).unwrap();
        assert_eq!(state.batches, vec![batch]);
        assert_eq!(state.close, Some(close));
    }

    #[test]
    fn normal_closed_session_index_survives_reopen_exact_retry_and_later_reorg() {
        let directory = secure_tempdir().unwrap();
        let database_path = directory.path().join(STATE_DATABASE);
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        let (batch, close) = certified_receipt_and_close(&benchmark, &fixture);
        let entry = super::normal_closed_session_index_entry(2, &fixture.session, &close).unwrap();
        let index_key =
            super::normal_closed_session_index_key(entry.lane_id, entry.session_sequence);
        let index_value = super::encode_normal_closed_session_index_value(2, &entry);

        {
            let store = RedbStore::create(&database_path).unwrap();
            persist_share_context(&store, &fixture);
            let shares = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
            validate_and_store_share(
                &store,
                2,
                &shares,
                fixture.share.object_id(),
                &canonical_bytes(&fixture.share),
            )
            .unwrap();
            let mut receipts = receipt_admission(&store, &fixture);
            receipts.share_dags = shares.dags.clone();
            validate_and_store_receipt_batch(
                &store,
                2,
                &receipts,
                batch.object_id(),
                &canonical_bytes(&batch),
            )
            .unwrap();
            validate_and_store_session_close(
                &store,
                2,
                &receipts,
                close.object_id(),
                &canonical_bytes(&close),
            )
            .unwrap();
            assert_eq!(
                store
                    .get(&super::normal_closed_session_index_namespace(2), &index_key,)
                    .unwrap(),
                Some(index_value.clone())
            );
        }

        let store = RedbStore::create(&database_path).unwrap();
        super::ensure_normal_closed_session_index(&store, 2).unwrap();
        let durable = store
            .get(&super::normal_closed_session_index_namespace(2), &index_key)
            .unwrap()
            .unwrap();
        assert_eq!(durable, index_value);
        assert_eq!(
            super::validate_normal_closed_session_index_row(&store, 2, &index_key, &durable)
                .unwrap(),
            entry
        );
        let receipts = receipt_admission(&store, &fixture);
        validate_and_store_session_close(
            &store,
            2,
            &receipts,
            close.object_id(),
            &canonical_bytes(&close),
        )
        .unwrap();

        // MM-0001 retains credit for a certified normal close even when its
        // parent is orphaned later. A reorg-only closure never receives this
        // row, but later reorg provenance does not erase a normal-close row.
        store
            .put(
                REORG_CLOSED_SESSION_NAMESPACE,
                &hex::encode(entry.session_id),
                &77u64.to_le_bytes(),
            )
            .unwrap();
        super::ensure_normal_closed_session_index(&store, 2).unwrap();
        let retained = store
            .get(&super::normal_closed_session_index_namespace(2), &index_key)
            .unwrap()
            .unwrap();
        assert_eq!(retained, index_value);
        assert_eq!(
            super::validate_normal_closed_session_index_row(&store, 2, &index_key, &retained)
                .unwrap(),
            entry
        );
        let snapshots = super::derive_expected_payout_snapshots(
            &store,
            2,
            &fixture.receipt_roster,
            &fixture.settlement_roster,
            payout_policy(&fixture, [0; 32]),
        )
        .unwrap();
        assert_eq!(snapshots.len(), 1);
        assert_eq!(snapshots[0].first_session_close_id, close.object_id());
        assert_eq!(snapshots[0].last_session_close_id, close.object_id());
        assert_eq!(
            snapshots[0].actual_work_in_window,
            work_for_target(&fixture.share.declared_target)
        );
    }

    #[test]
    fn normal_close_rejects_an_ordered_lane_sequence_conflict_without_partial_writes() {
        let store = MemoryStore::default();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        persist_share_context(&store, &fixture);
        let shares = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        validate_and_store_share(
            &store,
            2,
            &shares,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        let mut receipts = receipt_admission(&store, &fixture);
        receipts.share_dags = shares.dags.clone();
        let (batch, close) = certified_receipt_and_close(&benchmark, &fixture);
        validate_and_store_receipt_batch(
            &store,
            2,
            &receipts,
            batch.object_id(),
            &canonical_bytes(&batch),
        )
        .unwrap();

        let conflict = super::NormalClosedSessionIndexEntry {
            lane_id: fixture.session.lane_id,
            session_sequence: fixture.session.session_sequence,
            session_id: [91; 32],
            close_id: [92; 32],
        };
        let key = super::normal_closed_session_index_key(
            fixture.session.lane_id,
            fixture.session.session_sequence,
        );
        let conflict_value = super::encode_normal_closed_session_index_value(2, &conflict);
        store
            .put(
                &super::normal_closed_session_index_namespace(2),
                &key,
                &conflict_value,
            )
            .unwrap();

        let error = validate_and_store_session_close(
            &store,
            2,
            &receipts,
            close.object_id(),
            &canonical_bytes(&close),
        )
        .unwrap_err();
        assert!(error.to_string().contains("lane/sequence"));
        assert_eq!(
            store
                .get(&super::normal_closed_session_index_namespace(2), &key)
                .unwrap(),
            Some(conflict_value)
        );
        assert!(
            ProtocolJournal::new(&store)
                .load(ProtocolRecordKind::SessionClose, &close.object_id())
                .unwrap()
                .is_none()
        );
        assert!(
            store
                .get(
                    &super::session_normal_close_namespace(2),
                    &hex::encode(fixture.session.object_id()),
                )
                .unwrap()
                .is_none()
        );
        assert!(
            store
                .get(
                    &super::session_closure_namespace(2),
                    &hex::encode(fixture.session.object_id()),
                )
                .unwrap()
                .is_none()
        );
    }

