    #[test]
    fn active_receipt_head_recovers_only_the_open_chain_after_restart() {
        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        persist_share_context(&store, &fixture);
        let shares = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        validate_and_store_share(
            &store,
            2,
            &shares,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        let admission = receipt_admission(&store, &fixture);
        let (batch, _) = certified_receipt_and_close(&benchmark, &fixture);
        let payload = canonical_bytes(&batch);
        validate_and_store_receipt_batch(&store, 2, &admission, batch.object_id(), &payload)
            .unwrap();
        drop(admission);

        let recovered = recover_active_receipt_sessions(&store, 2, &fixture.receipt_roster)
            .unwrap()
            .remove(&fixture.session.object_id())
            .unwrap();
        assert_eq!(recovered.batches, vec![batch.clone()]);
        assert_eq!(recovered.total_batch_bytes, payload.len() as u64);
        let restarted = receipt_admission(&store, &fixture);
        validate_and_store_receipt_batch(&store, 2, &restarted, batch.object_id(), &payload)
            .unwrap();
        assert_eq!(
            restarted
                .sessions
                .lock()
                .unwrap()
                .get(&fixture.session.object_id())
                .unwrap()
                .batches,
            vec![batch]
        );
    }

