    #[test]
    fn active_receipt_migration_resumes_from_its_durable_validation_cursor() {
        let store = MemoryStore::default();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        let legacy = persist_legacy_empty_receipt_sessions(&store, &benchmark, &fixture, 9);

        let error =
            super::ensure_active_receipt_index(&store, 2, &fixture.receipt_roster).unwrap_err();
        assert!(
            error.to_string().contains("made bounded progress"),
            "unexpected migration failure: {error}"
        );
        let interrupted = super::load_active_receipt_migration_entry(&store, 2).unwrap();
        assert_eq!(
            interrupted.state.phase,
            super::ActiveReceiptMigrationPhase::Validate
        );
        assert!(interrupted.state.cursor.is_some());
        assert!(interrupted.encoded_state.is_some());
        assert!(interrupted.legacy_retired);
        assert_eq!(
            store
                .scan_namespace(
                    &super::active_receipt_head_namespace(2),
                    meshmine_storage::ScanLimits {
                        maximum_records: 9,
                        maximum_value_bytes: 103,
                        maximum_total_bytes: 1024 * 1024,
                    },
                )
                .unwrap()
                .len(),
            9
        );

        super::ensure_active_receipt_index(&store, 2, &fixture.receipt_roster).unwrap();
        let ready = super::load_active_receipt_migration_entry(&store, 2).unwrap();
        assert_eq!(ready.state.phase, super::ActiveReceiptMigrationPhase::Ready);
        assert!(ready.state.cursor.is_none());
        assert!(ready.legacy_retired);
        let recovered =
            recover_active_receipt_sessions(&store, 2, &fixture.receipt_roster).unwrap();
        assert_eq!(recovered.len(), legacy.len());
        for (session_id, batch) in legacy {
            assert_eq!(recovered.get(&session_id).unwrap().batches, vec![batch]);
        }
    }

    #[test]
    fn active_receipt_validation_failures_and_bounds_never_mark_ready() {
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        for (head, expected_error) in [
            (
                super::ActiveReceiptHead {
                    session_id: [91; 32],
                    head_id: [92; 32],
                    head_sequence: 0,
                    batch_count: 1,
                    total_entry_count: 1,
                    total_batch_bytes: 1,
                },
                "lacks immutable batch evidence",
            ),
            (
                super::ActiveReceiptHead {
                    session_id: [93; 32],
                    head_id: [94; 32],
                    head_sequence: super::MAX_ACTIVE_RECEIPT_BATCHES_PER_SESSION as u64,
                    batch_count: super::MAX_ACTIVE_RECEIPT_BATCHES_PER_SESSION as u64 + 1,
                    total_entry_count: super::MAX_ACTIVE_RECEIPT_BATCHES_PER_SESSION as u64 + 1,
                    total_batch_bytes: 1,
                },
                "exceeds its per-session bounds",
            ),
        ] {
            let store = MemoryStore::default();
            super::ensure_active_share_index(&store, 2).unwrap();
            store
                .put(
                    &super::active_receipt_head_namespace(2),
                    &super::active_receipt_head_key(head.session_id),
                    &super::encode_active_receipt_head(2, &head),
                )
                .unwrap();
            let validating = super::ActiveReceiptMigrationState {
                phase: super::ActiveReceiptMigrationPhase::Validate,
                cursor: None,
            };
            store
                .put(
                    super::ACTIVE_RECEIPT_MIGRATION_NAMESPACE,
                    "2",
                    &super::encode_active_receipt_migration(2, &validating),
                )
                .unwrap();
            store
                .put(
                    super::LEGACY_ACTIVE_RECEIPT_MIGRATION_NAMESPACE,
                    "2",
                    &super::encode_legacy_active_receipt_retirement(2),
                )
                .unwrap();

            let error =
                super::ensure_active_receipt_index(&store, 2, &fixture.receipt_roster).unwrap_err();
            assert!(
                error.to_string().contains(expected_error),
                "unexpected migration failure: {error}"
            );
            let retained = super::load_active_receipt_migration_entry(&store, 2).unwrap();
            assert_eq!(retained.state, validating);
            assert!(retained.legacy_retired);
        }
    }

    #[test]
    fn active_receipt_v3_retires_v2_and_requires_every_exact_ready_guard() {
        let store = MemoryStore::default();
        let fixture = ShareValidationBenchmark::new().artifacts();
        super::ensure_active_share_index(&store, 2).unwrap();

        let missing = super::active_receipt_ready_guards(&store, 2).unwrap_err();
        assert!(missing.to_string().contains("not ready"));

        let mut legacy = super::encode_active_receipt_migration(
            2,
            &super::ActiveReceiptMigrationState {
                phase: super::ActiveReceiptMigrationPhase::Ready,
                cursor: None,
            },
        );
        legacy[..4].copy_from_slice(&super::LEGACY_ACTIVE_RECEIPT_MIGRATION_MAGIC);
        store
            .put(
                super::LEGACY_ACTIVE_RECEIPT_MIGRATION_NAMESPACE,
                "2",
                &legacy,
            )
            .unwrap();
        let legacy_entry = super::load_active_receipt_migration_entry(&store, 2).unwrap();
        assert_eq!(
            legacy_entry.state.phase,
            super::ActiveReceiptMigrationPhase::ReceiptBatches
        );
        assert!(!legacy_entry.legacy_retired);

        let dags = HashMap::new();
        let first =
            super::advance_active_receipt_migration_unit(&store, 2, &fixture.receipt_roster, &dags)
                .unwrap();
        assert!(first.committed);
        assert_eq!(
            first.state.phase,
            super::ActiveReceiptMigrationPhase::Validate
        );
        assert_eq!(
            store
                .get(super::LEGACY_ACTIVE_RECEIPT_MIGRATION_NAMESPACE, "2")
                .unwrap(),
            Some(super::encode_legacy_active_receipt_retirement(2))
        );
        let second =
            super::advance_active_receipt_migration_unit(&store, 2, &fixture.receipt_roster, &dags)
                .unwrap();
        assert!(second.committed);
        assert_eq!(
            second.state.phase,
            super::ActiveReceiptMigrationPhase::Ready
        );
        super::active_receipt_ready_guards(&store, 2).unwrap();

        store
            .put(
                super::LEGACY_ACTIVE_RECEIPT_MIGRATION_NAMESPACE,
                "2",
                b"not-a-retirement",
            )
            .unwrap();
        assert!(super::active_receipt_ready_guards(&store, 2).is_err());
    }

