    #[test]
    fn receipt_role_proposal_signing_guard_and_publication_are_restart_safe() {
        let directory = secure_tempdir().unwrap();
        let database = directory.path().join(STATE_DATABASE);
        let store = RedbStore::create(&database).unwrap();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        persist_share_context(&store, &fixture);
        let shares = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        validate_and_store_share(
            &store,
            2,
            &shares,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        let second_share = independent_fixture_share(&fixture);
        validate_and_store_share(
            &store,
            2,
            &shares,
            second_share.object_id(),
            &canonical_bytes(&second_share),
        )
        .unwrap();
        let receipts = receipt_admission(&store, &fixture);
        let proposal = super::build_receipt_proposal(
            &store,
            2,
            &shares,
            &receipts,
            fixture.session.object_id(),
            1,
        )
        .unwrap();
        assert_eq!(proposal.batch_sequence, 0);
        assert_eq!(proposal.signer_set, SignatureSet::empty_ed25519());
        assert_eq!(proposal.accepted_share_ids.len(), 1);

        let other_share_id = [fixture.share.object_id(), second_share.object_id()]
            .into_iter()
            .find(|share_id| *share_id != proposal.accepted_share_ids[0])
            .unwrap();
        let other = super::load_receipt_share_evidence(
            &store,
            2,
            fixture.session.object_id(),
            other_share_id,
        )
        .unwrap();
        let mut alternate_builder = ReceiptBuilder::new(
            CORE_V2,
            2,
            fixture.session.object_id(),
            0,
            [0; 32],
            0,
            U512::ZERO,
        );
        alternate_builder.accept(other).unwrap();
        let alternate = alternate_builder
            .finalize(SignatureSet::empty_ed25519())
            .unwrap();
        super::validate_unsigned_receipt_candidate(&store, 2, &shares, &receipts, &alternate)
            .unwrap();
        assert_ne!(proposal.object_id(), alternate.object_id());

        let first_key = SigningKey::from_bytes(&[10; 32]);
        let first_signature =
            super::sign_receipt_candidate(&store, &first_key, 2, &shares, &receipts, &proposal)
                .unwrap();
        assert_eq!(
            first_signature,
            super::sign_receipt_candidate(&store, &first_key, 2, &shares, &receipts, &proposal)
                .unwrap()
        );
        assert!(
            super::sign_receipt_candidate(&store, &first_key, 2, &shares, &receipts, &alternate)
                .is_err()
        );
        let outsider = SigningKey::from_bytes(&[99; 32]);
        assert!(
            super::sign_receipt_candidate(&store, &outsider, 2, &shares, &receipts, &proposal)
                .is_err()
        );

        let second_key = SigningKey::from_bytes(&[11; 32]);
        let second_signature =
            super::sign_receipt_candidate(&store, &second_key, 2, &shares, &receipts, &proposal)
                .unwrap();
        let mut certified = proposal.clone();
        certified.signer_set =
            assemble_ed25519_set(vec![first_signature, second_signature]).unwrap();
        fixture
            .receipt_roster
            .verify(&certified.signer_set, &certified)
            .unwrap();
        let payload = canonical_bytes(&certified);
        let outbox = DurableGossipOutbox::new(2);
        let intent = match outbox
            .prepare_publication(
                &store,
                GossipTopic::ReceiptBatch,
                certified.object_id(),
                [0; 32],
                &payload,
            )
            .unwrap()
        {
            super::GossipPublicationPreparation::Intent(intent) => intent,
            other => panic!("expected publication intent, got {other:?}"),
        };
        validate_and_store_receipt_batch(&store, 2, &receipts, certified.object_id(), &payload)
            .unwrap();
        assert!(
            store
                .get(
                    &super::network_namespace(super::GOSSIP_PUBLICATION_INTENT_NAMESPACE, 2),
                    &intent,
                )
                .unwrap()
                .is_some()
        );
        drop(receipts);
        drop(shares);
        drop(outbox);
        drop(store);

        let restarted_store = RedbStore::create(&database).unwrap();
        let restarted_shares =
            share_admission(&restarted_store, &fixture, Arc::new(ParentOracle(true)));
        super::revalidate_recovered_shares(&restarted_store, 2, &restarted_shares).unwrap();
        let restarted_receipts = receipt_admission(&restarted_store, &fixture);
        let restarted_outbox = DurableGossipOutbox::new(2);
        assert_eq!(
            super::recover_durable_gossip_outbox(
                &restarted_store,
                2,
                &restarted_outbox,
                &BTreeSet::new(),
                super::GossipOutboxRecoveryProfile {
                    receipt: true,
                    ..Default::default()
                },
            )
            .unwrap(),
            1
        );
        assert!(
            restarted_store
                .get(
                    &super::network_namespace(super::GOSSIP_PUBLICATION_INTENT_NAMESPACE, 2),
                    &intent,
                )
                .unwrap()
                .is_none()
        );
        let locator = super::load_gossip_outbox_locator(&restarted_store, 2, 1)
            .unwrap()
            .unwrap();
        assert_eq!(locator.topic, GossipTopic::ReceiptBatch);
        assert_eq!(locator.object_id, certified.object_id());
        super::validate_unsigned_receipt_candidate(
            &restarted_store,
            2,
            &restarted_shares,
            &restarted_receipts,
            &proposal,
        )
        .unwrap();
        assert_eq!(
            super::sign_receipt_candidate(
                &restarted_store,
                &first_key,
                2,
                &restarted_shares,
                &restarted_receipts,
                &proposal,
            )
            .unwrap()
            .signer_pubkey,
            first_key.verifying_key().to_bytes()
        );
        assert!(
            super::sign_receipt_candidate(
                &restarted_store,
                &first_key,
                2,
                &restarted_shares,
                &restarted_receipts,
                &alternate,
            )
            .is_err()
        );
    }

    fn independent_fixture_share(fixture: &ShareValidationArtifacts) -> ShareV2 {
        let mut share = fixture.share.clone();
        let mut miner = MinerHeader {
            nonce: share.nonce.checked_add(1).unwrap(),
            time: share.ntime,
            prev_block: fixture.body.template_core.hns_parent_hash,
            tree_root: fixture.body.tree_root,
            mask_hash: fixture.session.mask_hash,
            extra_nonce: share.extra_nonce,
            reserved_root: fixture.body.reserved_root,
            witness_root: fixture.body.witness_root,
            merkle_root: fixture.body.merkle_root,
            version: fixture.body.template_core.block_version,
            bits: fixture.body.template_core.bits,
        };
        while miner.share_hash() > fixture.session.capture_target.0 {
            miner.nonce = miner.nonce.checked_add(1).unwrap();
        }
        share.nonce = miner.nonce;
        share.raw_share_hash = miner.share_hash();
        share.operator_signature = sign_object(&SigningKey::from_bytes(&[42; 32]), 2, &share);
        share
    }

    #[test]
    fn payout_snapshot_plan_and_entropy_replacement_are_restart_verified() {
        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        persist_share_context(&store, &fixture);
        let shares = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        validate_and_store_share(
            &store,
            2,
            &shares,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        let receipts = receipt_admission(&store, &fixture);
        let (batch, close) = certified_receipt_and_close(&benchmark, &fixture);
        validate_and_store_receipt_batch(
            &store,
            2,
            &receipts,
            batch.object_id(),
            &canonical_bytes(&batch),
        )
        .unwrap();
        validate_and_store_session_close(
            &store,
            2,
            &receipts,
            close.object_id(),
            &canonical_bytes(&close),
        )
        .unwrap();

        let first_entropy = [81; 32];
        let replacement_entropy = [82; 32];
        let entropy_height = fixture.parent.parent_height + 1;
        let oracle = Arc::new(MutableCanonicalOracle::default());
        oracle.set(entropy_height, first_entropy, true);
        let admission = payout_admission(&store, &fixture, oracle.clone(), [83; 32]);
        let (snapshot, first_plan) =
            certified_snapshot_and_plan(&benchmark, &fixture, &close, first_entropy, [83; 32]);

        // A settlement threshold cannot substitute an arbitrary work window,
        // anchor, or unevidenced service credit for exact receipt-derived
        // accumulation.
        for mut inconsistent in [
            {
                let mut candidate = snapshot.clone();
                candidate.work_window_target = U512([1; 64]);
                candidate
            },
            {
                let mut candidate = snapshot.clone();
                candidate.close_anchor_height += 1;
                candidate
            },
            {
                let mut candidate = snapshot.clone();
                candidate.service_buckets = vec![ServiceBucketLeaf {
                    bucket_id: fixture.payout_bucket.object_id(),
                    operator_pubkey: fixture.payout_bucket.operator_pubkey,
                    hns_address_version: fixture.payout_bucket.hns_address_version,
                    hns_address_hash: fixture.payout_bucket.hns_address_hash.clone(),
                    certified_service_credit: U512([1; 64]),
                }];
                candidate.service_set_root = merkle_root(&[close.object_id()]);
                candidate
            },
        ] {
            inconsistent.signer_set = benchmark.certify_settlement(&inconsistent);
            assert!(
                validate_and_store_payout_snapshot(
                    &store,
                    2,
                    &admission,
                    inconsistent.object_id(),
                    &canonical_bytes(&inconsistent),
                )
                .is_err()
            );
        }
        validate_and_store_payout_snapshot(
            &store,
            2,
            &admission,
            snapshot.object_id(),
            &canonical_bytes(&snapshot),
        )
        .unwrap();
        for (entropy_start, prior_beacon) in [
            (snapshot.close_anchor_height + 1, [84; 32]),
            (snapshot.close_anchor_height + 2, [83; 32]),
        ] {
            let mut inconsistent = build_payout_plan(
                &snapshot,
                entropy_start,
                vec![first_entropy],
                prior_beacon,
                payout_profile(),
                SignatureSet::empty_ed25519(),
            )
            .unwrap();
            inconsistent.signer_set = benchmark.certify_settlement(&inconsistent);
            assert!(
                validate_and_store_payout_plan(
                    &store,
                    2,
                    &admission,
                    inconsistent.object_id(),
                    &canonical_bytes(&inconsistent),
                )
                .is_err()
            );
        }
        validate_and_store_payout_plan(
            &store,
            2,
            &admission,
            first_plan.object_id(),
            &canonical_bytes(&first_plan),
        )
        .unwrap();

        let commitment = CoinbaseCommitmentV2 {
            protocol_version: CORE_V2,
            network_id: 2,
            template_core_id: [79; 32],
            payout_snapshot_id: snapshot.object_id(),
            payout_plan_id: first_plan.object_id(),
            plan_sequence: first_plan.plan_sequence,
            operator_key_hash: [80; 32],
            flags: 0,
        };
        let subsidy = 1_000u64;
        let mut canonical_payment = HsdCanonicalPaymentBlock {
            height: entropy_height + 1,
            hash: hex::encode([90; 32]),
            previous_block_hash: hex::encode(first_entropy),
            commitment: Some(hex::encode(commitment.encode())),
            ambiguous_commitments: false,
            subsidy: subsidy.to_string(),
            coinbase_input_count: 1,
            coinbase_outputs: vec![HsdCoinbaseOutput {
                value: subsidy.to_string(),
                address_version: fixture.payout_bucket.hns_address_version,
                address_hash: hex::encode(&fixture.payout_bucket.hns_address_hash),
                covenant_type: 0,
                covenant_items: 0,
            }],
        };
        assert_eq!(
            recognized_plan_payment(
                &store,
                2,
                &admission.state.lock().unwrap(),
                payout_profile(),
                &canonical_payment,
            )
            .unwrap(),
            Some(CanonicalPlanPaymentBinding {
                plan_sequence: first_plan.plan_sequence,
                payout_plan_id: first_plan.object_id(),
                payout_snapshot_id: snapshot.object_id(),
            })
        );
        canonical_payment.coinbase_outputs[0].value = (subsidy - 1).to_string();
        assert_eq!(
            recognized_plan_payment(
                &store,
                2,
                &admission.state.lock().unwrap(),
                payout_profile(),
                &canonical_payment,
            )
            .unwrap(),
            None
        );

        // A signed snapshot whose buckets do not sum to its stated work is
        // rejected independently of the settlement threshold signature.
        let mut inconsistent = snapshot.clone();
        inconsistent.actual_work_in_window = U512::ZERO;
        inconsistent.signer_set = benchmark.certify_settlement(&inconsistent);
        assert!(
            validate_and_store_payout_snapshot(
                &store,
                2,
                &admission,
                inconsistent.object_id(),
                &canonical_bytes(&inconsistent)
            )
            .is_err()
        );

        // A reorganization invalidates the old entropy and permits exactly
        // one newly deterministic, threshold-signed replacement plan.
        oracle.set(entropy_height, first_entropy, false);
        oracle.set(entropy_height, replacement_entropy, true);
        let (_, replacement) = certified_snapshot_and_plan(
            &benchmark,
            &fixture,
            &close,
            replacement_entropy,
            [83; 32],
        );
        validate_and_store_payout_plan(
            &store,
            2,
            &admission,
            replacement.object_id(),
            &canonical_bytes(&replacement),
        )
        .unwrap();
        assert_eq!(
            admission.state.lock().unwrap().canonical_plans.get(&0),
            Some(&replacement)
        );

        drop(admission);
        let recovered = recover_payout_state(
            &store,
            2,
            &fixture.receipt_roster,
            &fixture.settlement_roster,
            payout_policy(&fixture, [83; 32]),
            oracle.as_ref(),
        )
        .unwrap();
        assert_eq!(recovered.snapshots, vec![snapshot]);
        assert_eq!(recovered.canonical_plans.get(&0), Some(&replacement));
    }

    #[test]
    fn hns_reconciliation_waits_for_late_exact_payout_evidence() {
        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        persist_share_context(&store, &fixture);
        let shares = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        validate_and_store_share(
            &store,
            2,
            &shares,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        let receipts = receipt_admission(&store, &fixture);
        let (batch, close) = certified_receipt_and_close(&benchmark, &fixture);
        validate_and_store_receipt_batch(
            &store,
            2,
            &receipts,
            batch.object_id(),
            &canonical_bytes(&batch),
        )
        .unwrap();
        validate_and_store_session_close(
            &store,
            2,
            &receipts,
            close.object_id(),
            &canonical_bytes(&close),
        )
        .unwrap();

        let entropy_hash = [131; 32];
        let prior_beacon = [132; 32];
        let entropy_height = fixture.parent.parent_height + 1;
        let payment_height = entropy_height + 1;
        let payment_hash = [133; 32];
        let oracle = Arc::new(MutableCanonicalOracle::default());
        oracle.set(entropy_height, entropy_hash, true);
        oracle.set(payment_height, payment_hash, true);
        let admission = payout_admission(&store, &fixture, oracle.clone(), prior_beacon);
        let (snapshot, plan) =
            certified_snapshot_and_plan(&benchmark, &fixture, &close, entropy_hash, prior_beacon);
        validate_and_store_payout_snapshot(
            &store,
            2,
            &admission,
            snapshot.object_id(),
            &canonical_bytes(&snapshot),
        )
        .unwrap();

        let commitment = CoinbaseCommitmentV2 {
            protocol_version: CORE_V2,
            network_id: 2,
            template_core_id: [134; 32],
            payout_snapshot_id: snapshot.object_id(),
            payout_plan_id: plan.object_id(),
            plan_sequence: plan.plan_sequence,
            operator_key_hash: [135; 32],
            flags: 0,
        };
        let subsidy = 1_000u64;
        let source = MutablePaymentBlockSource::default();
        source.set_block(HsdCanonicalPaymentBlock {
            height: payment_height,
            hash: hex::encode(payment_hash),
            previous_block_hash: hex::encode(entropy_hash),
            commitment: Some(hex::encode(commitment.encode())),
            ambiguous_commitments: false,
            subsidy: subsidy.to_string(),
            coinbase_input_count: 1,
            coinbase_outputs: vec![HsdCoinbaseOutput {
                value: subsidy.to_string(),
                address_version: fixture.payout_bucket.hns_address_version,
                address_hash: hex::encode(&fixture.payout_bucket.hns_address_hash),
                covenant_type: 0,
                covenant_items: 0,
            }],
        });

        // The block identity is durable, but its payment classification is not
        // final until the exact certified plan arrives. Do not append a false
        // no-payment event that a later gossip delivery could contradict.
        assert!(
            reconcile_hns_once(&store, 2, &admission, &source, Some(payment_height), 1,).is_err()
        );
        assert!(admission.state.lock().unwrap().canonical_events.is_empty());
        assert!(
            ProtocolJournal::new(&store)
                .load(
                    ProtocolRecordKind::CanonicalPlanPayment,
                    &0u64.to_le_bytes(),
                )
                .unwrap()
                .is_none()
        );

        validate_and_store_payout_plan(
            &store,
            2,
            &admission,
            plan.object_id(),
            &canonical_bytes(&plan),
        )
        .unwrap();
        let summary =
            reconcile_hns_once(&store, 2, &admission, &source, Some(payment_height), 1).unwrap();
        assert!(summary.complete);
        assert_eq!(summary.appended_events, 1);
        let encoded = ProtocolJournal::new(&store)
            .load(
                ProtocolRecordKind::CanonicalPlanPayment,
                &0u64.to_le_bytes(),
            )
            .unwrap()
            .unwrap();
        let decoded = decode_canonical_payment_event(2, &encoded).unwrap();
        assert_eq!(
            decoded.event.paid_plan,
            Some(CanonicalPlanPaymentBinding {
                plan_sequence: plan.plan_sequence,
                payout_plan_id: plan.object_id(),
                payout_snapshot_id: snapshot.object_id(),
            })
        );
        assert_eq!(decoded.legacy_paid_plan_sequence, None);

        let recovered = recover_payout_state(
            &store,
            2,
            &fixture.receipt_roster,
            &fixture.settlement_roster,
            payout_policy(&fixture, prior_beacon),
            oracle.as_ref(),
        )
        .unwrap();
        assert_eq!(recovered.payments.current_payable(), None);
        assert_eq!(recovered.canonical_events, vec![decoded.event]);
    }

    #[test]
    fn settlement_role_signing_is_exact_restart_safe_and_entropy_reorg_aware() {
        let directory = secure_tempdir().unwrap();
        let database = directory.path().join(STATE_DATABASE);
        let store = RedbStore::create(&database).unwrap();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        persist_share_context(&store, &fixture);
        let shares = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        validate_and_store_share(
            &store,
            2,
            &shares,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        let receipts = receipt_admission(&store, &fixture);
        let (batch, close) = certified_receipt_and_close(&benchmark, &fixture);
        validate_and_store_receipt_batch(
            &store,
            2,
            &receipts,
            batch.object_id(),
            &canonical_bytes(&batch),
        )
        .unwrap();
        validate_and_store_session_close(
            &store,
            2,
            &receipts,
            close.object_id(),
            &canonical_bytes(&close),
        )
        .unwrap();

        let first_entropy = [121; 32];
        let replacement_entropy = [122; 32];
        let prior_beacon = [123; 32];
        let entropy_height = fixture.parent.parent_height + 1;
        let oracle = Arc::new(MutableCanonicalOracle::default());
        oracle.set(entropy_height, first_entropy, true);
        let admission = payout_admission(&store, &fixture, oracle.clone(), prior_beacon);
        let snapshot = super::derive_expected_payout_snapshots(
            &store,
            2,
            &fixture.receipt_roster,
            &fixture.settlement_roster,
            admission.policy,
        )
        .unwrap()
        .remove(0);
        let snapshot_candidate = super::SettlementCandidate::Snapshot(snapshot.clone());
        let first_key = SigningKey::from_bytes(&[7; 32]);
        let second_key = SigningKey::from_bytes(&[8; 32]);
        let first_snapshot_signature = super::sign_settlement_candidate(
            &store,
            &first_key,
            2,
            &admission,
            &snapshot_candidate,
        )
        .unwrap();
        assert_eq!(
            first_snapshot_signature,
            super::sign_settlement_candidate(
                &store,
                &first_key,
                2,
                &admission,
                &snapshot_candidate,
            )
            .unwrap()
        );
        assert!(
            super::sign_settlement_candidate(
                &store,
                &SigningKey::from_bytes(&[99; 32]),
                2,
                &admission,
                &snapshot_candidate,
            )
            .is_err()
        );
        let mut certified_snapshot = snapshot.clone();
        certified_snapshot.signer_set = assemble_ed25519_set(vec![
            first_snapshot_signature,
            super::sign_settlement_candidate(
                &store,
                &second_key,
                2,
                &admission,
                &snapshot_candidate,
            )
            .unwrap(),
        ])
        .unwrap();
        validate_and_store_payout_snapshot(
            &store,
            2,
            &admission,
            certified_snapshot.object_id(),
            &canonical_bytes(&certified_snapshot),
        )
        .unwrap();

        let plan = build_payout_plan(
            &certified_snapshot,
            entropy_height,
            vec![first_entropy],
            prior_beacon,
            payout_profile(),
            SignatureSet::empty_ed25519(),
        )
        .unwrap();
        let plan_candidate = super::SettlementCandidate::Plan(plan.clone());
        let first_plan_signature =
            super::sign_settlement_candidate(&store, &first_key, 2, &admission, &plan_candidate)
                .unwrap();
        let mut certified_plan = plan.clone();
        certified_plan.signer_set = assemble_ed25519_set(vec![
            first_plan_signature.clone(),
            super::sign_settlement_candidate(&store, &second_key, 2, &admission, &plan_candidate)
                .unwrap(),
        ])
        .unwrap();
        validate_and_store_payout_plan(
            &store,
            2,
            &admission,
            certified_plan.object_id(),
            &canonical_bytes(&certified_plan),
        )
        .unwrap();
        assert_eq!(
            super::sign_settlement_candidate(&store, &first_key, 2, &admission, &plan_candidate,)
                .unwrap(),
            first_plan_signature
        );

        oracle.set(entropy_height, first_entropy, false);
        oracle.set(entropy_height, replacement_entropy, true);
        let replacement = build_payout_plan(
            &certified_snapshot,
            entropy_height,
            vec![replacement_entropy],
            prior_beacon,
            payout_profile(),
            SignatureSet::empty_ed25519(),
        )
        .unwrap();
        let replacement_candidate = super::SettlementCandidate::Plan(replacement.clone());
        let mut certified_replacement = replacement;
        certified_replacement.signer_set = assemble_ed25519_set(vec![
            super::sign_settlement_candidate(
                &store,
                &first_key,
                2,
                &admission,
                &replacement_candidate,
            )
            .unwrap(),
            super::sign_settlement_candidate(
                &store,
                &second_key,
                2,
                &admission,
                &replacement_candidate,
            )
            .unwrap(),
        ])
        .unwrap();
        validate_and_store_payout_plan(
            &store,
            2,
            &admission,
            certified_replacement.object_id(),
            &canonical_bytes(&certified_replacement),
        )
        .unwrap();
        drop(admission);
        drop(receipts);
        drop(shares);
        drop(store);

        let restarted_store = RedbStore::create(&database).unwrap();
        let restarted = payout_admission(&restarted_store, &fixture, oracle, prior_beacon);
        assert_eq!(
            super::sign_settlement_candidate(
                &restarted_store,
                &first_key,
                2,
                &restarted,
                &snapshot_candidate,
            )
            .unwrap()
            .signer_pubkey,
            first_key.verifying_key().to_bytes()
        );
        assert_eq!(
            restarted.state.lock().unwrap().canonical_plans.get(&0),
            Some(&certified_replacement)
        );
    }

    #[test]
    fn canonical_payment_event_codec_is_bounded_and_exact() {
        let event = CanonicalPaymentEvent {
            sequence: 7,
            action: CanonicalPaymentAction::Connect,
            height: 42,
            block_hash: [1; 32],
            previous_block_hash: [2; 32],
            paid_plan: Some(CanonicalPlanPaymentBinding {
                plan_sequence: 3,
                payout_plan_id: [3; 32],
                payout_snapshot_id: [4; 32],
            }),
        };
        let encoded = encode_canonical_payment_event(2, &event);
        let decoded = decode_canonical_payment_event(2, &encoded).unwrap();
        assert_eq!(decoded.event, event);
        assert_eq!(decoded.legacy_paid_plan_sequence, None);
        assert!(decode_canonical_payment_event(1, &encoded).is_err());
        let mut trailing = encoded;
        trailing.push(0);
        assert!(decode_canonical_payment_event(2, &trailing).is_err());

        let mut legacy_encoder = Encoder::new();
        legacy_encoder.fixed(&super::LEGACY_CANONICAL_PAYMENT_EVENT_MAGIC);
        legacy_encoder.u16(CORE_V2);
        legacy_encoder.u8(2);
        legacy_encoder.u64(event.sequence);
        legacy_encoder.u8(CanonicalPaymentAction::Connect as u8);
        legacy_encoder.u32(event.height);
        legacy_encoder.fixed(&event.block_hash);
        legacy_encoder.fixed(&event.previous_block_hash);
        legacy_encoder.u8(1);
        legacy_encoder.u64(3);
        let legacy = legacy_encoder.into_bytes();
        let decoded_legacy = decode_canonical_payment_event(2, &legacy).unwrap();
        assert_eq!(decoded_legacy.event.paid_plan, None);
        assert_eq!(decoded_legacy.legacy_paid_plan_sequence, Some(3));

        let legacy_plan = PayoutPlanV2 {
            protocol_version: CORE_V2,
            network_id: 2,
            plan_sequence: 3,
            snapshot_id: [4; 32],
            entropy_anchor_start: 1,
            entropy_anchor_count: 1,
            entropy_hashes: vec![[5; 32]],
            prior_beacon: [6; 32],
            plan_seed: [7; 32],
            work_ticket_count: 1,
            service_ticket_count: 0,
            work_winners: vec![[8; 32]],
            service_winners: Vec::new(),
            selection_transcript_hash: [9; 32],
            signer_set: SignatureSet::empty_ed25519(),
        };
        let legacy_plan_id = legacy_plan.object_id();
        let plans = BTreeMap::from([(legacy_plan_id, legacy_plan.clone())]);
        let snapshots = BTreeSet::from([[4; 32]]);
        let normalized = super::normalize_recovered_canonical_payment_event(
            decoded_legacy.clone(),
            &plans,
            &snapshots,
        )
        .unwrap();
        assert_eq!(
            normalized.paid_plan,
            Some(CanonicalPlanPaymentBinding {
                plan_sequence: 3,
                payout_plan_id: legacy_plan_id,
                payout_snapshot_id: [4; 32],
            })
        );
        assert!(
            super::normalize_recovered_canonical_payment_event(
                decoded_legacy.clone(),
                &plans,
                &BTreeSet::new(),
            )
            .is_err()
        );
        let mut alternate = legacy_plan;
        alternate.prior_beacon = [10; 32];
        let mut ambiguous_plans = plans;
        ambiguous_plans.insert(alternate.object_id(), alternate);
        assert!(
            super::normalize_recovered_canonical_payment_event(
                decoded_legacy,
                &ambiguous_plans,
                &snapshots,
            )
            .is_err()
        );

        let invalid_disconnect = CanonicalPaymentEvent {
            action: CanonicalPaymentAction::Disconnect,
            ..event
        };
        assert!(
            decode_canonical_payment_event(
                2,
                &encode_canonical_payment_event(2, &invalid_disconnect)
            )
            .is_err()
        );
    }

    #[test]
    fn canonical_hns_reorg_is_durable_closes_sessions_and_replays_historical_payment() {
        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        persist_share_context(&store, &fixture);

        let shares = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        validate_and_store_share(
            &store,
            2,
            &shares,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        let receipts = receipt_admission(&store, &fixture);
        let (batch, close) = certified_receipt_and_close(&benchmark, &fixture);
        validate_and_store_receipt_batch(
            &store,
            2,
            &receipts,
            batch.object_id(),
            &canonical_bytes(&batch),
        )
        .unwrap();
        validate_and_store_session_close(
            &store,
            2,
            &receipts,
            close.object_id(),
            &canonical_bytes(&close),
        )
        .unwrap();

        let entropy_hash = [81; 32];
        let entropy_height = fixture.parent.parent_height + 1;
        let oracle = Arc::new(MutableCanonicalOracle::default());
        oracle.set(entropy_height, entropy_hash, true);
        let admission = payout_admission(&store, &fixture, oracle.clone(), [82; 32]);
        let (snapshot, plan) =
            certified_snapshot_and_plan(&benchmark, &fixture, &close, entropy_hash, [82; 32]);
        validate_and_store_payout_snapshot(
            &store,
            2,
            &admission,
            snapshot.object_id(),
            &canonical_bytes(&snapshot),
        )
        .unwrap();
        validate_and_store_payout_plan(
            &store,
            2,
            &admission,
            plan.object_id(),
            &canonical_bytes(&plan),
        )
        .unwrap();

        let horizon_parent = [44; 32];
        append_canonical_payment_event(
            &store,
            2,
            &admission,
            CanonicalPaymentEvent {
                sequence: 0,
                action: CanonicalPaymentAction::Connect,
                height: fixture.parent.parent_height,
                block_hash: fixture.parent.parent_hash,
                previous_block_hash: horizon_parent,
                paid_plan: None,
            },
        )
        .unwrap();
        {
            let mut state = admission.state.lock().unwrap();
            state
                .overlay
                .register_parent_certificate(&fixture.parent)
                .unwrap();
            state.overlay.register_session(&fixture.session).unwrap();
        }
        {
            let state = admission.state.lock().unwrap();
            let mut staged = state.clone();
            let mut noncanonical_alternate = build_payout_plan(
                &snapshot,
                entropy_height,
                vec![entropy_hash],
                [98; 32],
                payout_profile(),
                SignatureSet::empty_ed25519(),
            )
            .unwrap();
            noncanonical_alternate.signer_set =
                benchmark.certify_settlement(&noncanonical_alternate);
            staged.entropy.register(&noncanonical_alternate).unwrap();
            assert!(
                super::apply_canonical_payment_event(
                    &mut staged,
                    CanonicalPaymentEvent {
                        sequence: 1,
                        action: CanonicalPaymentAction::Connect,
                        height: entropy_height,
                        block_hash: entropy_hash,
                        previous_block_hash: fixture.parent.parent_hash,
                        paid_plan: Some(CanonicalPlanPaymentBinding {
                            plan_sequence: noncanonical_alternate.plan_sequence,
                            payout_plan_id: noncanonical_alternate.object_id(),
                            payout_snapshot_id: noncanonical_alternate.snapshot_id,
                        }),
                    },
                    Some(&noncanonical_alternate),
                    true,
                )
                .is_err()
            );
        }
        assert!(
            append_canonical_payment_event(
                &store,
                2,
                &admission,
                CanonicalPaymentEvent {
                    sequence: 1,
                    action: CanonicalPaymentAction::Connect,
                    height: entropy_height,
                    block_hash: entropy_hash,
                    previous_block_hash: fixture.parent.parent_hash,
                    paid_plan: Some(CanonicalPlanPaymentBinding {
                        plan_sequence: plan.plan_sequence,
                        payout_plan_id: [99; 32],
                        payout_snapshot_id: snapshot.object_id(),
                    }),
                },
            )
            .is_err()
        );
        assert!(
            ProtocolJournal::new(&store)
                .load(
                    ProtocolRecordKind::CanonicalPlanPayment,
                    &1u64.to_le_bytes(),
                )
                .unwrap()
                .is_none()
        );
        // Simulate the previous sequence-only durable encoding. Recovery must
        // derive its exact IDs from the one immutable plan and snapshot, while
        // all newly appended events use the source-bound encoding.
        let legacy_payment_event = CanonicalPaymentEvent {
            sequence: 1,
            action: CanonicalPaymentAction::Connect,
            height: entropy_height,
            block_hash: entropy_hash,
            previous_block_hash: fixture.parent.parent_hash,
            paid_plan: Some(CanonicalPlanPaymentBinding {
                plan_sequence: plan.plan_sequence,
                payout_plan_id: plan.object_id(),
                payout_snapshot_id: snapshot.object_id(),
            }),
        };
        let mut legacy_encoder = Encoder::new();
        legacy_encoder.fixed(&super::LEGACY_CANONICAL_PAYMENT_EVENT_MAGIC);
        legacy_encoder.u16(CORE_V2);
        legacy_encoder.u8(2);
        legacy_encoder.u64(legacy_payment_event.sequence);
        legacy_encoder.u8(legacy_payment_event.action as u8);
        legacy_encoder.u32(legacy_payment_event.height);
        legacy_encoder.fixed(&legacy_payment_event.block_hash);
        legacy_encoder.fixed(&legacy_payment_event.previous_block_hash);
        legacy_encoder.u8(1);
        legacy_encoder.u64(plan.plan_sequence);
        let legacy_bytes = legacy_encoder.into_bytes();
        {
            let mut state = admission.state.lock().unwrap();
            let mut staged = state.clone();
            super::apply_canonical_payment_event(
                &mut staged,
                legacy_payment_event,
                Some(&plan),
                true,
            )
            .unwrap();
            let event_commitment = super::extend_parent_reorg_event_commitment(
                state.canonical_event_commitment,
                &legacy_bytes,
            );
            ProtocolJournal::new(&store)
                .persist(
                    ProtocolRecordKind::CanonicalPlanPayment,
                    &1u64.to_le_bytes(),
                    &legacy_bytes,
                )
                .unwrap();
            store
                .put(
                    super::PARENT_REORG_REPAIR_NAMESPACE,
                    "2",
                    &super::encode_parent_reorg_repair(
                        2,
                        super::ParentReorgRepairState::Ready {
                            event_count: 2,
                            event_commitment,
                        },
                    ),
                )
                .unwrap();
            staged.canonical_event_commitment = event_commitment;
            *state = staged;
        }
        assert_eq!(
            admission.state.lock().unwrap().payments.current_payable(),
            None
        );

        append_canonical_payment_event(
            &store,
            2,
            &admission,
            CanonicalPaymentEvent {
                sequence: 2,
                action: CanonicalPaymentAction::Disconnect,
                height: entropy_height,
                block_hash: entropy_hash,
                previous_block_hash: fixture.parent.parent_hash,
                paid_plan: None,
            },
        )
        .unwrap();
        append_canonical_payment_event(
            &store,
            2,
            &admission,
            CanonicalPaymentEvent {
                sequence: 3,
                action: CanonicalPaymentAction::Disconnect,
                height: fixture.parent.parent_height,
                block_hash: fixture.parent.parent_hash,
                previous_block_hash: horizon_parent,
                paid_plan: None,
            },
        )
        .unwrap();
        assert_eq!(
            store
                .get(
                    REORG_ORPHAN_PARENT_NAMESPACE,
                    &hex::encode(fixture.parent.object_id())
                )
                .unwrap(),
            Some(3u64.to_le_bytes().to_vec())
        );
        assert_eq!(
            store
                .get(
                    REORG_CLOSED_SESSION_NAMESPACE,
                    &hex::encode(fixture.session.object_id())
                )
                .unwrap(),
            Some(3u64.to_le_bytes().to_vec())
        );
        // Exact historical evidence remains idempotent after closure, but it
        // cannot recreate the hot-state row or receive credit again.
        validate_and_store_share(
            &store,
            2,
            &shares,
            fixture.share.object_id(),
            &canonical_bytes(&fixture.share),
        )
        .unwrap();
        assert!(
            store
                .get(
                    &super::active_share_namespace(2),
                    &super::active_share_key(
                        fixture.session.object_id(),
                        fixture.share.object_id(),
                    ),
                )
                .unwrap()
                .is_none()
        );

        oracle.set(entropy_height, entropy_hash, false);
        drop(admission);
        let recovered = recover_payout_state(
            &store,
            2,
            &fixture.receipt_roster,
            &fixture.settlement_roster,
            payout_policy(&fixture, [82; 32]),
            oracle.as_ref(),
        )
        .unwrap();
        assert_eq!(recovered.canonical_events.len(), 4);
        assert_eq!(
            recovered.canonical_events[1].paid_plan,
            Some(CanonicalPlanPaymentBinding {
                plan_sequence: plan.plan_sequence,
                payout_plan_id: plan.object_id(),
                payout_snapshot_id: snapshot.object_id(),
            })
        );
        assert!(recovered.canonical_plans.is_empty());
        assert_eq!(recovered.payments.current_payable(), None);
        assert!(
            !share_admission(&store, &fixture, Arc::new(ParentOracle(false)))
                .dags
                .lock()
                .unwrap()
                .contains_key(&fixture.session.object_id())
        );
        assert!(
            ProtocolJournal::new(&store)
                .load(
                    ProtocolRecordKind::AcceptedShare,
                    &fixture.share.object_id(),
                )
                .unwrap()
                .is_some()
        );
        assert!(
            receipt_admission(&store, &fixture)
                .sessions
                .lock()
                .unwrap()
                .get(&fixture.session.object_id())
                .is_none()
        );
        assert!(
            store
                .get(
                    &super::active_receipt_head_namespace(2),
                    &super::active_receipt_head_key(fixture.session.object_id()),
                )
                .unwrap()
                .is_none()
        );

        // HNS may later return to the exact old entropy branch. Revalidating
        // the already-durable plan must reactivate it, and restart replay must
        // do the same only for the retained payment's oracle-current exact ID.
        oracle.set(entropy_height, entropy_hash, true);
        let returned = payout_admission(&store, &fixture, oracle.clone(), [82; 32]);
        assert!(returned.state.lock().unwrap().canonical_plans.is_empty());
        validate_and_store_payout_plan(
            &store,
            2,
            &returned,
            plan.object_id(),
            &canonical_bytes(&plan),
        )
        .unwrap();
        append_canonical_payment_event(
            &store,
            2,
            &returned,
            CanonicalPaymentEvent {
                sequence: 4,
                action: CanonicalPaymentAction::Connect,
                height: fixture.parent.parent_height,
                block_hash: fixture.parent.parent_hash,
                previous_block_hash: horizon_parent,
                paid_plan: None,
            },
        )
        .unwrap();
        append_canonical_payment_event(
            &store,
            2,
            &returned,
            CanonicalPaymentEvent {
                sequence: 5,
                action: CanonicalPaymentAction::Connect,
                height: entropy_height,
                block_hash: entropy_hash,
                previous_block_hash: fixture.parent.parent_hash,
                paid_plan: Some(CanonicalPlanPaymentBinding {
                    plan_sequence: plan.plan_sequence,
                    payout_plan_id: plan.object_id(),
                    payout_snapshot_id: snapshot.object_id(),
                }),
            },
        )
        .unwrap();
        drop(returned);
        let branch_returned = recover_payout_state(
            &store,
            2,
            &fixture.receipt_roster,
            &fixture.settlement_roster,
            payout_policy(&fixture, [82; 32]),
            oracle.as_ref(),
        )
        .unwrap();
        assert_eq!(branch_returned.canonical_events.len(), 6);
        assert_eq!(
            branch_returned.canonical_events[5].paid_plan,
            Some(CanonicalPlanPaymentBinding {
                plan_sequence: plan.plan_sequence,
                payout_plan_id: plan.object_id(),
                payout_snapshot_id: snapshot.object_id(),
            })
        );
        assert_eq!(branch_returned.canonical_plans.get(&0), Some(&plan));
        assert_eq!(branch_returned.payments.current_payable(), None);
    }

    #[test]
    fn concurrent_wrappers_reserve_one_durable_work_key() {
        use std::sync::Barrier;

        let directory = secure_tempdir().unwrap();
        let store = RedbStore::create(directory.path().join(STATE_DATABASE)).unwrap();
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        persist_share_context(&store, &fixture);
        let first = fixture.share.clone();
        let second = benchmark.rewrapped_share();
        let work_key = first.work_key();
        let admission = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
        let application = Arc::new(DurableOverlayApplication {
            store,
            network_id: 2,
            parent_admission: None,
            share_admission: Some(admission),
            receipt_admission: None,
            payout_admission: None,
            gossip_forward_tx: None,
            gossip_outbox: None,
        });
        let barrier = Arc::new(Barrier::new(3));
        let handles: Vec<_> = [first.clone(), second.clone()]
            .into_iter()
            .map(|share| {
                let application = application.clone();
                let barrier = barrier.clone();
                std::thread::spawn(move || {
                    barrier.wait();
                    application.validate_and_store_gossip(
                        [0; 32],
                        GossipTopic::Share,
                        share.object_id(),
                        &canonical_bytes(&share),
                    )
                })
            })
            .collect();
        barrier.wait();
        let accepted: Vec<_> = handles
            .into_iter()
            .map(|handle| handle.join().unwrap())
            .collect();
        assert_eq!(accepted.iter().filter(|accepted| **accepted).count(), 1);

        let accepted_id = if accepted[0] {
            first.object_id()
        } else {
            second.object_id()
        };
        assert_eq!(
            ProtocolJournal::new(&application.store)
                .load(ProtocolRecordKind::AcceptedWorkKey, &work_key)
                .unwrap(),
            Some(accepted_id.to_vec())
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn quic_share_receipt_close_snapshot_and_plan_survive_restart() {
        let server_directory = secure_tempdir().unwrap();
        let client_directory = secure_tempdir().unwrap();
        for directory in [&server_directory, &client_directory] {
            overlay_init(vec![
                "--dir".to_owned(),
                directory.path().display().to_string(),
            ])
            .unwrap();
        }
        let benchmark = ShareValidationBenchmark::new();
        let fixture = benchmark.artifacts();
        {
            let store = RedbStore::create(server_directory.path().join(STATE_DATABASE)).unwrap();
            persist_share_context(&store, &fixture);
        }
        let share_id = fixture.share.object_id();
        let share_bytes = canonical_bytes(&fixture.share);
        let rewrapped = benchmark.rewrapped_share();
        let (batch, close) = certified_receipt_and_close(&benchmark, &fixture);
        let batch_bytes = canonical_bytes(&batch);
        let close_bytes = canonical_bytes(&close);
        let entropy_hash = [91; 32];
        let payout_oracle = Arc::new(MutableCanonicalOracle::default());
        payout_oracle.set(fixture.parent.parent_height + 1, entropy_hash, true);
        let (snapshot, plan) =
            certified_snapshot_and_plan(&benchmark, &fixture, &close, entropy_hash, [92; 32]);
        let snapshot_bytes = canonical_bytes(&snapshot);
        let plan_bytes = canonical_bytes(&plan);

        for restart in 0..2 {
            let certificate =
                read_bounded(&server_directory.path().join(QUIC_CERTIFICATE), 64 * 1024).unwrap();
            let private_key =
                read_bounded(&server_directory.path().join(QUIC_PRIVATE_KEY), 64 * 1024).unwrap();
            let store = RedbStore::create(server_directory.path().join(STATE_DATABASE)).unwrap();
            let admission = share_admission(&store, &fixture, Arc::new(ParentOracle(true)));
            let mut receipts = receipt_admission(&store, &fixture);
            receipts.share_dags = admission.dags.clone();
            let payouts = payout_admission(&store, &fixture, payout_oracle.clone(), [92; 32]);
            let (limits, topic_limits) = default_overlay_limits();
            let server = QuicOverlayServer::bind(
                "127.0.0.1:0".parse().unwrap(),
                certificate.clone(),
                private_key,
                load_transport_identity(server_directory.path()).unwrap(),
                2,
                OverlayNode::new(2, limits, topic_limits),
                Arc::new(DurableOverlayApplication {
                    store,
                    network_id: 2,
                    parent_admission: None,
                    share_admission: Some(admission),
                    receipt_admission: Some(receipts),
                    payout_admission: Some(payouts),
                    gossip_forward_tx: None,
                    gossip_outbox: None,
                }),
                QuicTransportLimits::default(),
            )
            .unwrap();
            let address = server.local_addr().unwrap();
            let (shutdown_tx, shutdown_rx) = watch::channel(false);
            let task = tokio::spawn(server.run_until(shutdown_rx));
            let peer = QuicOverlayPeer::connect(
                default_client_bind(address),
                address,
                "localhost",
                certificate,
                load_transport_identity(client_directory.path()).unwrap(),
                2,
                QuicTransportLimits::default(),
            )
            .await
            .unwrap();
            peer.gossip(GossipTopic::Share, share_id, false, 0, share_bytes.clone())
                .await
                .unwrap();
            if restart == 0 {
                assert!(
                    peer.gossip(
                        GossipTopic::Share,
                        rewrapped.object_id(),
                        false,
                        0,
                        canonical_bytes(&rewrapped),
                    )
                    .await
                    .is_err()
                );
            }
            peer.gossip(
                GossipTopic::ReceiptBatch,
                batch.object_id(),
                false,
                0,
                batch_bytes.clone(),
            )
            .await
            .unwrap();
            peer.gossip(
                GossipTopic::SessionClose,
                close.object_id(),
                false,
                0,
                close_bytes.clone(),
            )
            .await
            .unwrap();
            peer.gossip(
                GossipTopic::PayoutSnapshot,
                snapshot.object_id(),
                false,
                0,
                snapshot_bytes.clone(),
            )
            .await
            .unwrap();
            peer.gossip(
                GossipTopic::PayoutPlan,
                plan.object_id(),
                false,
                0,
                plan_bytes.clone(),
            )
            .await
            .unwrap();
            peer.close().await;
            shutdown_tx.send(true).unwrap();
            task.await.unwrap().unwrap();
        }

        let store = RedbStore::create(server_directory.path().join(STATE_DATABASE)).unwrap();
        assert_eq!(
            ProtocolJournal::new(&store)
                .load(ProtocolRecordKind::AcceptedShare, &share_id)
                .unwrap(),
            Some(share_bytes)
        );
        assert!(
            !recover_share_dags(&store, 2)
                .unwrap()
                .contains_key(&fixture.session.object_id())
        );
        let recovered = recover_receipt_sessions(
            &store,
            2,
            &fixture.receipt_roster,
            &fixture.settlement_roster,
        )
        .unwrap();
        assert_eq!(
            recovered.get(&fixture.session.object_id()).unwrap().close,
            Some(close)
        );
        let payouts = recover_payout_state(
            &store,
            2,
            &fixture.receipt_roster,
            &fixture.settlement_roster,
            payout_policy(&fixture, [92; 32]),
            payout_oracle.as_ref(),
        )
        .unwrap();
        assert_eq!(payouts.snapshots, vec![snapshot]);
        assert_eq!(payouts.canonical_plans.get(&0), Some(&plan));
    }

    #[test]
    fn parent_canonical_migration_is_bounded_resumable_and_ignores_losing_siblings() {
        let (admission, first_key, second_key) = parent_migration_fixture(7);
        let first = signed_parent_for_migration(7, &first_key, &second_key, 0, [0; 32], [204; 32]);
        let second = signed_parent_for_migration(
            7,
            &first_key,
            &second_key,
            1,
            first.object_id(),
            [205; 32],
        );
        let third = signed_parent_for_migration(
            7,
            &first_key,
            &second_key,
            2,
            second.object_id(),
            [206; 32],
        );
        let losing_second = signed_parent_for_migration(
            7,
            &first_key,
            &second_key,
            1,
            first.object_id(),
            [207; 32],
        );
        let directory = secure_tempdir().unwrap();
        let database_path = directory.path().join(STATE_DATABASE);
        let store = RedbStore::create(&database_path).unwrap();
        persist_legacy_parent_chain(&store, 7, &[first.clone(), second.clone(), third.clone()]);
        initialize_parent_reorg_repair(&store, 7);
        for parent in [&first, &second, &third] {
            store
                .delete(
                    super::PARENT_ACCEPTED_NAMESPACE,
                    &super::parent_acceptance_key(7, parent.object_id()),
                )
                .unwrap();
        }
        let losing_id = losing_second.object_id();
        ProtocolJournal::new(&store)
            .persist(
                ProtocolRecordKind::ParentCertificate,
                &losing_id,
                &canonical_bytes(&losing_second),
            )
            .unwrap();
        store
            .put(
                super::PARENT_ACCEPTED_NAMESPACE,
                &super::parent_acceptance_key(7, losing_id),
                &super::encode_parent_acceptance(7, 1, losing_id),
            )
            .unwrap();

        let interrupted = super::ensure_parent_canonical_index_with_limits(
            &store,
            7,
            &admission,
            1,
            1,
            super::PARENT_CANONICAL_MIGRATION_PAGE_BYTES,
        )
        .unwrap_err()
        .to_string();
        assert!(interrupted.contains("bounded progress"));
        let namespace = super::parent_canonical_sequence_namespace(7);
        assert_eq!(
            store
                .get(&namespace, &super::parent_canonical_sequence_key(2))
                .unwrap(),
            Some(super::encode_parent_canonical_sequence(
                7,
                super::ParentCanonicalLink {
                    sequence: 2,
                    object_id: third.object_id(),
                },
            ))
        );
        assert!(
            store
                .get(&namespace, &super::parent_canonical_sequence_key(1))
                .unwrap()
                .is_none()
        );

        drop(store);
        let restarted = RedbStore::create(&database_path).unwrap();
        let mut completed = false;
        for _ in 0..8 {
            match super::ensure_parent_canonical_index_with_limits(
                &restarted,
                7,
                &admission,
                1,
                1,
                super::PARENT_CANONICAL_MIGRATION_PAGE_BYTES,
            ) {
                Ok(()) => {
                    completed = true;
                    break;
                }
                Err(error) => {
                    assert!(error.to_string().contains("bounded progress"));
                    let state = super::decode_parent_canonical_migration(
                        7,
                        &restarted
                            .get(super::PARENT_CANONICAL_MIGRATION_NAMESPACE, "7")
                            .unwrap()
                            .unwrap(),
                    )
                    .unwrap();
                    if matches!(
                        state,
                        super::ParentCanonicalMigrationState::Backfill { .. }
                            | super::ParentCanonicalMigrationState::Validate { .. }
                            | super::ParentCanonicalMigrationState::AcceptanceRepair {
                                last: None,
                                ..
                            }
                    ) {
                        for parent in [&first, &second, &third] {
                            assert_eq!(
                                super::load_parent_acceptance(&restarted, 7, parent.object_id(),)
                                    .unwrap(),
                                None
                            );
                        }
                    }
                }
            }
        }
        assert!(completed);
        for parent in [&first, &second, &third] {
            super::validate_parent_canonical_binding(
                &restarted,
                7,
                super::ParentCanonicalLink {
                    sequence: parent.certificate_sequence,
                    object_id: parent.object_id(),
                },
            )
            .unwrap();
            assert_eq!(
                super::load_parent_acceptance(&restarted, 7, parent.object_id()).unwrap(),
                Some(parent.certificate_sequence)
            );
        }
        assert_eq!(
            super::decode_parent_canonical_sequence(
                7,
                &super::parent_canonical_sequence_key(1),
                &restarted
                    .get(&namespace, &super::parent_canonical_sequence_key(1))
                    .unwrap()
                    .unwrap(),
            )
            .unwrap()
            .object_id,
            second.object_id()
        );
        assert_ne!(second.object_id(), losing_id);
        assert_eq!(
            super::decode_parent_canonical_migration(
                7,
                &restarted
                    .get(super::PARENT_CANONICAL_MIGRATION_NAMESPACE, "7")
                    .unwrap()
                    .unwrap(),
            )
            .unwrap(),
            super::ParentCanonicalMigrationState::Ready
        );
    }

    #[test]
    fn parent_canonical_migration_rejects_conflicting_and_missing_evidence() {
        let (admission, first_key, second_key) = parent_migration_fixture(7);
        let first = signed_parent_for_migration(7, &first_key, &second_key, 0, [0; 32], [208; 32]);
        let conflicting = MemoryStore::default();
        persist_legacy_parent_chain(&conflicting, 7, std::slice::from_ref(&first));
        initialize_parent_reorg_repair(&conflicting, 7);
        let namespace = super::parent_canonical_sequence_namespace(7);
        conflicting
            .put(
                &namespace,
                &super::parent_canonical_sequence_key(0),
                &super::encode_parent_canonical_sequence(
                    7,
                    super::ParentCanonicalLink {
                        sequence: 0,
                        object_id: [209; 32],
                    },
                ),
            )
            .unwrap();
        let error = super::ensure_parent_canonical_index(&conflicting, 7, &admission)
            .unwrap_err()
            .to_string();
        assert!(error.contains("conflicting sequence binding"));
        assert!(
            conflicting
                .get(super::PARENT_CANONICAL_MIGRATION_NAMESPACE, "7")
                .unwrap()
                .is_none()
        );

        let missing_certificate = MemoryStore::default();
        let first_id = first.object_id();
        missing_certificate
            .put(
                PARENT_HEAD_NAMESPACE,
                "7",
                &super::encode_parent_head(0, first_id),
            )
            .unwrap();
        missing_certificate
            .put(
                super::PARENT_ACCEPTED_NAMESPACE,
                &super::parent_acceptance_key(7, first_id),
                &super::encode_parent_acceptance(7, 0, first_id),
            )
            .unwrap();
        let error = super::ensure_parent_canonical_index(&missing_certificate, 7, &admission)
            .unwrap_err()
            .to_string();
        assert!(error.contains("lacks immutable certificate evidence"));

        let missing_acceptance = MemoryStore::default();
        ProtocolJournal::new(&missing_acceptance)
            .persist(
                ProtocolRecordKind::ParentCertificate,
                &first_id,
                &canonical_bytes(&first),
            )
            .unwrap();
        missing_acceptance
            .put(
                PARENT_HEAD_NAMESPACE,
                "7",
                &super::encode_parent_head(0, first_id),
            )
            .unwrap();
        initialize_parent_reorg_repair(&missing_acceptance, 7);
        for expected_phase in [
            super::ParentCanonicalMigrationState::Validate {
                anchor: Some(super::ParentCanonicalLink {
                    sequence: 0,
                    object_id: first_id,
                }),
                last: None,
            },
            super::ParentCanonicalMigrationState::AcceptanceRepair {
                anchor: Some(super::ParentCanonicalLink {
                    sequence: 0,
                    object_id: first_id,
                }),
                last: None,
            },
        ] {
            let error = super::ensure_parent_canonical_index_with_limits(
                &missing_acceptance,
                7,
                &admission,
                1,
                1,
                super::PARENT_CANONICAL_MIGRATION_PAGE_BYTES,
            )
            .unwrap_err()
            .to_string();
            assert!(error.contains("bounded progress"));
            assert_eq!(
                super::load_parent_acceptance(&missing_acceptance, 7, first_id).unwrap(),
                None
            );
            assert_eq!(
                super::decode_parent_canonical_migration(
                    7,
                    &missing_acceptance
                        .get(super::PARENT_CANONICAL_MIGRATION_NAMESPACE, "7")
                        .unwrap()
                        .unwrap(),
                )
                .unwrap(),
                expected_phase
            );
        }
        super::ensure_parent_canonical_index_with_limits(
            &missing_acceptance,
            7,
            &admission,
            1,
            1,
            super::PARENT_CANONICAL_MIGRATION_PAGE_BYTES,
        )
        .unwrap();
        assert_eq!(
            super::load_parent_acceptance(&missing_acceptance, 7, first_id).unwrap(),
            Some(0)
        );
    }

    #[test]
    fn parent_canonical_validation_rejects_broken_predecessor_without_early_acceptance() {
        let (admission, first_key, second_key) = parent_migration_fixture(7);
        let first = signed_parent_for_migration(7, &first_key, &second_key, 0, [0; 32], [240; 32]);
        let second =
            signed_parent_for_migration(7, &first_key, &second_key, 1, [241; 32], [242; 32]);
        let first_link = super::ParentCanonicalLink {
            sequence: 0,
            object_id: first.object_id(),
        };
        let second_link = super::ParentCanonicalLink {
            sequence: 1,
            object_id: second.object_id(),
        };
        let store = MemoryStore::default();
        initialize_parent_reorg_repair(&store, 7);
        let journal = ProtocolJournal::new(&store);
        for parent in [&first, &second] {
            journal
                .persist(
                    ProtocolRecordKind::ParentCertificate,
                    &parent.object_id(),
                    &canonical_bytes(parent),
                )
                .unwrap();
        }
        let namespace = super::parent_canonical_sequence_namespace(7);
        for link in [first_link, second_link] {
            store
                .put(
                    &namespace,
                    &super::parent_canonical_sequence_key(link.sequence),
                    &super::encode_parent_canonical_sequence(7, link),
                )
                .unwrap();
        }
        store
            .put(
                PARENT_HEAD_NAMESPACE,
                "7",
                &super::encode_parent_head(second_link.sequence, second_link.object_id),
            )
            .unwrap();
        let validate = super::ParentCanonicalMigrationState::Validate {
            anchor: Some(second_link),
            last: None,
        };
        store
            .put(
                super::PARENT_CANONICAL_MIGRATION_NAMESPACE,
                "7",
                &super::encode_parent_canonical_migration(7, &validate),
            )
            .unwrap();

        let error = super::ensure_parent_canonical_index_with_limits(
            &store,
            7,
            &admission,
            1,
            16,
            super::PARENT_CANONICAL_MIGRATION_PAGE_BYTES,
        )
        .unwrap_err()
        .to_string();
        assert!(error.contains("losing or disconnected sibling"));
        assert_eq!(
            super::load_parent_acceptance(&store, 7, first_link.object_id).unwrap(),
            None
        );
        assert_eq!(
            super::load_parent_acceptance(&store, 7, second_link.object_id).unwrap(),
            None
        );
        assert_eq!(
            super::decode_parent_canonical_migration(
                7,
                &store
                    .get(super::PARENT_CANONICAL_MIGRATION_NAMESPACE, "7")
                    .unwrap()
                    .unwrap(),
            )
            .unwrap(),
            validate
        );
    }

    #[test]
    fn ready_parent_recovery_fails_closed_on_oracle_and_head_corruption() {
        let (admission, first_key, second_key) = parent_migration_fixture(7);
        let parent = signed_parent_for_migration(7, &first_key, &second_key, 0, [0; 32], [243; 32]);
        let parent_id = parent.object_id();
        let store = MemoryStore::default();
        initialize_parent_reorg_repair(&store, 7);
        validate_and_store_parent(&store, 7, &admission, parent_id, &canonical_bytes(&parent))
            .unwrap();
        let expected_head = super::encode_parent_head(0, parent_id);

        let rejecting = ParentAdmission {
            roster: admission.roster.clone(),
            oracle: Arc::new(ParentOracle(false)),
        };
        let error = recover_parent_head(&store, 7, &rejecting)
            .unwrap_err()
            .to_string();
        assert!(error.contains("rejected the ready canonical parent head"));
        assert_eq!(
            store.get(PARENT_HEAD_NAMESPACE, "7").unwrap(),
            Some(expected_head)
        );

        store
            .put(
                PARENT_HEAD_NAMESPACE,
                "7",
                &super::encode_parent_head(1, parent_id),
            )
            .unwrap();
        let error = recover_parent_head(&store, 7, &admission)
            .unwrap_err()
            .to_string();
        assert!(error.contains("lacks its durable head binding"));
        assert_eq!(
            super::load_parent_acceptance(&store, 7, parent_id).unwrap(),
            Some(0)
        );
    }

